window.__D("text/maamarei-admur-hazaken/c008",{"p":[[2100990229,"ודרום כו' ובכל סטר כלול מג' הרי י\"ב כמבואר בזוהר בפ' פקודי כמו דגל<sup data-n=\"4337\">58</sup> מחנה ראובן תימנה הוא בבחי' החסד ודגל מחנה<sup data-n=\"4338\">59</sup> יהודה מזרחה בבחי' החכמה וכיוצא בזה בשאר הדגלים וכידוע שזהו פי' בשם<sup data-n=\"4339\">60</sup> אלקינו נדגול פי' בשם זה דאלקינו דוקא להיותו בבחי' מל' נדגול בבחי' ד'<sup data-n=\"4340\">61</sup> דגלים שהן ד' מחנות שכינה למעלה כידוע והרי כבר יש כאן ד' פרטים וכאו\"א מיוחד בפ\"ע כי דגל מחנה יהודה נבדל לגמרי מדגל מחנה ראובן כו' אבל בחי' ההתכללות מכולם שהוא ענין בחי' ו\"ק שבמל' בכללו' יחד אין זה אלא למעלה דוקא והוא בבחי' ז\"א דאצי' שכוללם יחד כמ\"ש הנה<sup data-n=\"4341\">62</sup> מקום אתי כו' וכמ\"ש לך<sup data-n=\"4342\">63</sup> הוי' הגדולה והגבור' כו' והטעם הוא לפי שבו\"ק דז\"א דוקא יש הארת אור אבא שכולל כל התכללות מפני בחי' הביטול דשם מ\"ה שבחכמה כו' וכמ\"ש במ\"א וד\"ל. וזהו הטעם שלא הי' נצחון מלחמת מדין כ\"א ע\"י משה להיותו מבחי' אור אבא שכולל כל ו\"ק דז\"א וכמ\"ש בעצמו<sup data-n=\"4343\">64</sup> ת\"ר אלף רגלי אשר אנכי בקרבו כלומר שכוללם יחד ע\"כ ביכולתו דוקא הי' לעשות בחי' ההתכללו' מכללו' נ\"י יחד דוקא וכמו שאמר החלצו דכולכם משמע כנ\"ל וד\"ל.\n<b>והמופת</b> לכל זה ממה שמצינו בדור שאחר יהושע שלא הי' בהם בחי' ההתכללו' אלא בבחי' הפרט כענין הדגלים הנ\"ל שהרי נא' ויהי<sup data-n=\"4344\">65</sup> אחר מות יהושע וישאלו בנ\"י בה' מי יעלה ויאמר ה' יהודה יעלה כו' יהודה לבדו וכן בבית יוסף נא' ג\"כ שהם לבדם עשו מלחמה וכן עשה כל שבט מלחמה בפ\"ע ולא עשו כללו' נ\"י מלחמה מפני שנתמעט מהם אור אבא הכוללם יחד גם בימי יהושע אך מפני שסמך משה ידיו עליו קיבל הארת משה כי פני<sup data-n=\"4345\">66</sup> משה כפני חמה ופני יהושע כפני לבנה וע\"כ אמרו ליהושע אך יהי'<sup data-n=\"4346\">67</sup> ה' עמך כאשר הי' עם משה דוקא כו' אבל אחר יהושע נעשו בבחי' הפירוד ולא הי' בהם בחי' ההתכללו' כו' כי נסתלק מהם בחי' אור אבא לגמרי כו' ובכל זה מובן בתוס' ביאור למ\"ש וידבר משה אל העם החלצו כו' אחר שאמר נקום נקמת כו' ואחר תאסף כו' וד\"ל.",[["4337","58","<b>דגל מחנה ראובן תימנה</b>: ראה במדבר ב, י."],["4338","59","<b>מחנה יהודה מזרחה</b>: ראה במדבר ב, ג."],["4339","60","<b>בשם אלקינו נדגול</b>: תהלים כ, ו."],["4340","61","<b>ד' דגלים. . . מחנות שכינה</b>: ראה זהר במדבר קיח, ב. ביאורי הזוהר שם פה, א."],["4341","62","<b>הנה מקום אתי</b>: שמות לג, כא."],["4342","63","<b>לך ה' הגדולה</b>: דברי הימים-א כט, יא."],["4343","64","<b>ת\"ר אלף רגלי</b>: בהעלותך יא, כא. וראה סה\"מ תקס\"ה ח\"ב ע' תשי ואילך. וס\"ע תש\"כ ואילך."],["4344","65","<b>ויהי אחרי מות יהושע</b>: שופטים א, א."],["4345","66","<b>פני משה כפני חמה</b>: בבא בתרא עה, א. זח\"א כח, א."],["4346","67","<b>יהי' ה' עמך כאשר הי' עם משה</b>: יהושע א, יז."]]],[2100990230,"<h3>נוסח שני: לתת נקמת הוי' במדין</h3>\n&lt;שא&gt;\n\nלתת<sup data-n=\"4347\">1</sup> נקמת<sup data-n=\"4348\">2</sup> הוי' במדין כו' אלף למטה לכל מטות כו' וצלה\"ב מהו נקמת הוי\"ה ומהו לכל מטות הול\"ל ממטות כו'. והענין כי מדין הוא בחי' מדון היפך הקדושה בבחי' יחוד נעוץ סופן כו' שבקדושה מדרגה זו שרשה מאד נעלה ולכך קודם מ\"ת הי' צריך להכנעת כהן מדין שאמר עתה<sup data-n=\"4349\">3</sup> ידעתי כו' דהנה תורה<sup data-n=\"4350\">4</sup> נק' שלום כי בשעת<sup data-n=\"4351\">5</sup> מ\"ת פתחו כולם ואמרו ה'<sup data-n=\"4352\">6</sup> עוז לעמו כו' או<sup data-n=\"4353\">7</sup> יחזיק במעוזי שלום יעשה בפמליא של מעלה יעשה שלום בפמליא של מטה. כי הנה פמליא של מעלה בחי' י\"ה יו\"ד<sup data-n=\"4354\">8</sup> צמצום בחי' ישת<sup data-n=\"4355\">9</sup> חשך סתרו רק גלוי בחי' נקודא ויצא<sup data-n=\"4356\">10</sup> כברק חיצו כו' הוא התפשטות לאורך ורוחב בבחי' השגה והמה ב' מנגדים עכ\"ז הן משתווין יחד כי כולא קמי' כלא כו' וכחשיכה<sup data-n=\"4357\">11</sup> כאורה שגם ההעלם הוא אינו אלא לפנינו אבל לפניו הם גלוים וידועים וכמ\"ש גם<sup data-n=\"4358\">12</sup> חשך לא יחשיך כו' וז\"ש הנסתרות<sup data-n=\"4359\">13</sup> להוי' אלקינו אינון חו\"ב ע\"י התורה דמחכמה<sup data-n=\"4360\">14</sup> נפקת הוי' בחכמה חכמתו ורצונו כו', ושלום בפמליא של מטה יחוד ו\"ה וז\"ש הנגלות ו\"ה נגלות כו' דהיינו שרש ו\"ק לך<sup data-n=\"4361\">15</sup> הוי\"ה הגדולה והגבורה בחי' חסדים וגבו' אשר המה הפכים כמים ואש וארז\"ל עושה<sup data-n=\"4362\">16</sup> שלום במרומיו בין שר של מים כו' שישתחוו חסו\"ג ויתאחדו והיינו ע\"י מה שהאדם עושה למטה האחדות במדות שלו דזה לעו\"ז עשה אלקים שיש אצלו מדות בקדושה ומדות בקליפה חו\"ג שנאה כעס והתפארות והודי' עצמה מסוד הי.\n<b>יש</b> להבין חטא<sup data-n=\"4363\">17</sup> בית ראשון בעד גזל ועריות וש\"ד ע' שנה ובית<sup data-n=\"4364\">18</sup> שני בעד שנאת חנם כמה שני'. הענין כי בירור ז' מדות וכאו\"א כלולה מעשר בגי' ע' והיינו ט' אומות שיתגברו אחר הכבש' שכבשו אותן משה ויהושע תחילה מפני שהשאירו מהם מעט וכמ\"ש הצדוני' כו' אבל בירור בית שני בש\"ח גדולה כ\"כ דהיינו היפוך האחדות דקדושה כו' וצריך להחליף מדותיו לקדושה ועי\"ז יהיה התחברות כמו העני ששונא לבעה\"ב אם לא יתן לו וזה שונאו כי כמים הפנים כו' אבל ע\"י הצדקה מתאחדים וע\"כ מעשה הצדקה שלום כו'.",[["4347","1","<b>לתת נקמת הוי' במדין</b>: הנחת המהרי\"ל. נעתק מכת\"י 1824 נא, ד. הנחת כ\"ק אדה\"א ממאמר זה נדפס לעיל ע' תקצ ד\"ה החלצו מאתכם."],["4348","2","<b>לתת נקמת הוי' במדין</b>: מטות לא, ג."],["4349","3","<b>עתה ידעתי</b>: יתרו יח, יא."],["4350","4","<b>התורה נק' שלום</b>: רמב\"ם הל' חנוכה בסופו. וראה תו\"א סז, ב. קט, ב."],["4351","5","<b>בשעת מ\"ת פתחו כולם</b>: ראה ספרי דברים לג, ב. ועוד."],["4352","6","<b>ה' עוז לעמו</b>: תהלים כט, יא."],["4353","7","<b>או יחזיק במעוזי שלום</b>: ישעי' כז, ה. סנהדרין צט, ב."],["4354","8","<b>יו\"ד צמצום</b>: אגרת התשובה פ\"ד."],["4355","9","<b>ישת חושך סתרו</b>: תהלים יח, יב."],["4356","10","<b>ויצא כברק חיצו</b>: זכרי' ט, יו\"ד."],["4357","11","<b>וכחשיכה כאורה</b>: תהלים קלט, יב."],["4358","12","<b>גם חשך לא יחשיך</b>: תהלים קלט, יב."],["4359","13","<b>הנסתרות להוי' אלקינו אינון חו\"ב</b>: נצבים כט, כח. ע\"פ תקו\"ז בהקדמה ד\"ה פתח אלי'."],["4360","14","<b>דמחכמה נפקת</b>: זח\"ב סב, א. פה, א. קכא, א. זח\"ג פא, א. קפב, א. רסא, א."],["4361","15","<b>לך ה' הגדולה והגבורה</b>: דה\"א כט, יא."],["4362","16","<b>עושה שלום במרומיו בין שר של מים</b>: איוב כה, ב. במדבר רבא פי\"ב ח. תנחומא ויגש ו. זח\"א השמטות רסג, א."],["4363","17","<b>חטא בית ראשון גזל ועריות וש\"ד</b>: ראה הנסמן לעיל ע' תקצא."],["4364","18","<b>ובית שני בעד שנאת חנם</b>: ראה יומא יט, ב. וראה הערת כ\"ק אדמו\"ר בסה\"מ תרנ\"ט ע' סז."]]],[2100990231,"<b>וכן</b> תפילין הוקשה<sup data-n=\"4365\">19</sup> כל התורה לתפילין שקלף גשמי מתאחד עם מוחין חו\"ב כו' ועד\"ז בכל המצות וכן מוחא ולבא הן הפכים וצ\"ל המוח שליט שלא יהא הלב עומד ומתפעל בענין אהבה בחי' יש אני אוהב כו' ויש אני נאהב כו' אלא בבחי' ובכל נפשך ביטול כי אליך<sup data-n=\"4366\">20</sup> הוי' נפשי אשא, מפני שאתה עתיד לטלה ממני, והן הן הנק' נסתרות והוא מ\"ש נק' בשם הוי\"ה וכתי' כי<sup data-n=\"4367\">21</sup> שם הוי' נק' עליך ויראו ממך כו', ותו\"מ בחי' נגלות לנו, ואמנם כדי שיהי' התורה צ\"ל שלום וזהו הכנעת כהן מדין, פתחו כולם ואמרו ה' יברך את עמו בשלום.\n<b>וזהו</b> החלצו מאתכם על מדין לתת נקמת הוי', כי כל אדם צריך לעמוד במלחמה בעד שם הוי' המורה על יחוד אלף למטה לכל מטות מטה כלפי חסד ת\"ר אלף נשמות כנגד ת\"ר אלף חשבח ויש י\"ב שבטים ששם עלייה וא\"ו למעלה כו' וד\"ל.",[["4365","19","<b>הוקשה כל התורה לתפילין</b>: ראה קידושין לה, א."],["4366","20","<b>אליך הוי' נפשי אשא</b>: תהלים כה, א."],["4367","21","<b>כי שם הוי' נק' עליך</b>: תבוא כח, יוד."]]],[2100990232,"<h3>נוסח שני: ענין החלצו מאתכם</h3>\n<b>ביאור<sup data-n=\"4368\">1</sup></b>\n<b>ענין</b> החלצו מאתכם תחלצו מבעי' לי' דהא מאתכם משמע ולא כולכם והחלצו משמע כולכם דהא כתי' וידבר<sup data-n=\"4369\">2</sup> משה אל העם לאמר החלצו. אך הענין כי הנה הז'<sup data-n=\"4370\">3</sup> גוים הם הז' מלכים שאחר הבירור הסיגים והפסולת כמו אברהם<sup data-n=\"4371\">4</sup> שיצא ממנו ישמעאל שכבר יצא והוברר ונעשה סיגים וקליפות דהיינו למטה נעשה קליפה אבל לא למעלה, והנה מתחילה הוברר האצי' ומה שלא נכלל באצי' נעשה בריא' והכל בסט' דקדושה בחי' ביטול כי כל קדושה הוא בחי' ביטול רק באצי' הוא ביטול גמור ובריאה הוא יש ובטל כמו וצבא השמים לך משתחוים וכתיב הן<sup data-n=\"4372\">5</sup> שמים לא זכו בעיניו כו' ואף במלאכיו<sup data-n=\"4373\">6</sup> ישים תהלה וכמארז\"ל אפקוהו<sup data-n=\"4374\">7</sup> למט\"ט עד שבהשתלשלות נעשה סיגים ממש וז\"ש נתן<sup data-n=\"4375\">8</sup> עיניו במקדש ראשון והרי פעם אמרו שטן<sup data-n=\"4376\">9</sup> ופנינה לש\"ש נתכוונו אך שניהם אמת כי כך הוא דרך השתלשלות שלמעלה הוא לש\"ש וכל מה שנשתלשל למטה יותר נעשה מקטרג ואמר החכם ירא איוב כו' וכ\"ז הוא ענין הז'",[["4368","1","<b>ביאור</b>: הנחת המהרי\"ל. נעתק מכת\"י 1824 נב, א. נדפס בתוס' הגהות בלקו\"ת מטות פז, א. ראה בהנסמן לעיל ע' תקצ."],["4369","2","<b>וידבר משה אל העם לאמר החלצו</b>: מטות לא, ג."],["4370","3","<b>הז' גוים הם הז' מלכים</b>: ראה גם סה\"מ תקס\"ב ח\"א ע' קסח. תקס\"ה ח\"א ע' תיז. מאמרי אדה\"א דברים ח\"א ע' ג ואילך. לקו\"ש חכ\"א ע' 220 והערה 39 שם."],["4371","4","<b>אברהם שיצא ממנו ישמעאל</b>: ראה פסחים נו, א."],["4372","5","<b>הן שמים לא זכו בעיניו</b>: איוב טו, טו."],["4373","6","<b>במלאכיו ישים תהלה</b>: איוב ד, יח."],["4374","7","<b>אפקוהו למט\"ט</b>: חגיגה טו, א."],["4375","8","<b>נתן עיניו במקדש</b>: סוכה נב, סע\"א."],["4376","9","<b>שטן ופנינה לש\"ש נתכוונו</b>: ב\"ב טז, א."]]],[2100990233,"עממין אך ענין מדין הוא מ\"ש בס\"ד עד<sup data-n=\"4377\">10</sup> לא הוי מתקלא כו' ולא היו משגיחין אפין באפין כו' והוא בחי' אבא וזהו בחי' תהו זת\"ז רה\"ר שלא הי' שייכות לחסד עם גבורה שהחסד הי' חסד שבחסד וגבורה הי' גבורה שבגבורות והתיקון הוא להיות בהתכללות והיינו ע\"י מ\"ה כי השבירה היתה בבחי' ב\"ן עולם הנקודים והם ב' ענינים א' בכלים להיות החסד כלול מגבורה וגבורה מחסד ונמצא שהחסד שבגבורות וגבורה שבחסד קרובים להיות שוים כו' והכל באורות שע\"י רבוי הכלי מחזיק האור יותר שהשבירה היתה מפני מיעוט הכלים ולא היו יכולין לסבול האור בתוכן ועיקר התיקון הוא ע\"י האורות שהאורות הם המחברים וכוללים מפני שנתרבה הארתן ולא עוד אלא דאתחלפו דוכתייהו אור החסד בכלי הגבורה כו' וזהו ענין ימינך<sup data-n=\"4378\">11</sup> ה' נאדרי בכח שמאלא<sup data-n=\"4379\">12</sup> אתכליל בימינא וימינך הוי' תרעץ אויב הוא להיפוך.\n<b>והנה</b> מדין הי' משרש התהו קודם התיקון ולא הי' אפין באפין ולכך בא יתרו קודם מ\"ת כמ\"ש<sup data-n=\"4380\">13</sup> בזהר לאכנעא מלך וכהן כי התורה הוא התקון כמ\"ש ה'<sup data-n=\"4381\">14</sup> יברך את עמו בשלום וצ\"ל ביטול בחי' מדין והנה שרש התיקון הוא גילוי הוי' יו\"ד חכמה בחי' ברק כו' ישת<sup data-n=\"4382\">15</sup> חשך סתרו הוא כתר (אשתא דדליג לטורא חשוכא מל' נכלל בכתר) כי מגלה<sup data-n=\"4383\">16</sup> עמוקות מני חושך שי\"ס שהם בגלוי הוא למעלה בהעלם ג\"כ וכך כל ההתכללות חסד שבחסד כנ\"ל ובנקודים היינו הגילוי הי' בחי' נקודים והשאר בהעלם ומבחי' חשך של הכתר הי' גילוי החכמה כברק ונקרא<sup data-n=\"4384\">17</sup> בזוהר נקודה בהיכלא והיכלא הוא בינה דאימא<sup data-n=\"4385\">18</sup> מקננת בכורסייא ונקרא אלהים<sup data-n=\"4386\">19</sup> חיים ומלך עולם ויש לה התפשטות אור אך החכמה<sup data-n=\"4387\">20</sup> הוא בחי' נקודה בלבד דהיינו כמו למשל בשעה שאדם מעמיק בלימודו ונפל לו שכל חדש שהשכל ההוא אינו אלא נקודה והוא ברק המבריק בתוך רוח בינתו המתפשט באור בהיכלא והמחבר להיות נקודא בהיכלא הוא הדעת כי הדעת<sup data-n=\"4388\">21</sup> עולה עד קרומא דאוירא אויר שלפני הקרום דחפייא על מוחא סתימאה כנ\"ל שהיא מעצמות אור א\"ס כמו במשל להיות נובע השכל מלמעלה מן השכל מלמעלה מן השכל ועי\"ז חבור חו\"ב<sup data-n=\"4389\">22</sup> תרין רעין כו' והוא ענין עסק<sup data-n=\"4390\">23</sup> בתורה לשמה לשמה דתורה להיות התורה בבחי' חכמה והוי\"ו בחכמה כו'",[["4377","10","<b>עד לא הוי' מתקלא</b>: זהר תרומה קעו, ב."],["4378","11","<b>ימינך ה' נאדרי בכח</b>: בשלח טו, ו."],["4379","12","<b>שמאלא אתכליל בימינא</b>: ראה זח\"ג קעו, א. קעח, א-ב. וראה אוה\"ת דרושים לשבועות ע' קצב."],["4380","13","<b>כמ\"ש בזוהר לאכנעא מלך וכהן</b>: ראה זוהר שמות סז, ב."],["4381","14","<b>ה' יברך את עמו בשלום</b>: תהלים כט, יא."],["4382","15","<b>ישת חשך סתרו</b>: תהלים יח, יב."],["4383","16","<b>מגלה עמוקות מני חשך</b>: איוב יב, כב."],["4384","17","<b>ונקרא בזוהר נקודה בהיכלא</b>: זח\"א ו, רע\"א. ראה לקו\"ת ר\"פ ראה יח, ב."],["4385","18","<b>דאימא מקננת בכרסייא</b>: תקו\"ז ת\"ו (כג, א). ע\"ח שער (מז) סדר אבי\"ע פ\"ג. שער (מב) דרושי (כללות) אבי\"ע פי\"ג. תניא פל\"ט."],["4386","19","<b>אלקים חיים ומלך עולם</b>: ירמי' יוד, יוד."],["4387","20","<b>החכמה הוא בחי' נקודה בלבד</b>: ראה תו\"א לך יא, ג. משפטים עח, ד. לקו\"ת חקת סו, ג."],["4388","21","<b>הדעת עולה עד קרומא דאוירא</b>: ראה ד\"ה למען דעת תרס\"ט ע' מב."],["4389","22","<b>חו\"ב תרין ריעין</b>: זח\"ג ד, א."],["4390","23","<b>עסק בתורה לשמה לשמה דתורה</b>: ראה פע\"ח שער הנהגת הלימוד. וראה לקו\"ת שלח מז, ריש ע\"ג. לקו\"ש חכ\"ג ס\"ע 146 ואילך וש\"נ."]]],[2100990234,"כמ\"ש בזה\"ק דוד<sup data-n=\"4391\">24</sup> קשיר אורייתא דלעילא בקוב\"ה אורייתא דלעילא חכ\"ע כי גם חכמה תתאה נק' תורה ואורייתא סתם חכמה סתם אבל אורייתא דלעילא חכ\"ע נקשר בקוב\"ה להיות בה השראת אור א\"ס וזהו או יחזיק במעוזי יעשה שלום לי שלום יעשה לי שבבחי' שלום העליון נעשה שלום התחתון כמ\"ש אל<sup data-n=\"4392\">25</sup> דעות הוי\"ה ב' דיעות דעת עליון המחבר חו\"ב ודעת תחתון המחבר המדות להיות התכללות במדותיו חסד שבגבורה וגבורה שבחסד כי יש גבורה בלא חסד כמו דור<sup data-n=\"4393\">26</sup> המבול שנענשו בשביל חטאם ולא בשביל תיקון שהרי אין להם חלק לעוה\"ב וכן אנשי סדום מבול של אש אין להם חלק לעוה\"ב, וכן מצרים רק באבוד<sup data-n=\"4394\">27</sup> רשעים רינה לעולם שעולם נהנין כו' אבל כי<sup data-n=\"4395\">28</sup> את אשר יאהב ה' יוכיח יסורין של אהבה הן כמו שמרחיצין את הקטן לטובתו כו' ולא בשביל החטא כי החטא נמחל בלא\"ה רק שצריך לתקון ותקון לזה הוא מבחי' התכללות גבורה שבחסד והוא ע\"י מוחין כמו נה\"י דאבא הם מוחין לז\"א וע\"י התורה מביא תוס' מוחין והיינו ע\"י שמתחילה יעשה שלום לי חבור חו\"ב ואח\"כ שלום יעשה לי שמאו\"א נעשה מוחין לז\"א להיות התכללות הו\"ק כו' והנה כך הוא בנפש חו\"ב מוחא ולבא ברשפי אש הלב מתמעט המוח ובמוח מתמעט אש הלב שהם שני הפכים וצ\"ל התכללות להיות המוח שליט על הלב והיינו ע\"י שיהי' הלב נכנע למוח ויתנהג ע\"פ הנהגת המוח להיות ובכל נפשך אליך<sup data-n=\"4396\">29</sup> ה' נפשי אשא והיינו בתורה ואשים<sup data-n=\"4397\">30</sup> דברי בפיך ובצל ידי כסיתיך ועי\"ז ממשיך מן המוח אל הלב כו' ע\"י עסק התורה לשמה גלוי אא\"ס בחכמה כו' והמדות הם עה\"ד טו\"ר כי בחז' דז\"א מסתיים יסוד אימא כו' והתכללות המדות להיות כלולים בטוב הוא ע\"י התורה שהיא להבדיל<sup data-n=\"4398\">31</sup> בין הטמא ובין הטהור כו' והוא המברר כנ\"ל ובירור המדות הוא ע\"י מוחין כי בתוס' מוחין נעשה התכללות ומוחין נמשכו מבחי' אבא לכן כתיב נקום נקמת הוי\"ה מאת המדינים אחר תאסף כו' שלא הי' יכול להיות מלחמה זו רק בימי משה לכן אף שנקנסה עליו עלה<sup data-n=\"4399\">32</sup> אל הר העברים כו' מ\"מ המתינו לו עד שינקום והיינו מפני כי משה<sup data-n=\"4400\">33</sup> יסוד אבא ספרא<sup data-n=\"4401\">34</sup> רבא וירא<sup data-n=\"4402\">35</sup> ראשית לו (אלא שזכה לבינה והוצרך להיות התקון דווקא ע\"י כו') כי מדין הוא מבחי' הפירוד שקודם התיקון עד לא הוו אפין באפין שלכן אריכות הגלות הזה, שבחורבן בית ראשון ע\"י שהי' מז' עממים ז' מלכי' שאחר התיקון שהי' כלים לפי הכלי כך הוא התיקון הגבול ימי<sup data-n=\"4403\">36</sup> שנותינו בהם ע' שנים משא\"כ שרש",[["4391","24","<b>דוד קשיר אורייתא דלעילא בקוב\"ה</b>: זח\"ג רכב, ב. וראה אוה\"ת שבועות ע' קעז."],["4392","25","<b>אל דיעות ה' ב' דיעות</b>: שמואל-א ב, ג. וראה מאמרי אדה\"א ויקרא ח\"א ע' רסב. וש\"נ."],["4393","26","<b>דור המבול. . אין להם חלק לעוה\"ב</b>: ראה סנהדרין קז, ב."],["4394","27","<b>באבוד רשעים רינה</b>: משלי יא, י."],["4395","28","<b>כי את אשר יאהב ה' יוכיח</b>: משלי ג, יב."],["4396","29","<b>אליך ה' נפשי אשא</b>: תהלים כה, א."],["4397","30","<b>ואשים דברי בפיך</b>: ישעי' נא, טז."],["4398","31","<b>להבדיל בין הטמא ובין הטהור</b>: ע\"פ שמיני יא, טז."],["4399","32","<b>עלה אל הר העברים</b>: פינחס כז, יב."],["4400","33","<b>משה יסוד אבא</b>: לקו\"ת מהאריז\"ל פ' שמות. וראה ע\"ח (שער הארת המעיין זו\"ן) של\"ב, פ\"ב. לקו\"ש ח\"ו ע' 246."],["4401","34","<b>ספרא רבא</b>: תרגום אונקלוס ברכה לג, כא."],["4402","35","<b>וירא ראשית לו</b>: ברכה לג, כא."],["4403","36","<b>ימי שנותינו בהם ע' שנה</b>: תהלים צ, י."]]],[2100990235,"התיקון שהי' מעולם התהו עולם התיקון שלפני זה צריך שיהי' זמן ארוך כו' וצ\"ל בחי' משה יס\"א מקור התורה שכל התורה הוא תורת משה וקודם מ\"ת בא יתרו להכניע א\"ע כי ה' יברך את עמו בשלום אתעדל\"ע שלפני אתעדל\"ת כנ\"ל וזהו נקמת הוי' כי קודם התקון בעולם התהו לא היו שמות אלו אהי' הוי' אלא קראן בשמות נוכראן כו' כמ\"ש בזהר, לכל מטות ב\"י והחלצו כולכם שכולם היו צריכים להיות מבחי' התכללות שלכן הי' ע\"י משה שבימי משה הי' המלחמות בכללות ישראל ביחד משא\"כ אח\"כ כתיב יהודה<sup data-n=\"4404\">37</sup> יעלה כו' שלא הי' ביחד, כי להיות התכללות כללות ישראל שהם ו\"ק דז\"א מחנה<sup data-n=\"4405\">38</sup> יהודה מזרחה כו' ומחנה ראובן תימנה כו' ובשם<sup data-n=\"4406\">39</sup> אלהינו נדגול כו' הוא ע\"י מוחין דאבא שמשם הוא התכללות יעשה שלום לי וכן שלום יעשה לי כו' וד\"ל.",[["4404","37","<b>יהודה יעלה</b>: שופטים א, ב."],["4405","38","<b>מחנה יהודה מזרחה</b>: במדבר ב, ג ואילך."],["4406","39","<b>ובשם אלקינו נדגול</b>: תהלים כ, ו."]]],[2100990236,"<h3>זוהר פינחס פתח ר' חייא ישבעו עצי הוי'</h3>\n<b></b><b>שבת פ' מטות מסעי בעזר\"ה </b>\nשבת פ' מטות מסעי\n(זוהר פ' פנחס דרי\"ז ע\"א)\nפתח<sup data-n=\"4407\">1</sup> ר' חייא ישבעו<sup data-n=\"4408\">2</sup> עצי הוי' ארזי לבנון אשר נטע, מה כתיב לעילא ויין<sup data-n=\"4409\">3</sup> ישמח לבב אנוש וכו' מצמיח<sup data-n=\"4410\">4</sup> חציר לבהמה כו' אלין אינון שיתין אלף רבוא דמלאכין שליחן דאתבריאו ביומא תניינא דבראשית וכולא אשא מלהטא אלין אינון חציר בגין דצמחי כחציר דא דכל יומא ויומא אתקצירו השתא ולבתר צמחין ומהדרין כמלקדמין הה\"ד יודע<sup data-n=\"4411\">5</sup> צדיק נפש בהמתו ע\"כ. פי' עד\"מ החציר הנק' שחת כידוע בגמ' דשבת<sup data-n=\"4412\">7</sup> כמו הקוצר<sup data-n=\"4413\">6</sup> לשחת וכן מאן דקטיל אספסתא כו' שהחציר הוא שקוצרין את העשב הגדל מעט וחוזר וגדל וחוזרי' וקוצרין אותו וכן עושין פעמי' הרבה כדאיתא<sup data-n=\"4414\">8</sup> בב\"ב ונמצא קצירתו גורמת גידולו שחוזר ומצמיח מחדש ולכך חייב משום קוצר ומשום נוטע כו' וזהו פי' הפשוט בפסוק מצמיח חציר לבהמה לפי שהחציר הנ\"ל עיקרו למאכל בהמה וקוצרי' אותו בכל יום למאכל בהמה ועי\"ז חוזר וצומח ונעשה מאכל לבהמה ביום השני וכמו שאמר כאן דכל יומא ויומא אתקצירו כו' והנמשל מן כל זה אמר דהיינו שתין אלף רבוא דמלאכין כו' פי' כי יש מלאכי'",[["4407","1","<b>פתח ר' חייא ישבעו עצי הוי'</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק 1025 (פא, ב). הלשון בזהר (בשינוי קצת)."],["4408","2","<b>ישבעו עצי הוי'</b>: תהלים קד, טז."],["4409","3","<b>ויין ישמח לבב אנוש</b>: שם טו."],["4410","4","<b>מצמיח חציר לבהמה</b>: שם יד."],["4411","5","<b>יודע צדיק נפש בהמתו</b>: משלי יב, י."],["4412","7","<b>דשבת. . מאן דקטיל אספסתא</b>: שבת עג, ב."],["4413","6","<b>הקוצר לשחת</b>: ראה פאה פ\"ב מ\"א."],["4414","8","<b>כדאיתא בב\"ב</b>: כח, ב. וע' שם כ, ב. וראה לקו\"ת שה\"ש כה, א. פירוש המלות פו, א."]]],[2100990237,"שמתחדשי' בכל יום וכמאמר יוצר<sup data-n=\"4415\">9</sup> משרתים כו' והענין הוא לפי שהברורי' דנוגה דבי\"ע מתחדשי' בכל יום ויום להיות כי הנה ידוע בענין ז'<sup data-n=\"4416\">10</sup> מלכין קדמאי' דתוהו שנא' בהן וימלוך<sup data-n=\"4417\">11</sup> וימת כו' הרי נפלו בעולמו' הנפרדים והוא בבחי' עה\"ד טו\"ר דנוגה דבי\"ע, וביאור ענין בחי' נוגה ידוע להיות כי באצי' עצמו נא' לא<sup data-n=\"4418\">12</sup> יגורך רע כלל אפי' בתערובו' כל שהוא משום דאיהו<sup data-n=\"4419\">13</sup> וחיוהי וגם גרמוהי חד כו' דגם הכלים דשם הוא בתכלית בחי' הביטול דמ\"ה דז\"א הוא שמלובש בכלים כו' וכמ\"ש במ\"א, אך בעולם הבריאה שאין שם בחי' הביטול כ\"כ ועכ\"פ בבחי' הכלים החיצונים די\"ס דבריא' כבר נראה קצת יש ודבר מה ע\"כ בירידת אור עוד מבחי' כלים החיצוני' יוכל להיו' בחי' יש גמור מעורב טו\"ר והוא בחי' נוגה דבריא'<sup data-n=\"4420\">14</sup> שמיעוטו רע ורובו טוב כו' והמלאכים שמתחדשים שם מאין ליש הגופים שלהם החומרי הוא נלקח מבחי' נוגה שהוא בבחי' יש ממש ומעורב טו\"ר קצת אך בחי' הצורה שלהם נלקח מכלים די\"ס דקדוש' כמ\"ש בע\"ח<sup data-n=\"4421\">15</sup> בשער מ\"ן ומ\"ד וז\"ש עושה<sup data-n=\"4422\">16</sup> מלאכיו רוחו' משרתיו אש לוהט בחי' הרוחו' שלהם מחלק הקדוש' ממש והגופי' שלהם אש לוהט מבחי' גבורו' דנוגה והיינו שאמר כאן וכולהו אשא מלהטא כו' וד\"ל.\n<b>והנה</b> הבירורי' של המלאכי' הללו שמתחדשי' שם הוא כדמיון החציר שנקצר למאכל בהמה כנ\"ל כי הנה בחי' מל' דאצי' הוא בחי' שם ב\"ן<sup data-n=\"4423\">17</sup> בגי' בהמה כידוע וכתיב ורוח<sup data-n=\"4424\">18</sup> הבהמה היא היורדת למטה לברר ברורי' דנוגה כו' וענין אופן הבירור הזה יובן ע\"ד דוגמא ממה שאמרו ז\"ל למה<sup data-n=\"4425\">19</sup> צדיקי' דומין בפני השכינה כנר בפני האבוקה והנר בפני האבוקה ידוע ע\"ד הטבע בענין הביטול והתכללות האור ושלהבת של הנר באבוקה הגדולה עד שנפרדת מן הפתילה ונכבית ועולה ונכללת באבוקה ממש והטעם הוא לעוצם גילוי השלהבת הגדולה של האבוקה שהיא מקור כל הניצוצו' הקטני' לכך &lt;שב&gt;\nנשאבו ונכללו בה כל ניצוצי' קטני' שעומדי' סמוך לה כו' והנמשל בצדיקי' בפני גילוי אור השכינה מובן ג\"כ עד\"מ זה וכדוגמא זו ג\"כ יובן ענין הברורי' של המלאכי' הנ\"ל כי הרי נפש הצורה שלהם שרשה הוא מבחי' מל' דאצי' כנ\"ל שנלקחת מכלים החיצוני' די\"ס דבריא' ואע\"פ שהחומר שלהם אש לוהט מגבורו' דנוגה הרי מתפרד הצורה מן החומר ונכלל ובטל במקורו והוא שם ב\"ן דמלכות בגי' בהמה והיינו מפני המקור שיורד גילוי אור אלקי עליהם אזי ממילא",[["4415","9","<b>יוצר משרתים</b>: ברכת ק\"ש."],["4416","10","<b>ז' מלכין קדמאי' דתהו</b>: נסמן לעיל (ח\"א) ע' תח."],["4417","11","<b>וימלוך וימת</b>: וישלח לו, לב ואילך."],["4418","12","<b>לא יגורך רע</b>: תהלים ה, ה."],["4419","13","<b>דאיהו וחיוהי</b>: ראה תקו\"ז בהקדמה (ג, ב)."],["4420","14","<b>דבריא' שמיעוטו רע</b>: ראה ע\"ח (שער ק\"נ) שמ\"ט, פ\"ו."],["4421","15","<b>בע\"ח בשער מ\"ן ומ\"ד</b>: ראה ג\"כ לעיל ע' תקסה."],["4422","16","<b>עושה מלאכיו רוחו' משרתיו אש לוהט</b>: תהלים קד, ד."],["4423","17","<b>ב\"ן בגי' בהמה</b>: ראה תניא ספמ\"ו. תו\"א עו, ב. זח\"ג ריז, א. ראה כנפי יונה (לרמ\"ע מפאנו) חלק שני סק\"ה. מגלה עמוקות אופן קו (מו, א). קהלת יעקב בערכו. שבת קמה, ב."],["4424","18","<b>ורוח הבהמה היא היורדת למטה</b>: ע\"פ קהלת ג, כא."],["4425","19","<b>למה צדיקי' דומין בפני השכינה</b>: פסחים ח, א."]]],[2100990238,"נכללי' בה כמשל ביטול הנר בפני האבוקה כנ\"ל כך נפרדי' אורו' המלאכי' מהגופי' שלהם ואז נתברר גם חלק החומר שלהם שמנוגה וה\"ז כמו משל החציר שנשאב בפי בהמה ולפי שבכל יום מתחדשי' מפני בחי' השבירה דז' מלכי' ע\"כ בכל יום ויום מצמיח חציר דמלאכי' לבהמה העליונ' וחוזרי' וצומחין מחדש משבירת הכלים וחוזרי' ונכללי' במלכו' ע\"ד המשל בחציר הגשמי כנ\"ל וד\"ל.\n<b>וזהו</b> שאמר אלין אינון שתין אלף רבוא דמלאכי' כו' והטעם למספר זה דוקא לפי שמדבר כאן בברורי' דנוגה דבריא' כנ\"ל ובעולם הבריא' המספר באלף דוקא כמ\"ש בזוהר<sup data-n=\"4426\">20</sup> בענין תלת עלמין כו' משום דבעלמא קדמאה דבריאה מאיר אל שדי שמספרו בריבועו ומילואו עולה אלף דוקא וז\"ש כי אלף<sup data-n=\"4427\">21</sup> המגן תלוי עליו כל שלטי כו' ואל הוי' מאיר בעולם היצירה שמספרו נ\"ז וזהו הכונה בברכה ראשונה דברכהמ\"ז הז\"ן את העולם כו' ואל אד' מאיר בעולם העשי' שמספרו צ\"ו כו' כידוע כל זה בכתבי האריז\"ל ומאחר שאמר בסמוך דאלף טורין כו' מוכח מזה דמיירי כאן בעולם הבריא' שמהספר שם אלף וע\"כ אמר כאן שתין אלף רבוא כו' והטעם לשתין אלף רבוא היינו לפי שו\"ק דתוהו שנשברו מתכללי' זה בזה כמו בלע ויובב כו' ויש בכל מדה התכללות ממאה אלף וע\"כ עולה שרש מספר כולם ת\"ר אלף כידוע בטעם מספר נשמו' ישראל שהם ס\"ר להיותם בו\"ק דז\"א דתיקון כו' וגם בתוהו הרי במלכו' לא הי' בחי' שבירה כלל וכמאמר דארעא אתבטלת פי' אתבטלת בבחי' ביטול בלבד ולא בבחי' שבירה כו' וד\"ל.\n<b>ובזה</b> יובן הטעם שלא יש ימים שנק' ימי המעשה רק ששה ימים בלבד אבל יום השביעי שהוא לנגד בחי' המל' לא נק' יום המעשה שהרי המלאכה<sup data-n=\"4428\">22</sup> אסו' בשבת והרי אין כאן אלא ו' ימי המעשה בלבד כו' והענין הוא להיו' ידוע דפי' ו' ימי המעשה מעשה זו היינו בחי' התיקון והבירור כמו עד\"מ באדם התחתון שו' יומין דחול זמן המעשה בשדהו בל\"ט מלאכו' חורש וזורע וקוצר כו' דבאמת<sup data-n=\"4429\">23</sup> לכאורה אינו מובן מה שצריך האדם לחרוש ולזרוע ולקצור וכו' ואח\"כ לטחון ולאפות הפת עד שיאכל המאכל וכן צריך שיקח צמר ויטווה ויארוג ואח\"כ יתפור עד שיתלבש במלבוש שכל אלה ענין טרחא ועבודה רבה ולמה לא יהי' להאדם לחם<sup data-n=\"4430\">24</sup> לאכול ובגד ללבוש בלתי הכנה ותיקון בעבודה רבה כזאת בל\"ט מלאכו' כו'.\n<b>אך</b> הענין שכל אלה העבודו' ענין תיקון ובירור הוא שהרי החורש וזורע תיקון ובירור הזרע הוא להוציא הכח המצמיח מן החטה כו' ואח\"כ הדישה והקצירה והטחינה הכל עניני בירור ותיקון כדי שיהא ראוי למאכל וגם אחר שנטחן עדיין עוד",[["4426","20","<b>בזוהר בענין תלת עלמין</b>: ראה זח\"ג קנט, א."],["4427","21","<b>אלף המגן תלוי עליו</b>: שה\"ש ד, ד."],["4428","22","<b>שהמלאכה אסורה בשבת</b>: ראה שבת עג, א."],["4429","23","<b>דבאמת לכאו'</b>: בהבא לקמן ראה ג\"כ תו\"ח תולדות קמט, א. שערי תשובה סו, א ואילך."],["4430","24","<b>לחם לאכול ובגד ללבוש</b>: לשון הפסוק ויצא כח, כ."]]],[2100990239,"צריך תיקון לאפות הפת כדי שיהא נבלע באיברי' כו' וכל זה תיקון אחר תיקון עד &lt;שג&gt;\nשיהי' ראוי למאכל לחיות בו הנפש כו' וכן הלבוש אינו בא ממילא אלא ג\"כ ע\"י בחי' התיקון בטוויית הצמר ואריגתו והתפירה וכיוצא עד שיהא לו למלבוש ממש כו' והטעם שלא נברא הלחם לאכול והבגד ללבוש בלתי תיקון כלל כענין לעתיד<sup data-n=\"4431\">25</sup> שאמרו שתוציא הארץ גלוסקאו' וכלי מילת כלומר גמר תיקונן בא ממילא שיצמחו עם גמר תיקונן מן הארץ ולא עכשיו כי ידוע שבצלם<sup data-n=\"4432\">26</sup> האלקי' עשה את האדם התחתון ולמעלה בבחי' אדם שעל הכסא מתלבש בו' יומין דחול ג\"כ לברר ברורי' דנוגה ע\"ד הנ\"ל בחציר שהוא כמו דמיון הקצירה וכן יש עד\"ז ל\"ט מלאכו' כולן חורש וזורע בשדה העליונה כו' עד שיהיו מציאו' נבראי' שנק' בשם מאכל לחם למעלה וכן יש נבראי' שנק' בשם לבושי' ונא' בהן דרשה<sup data-n=\"4433\">27</sup> צמר ופשתים וכן סדין<sup data-n=\"4434\">28</sup> עשתה וכיוצא והכל עניני בירורי' בירור אחר בירור כנ\"ל במשל ולכך נק' ו' ימי המעש\"ה כלומר ימי המלאכה והתיקון עד שיהי' לחם לאכול ובגד ללבוש כו' ועד\"ז ניתן למטה בעבודת ה' בנפש האלקי' שלא יבא האדם למדרגת הדביקו' בה' אחד ממילא ומעצמו אלא ע\"י בחי' הברורי' והוא לאהפכא<sup data-n=\"4435\">29</sup> חשוכא לנהורא כו' מנפש הבהמיו' דנוגה המעורב טו\"ר כו' והיינו מפני שהנפש אלקי' היא מבחי' מ\"ה<sup data-n=\"4436\">30</sup> דתיקון שמברר ב\"ן כו' וד\"ל ואמנם אין התיקון אלא במה שהי' בחי' שבירה ונפילה דוקא והיינו בששה המדו' דתוהו כמו בלע<sup data-n=\"4437\">31</sup> ויובב וכיוצא והוא בחי' חג\"ת נה\"י אבל במלכו' המדה השביעי' לא הי' שבירה אלא בחי' ביטול בלבד כנ\"ל ע\"כ אין מלאכה בשבת שהוא לנגד המלכו' שא\"צ בירור ותיקון כלל וע\"כ כל ל\"ט מלאכו' אסו' בשבת כי אין צריך תיקון רק בו' ימים בלבד לתקן ו' המדו' שנשברו אך בחי' ההעלאה מן הבירורי' הוא דוקא בשבת ולא בחול כמאמר מי<sup data-n=\"4438\">32</sup> שטרח בע\"ש יאכל כו' וכמ\"ש במ\"א וד\"ל.\n<b>ומה</b> שאמר עוד אלף טורין סלקין לה בכל יומא ויומא וכל טורא שתין רבוא הוה והיא אכלה ע\"כ משום דמיירי בבחי' נוגה דבריא' וכל יום כלול מן ו' הימים וכללו' הכל עולה ת\"ר אלף רבוא מטעם הנ\"ל וד\"ל. ומה שאמר דוקא ביומא תניינא דבראשית לפי שבחי' אור<sup data-n=\"4439\">33</sup> הגבור' האיר ביום ב' במאמר יהי<sup data-n=\"4440\">34</sup> רקיע כו' להבדיל כו' כמ\"ש במ\"א והמלאכי' שרשם מבחי' הגבורו' דשם ב\"ן וע\"כ אמר וכולהו אשא מלהטא וכנ\"ל ואלין אינון חציר כו' מבואר הכל עפ\"י כל הנ\"ל.",[["4431","25","<b>לעתיד. . שתוציא הארץ גלוסקאו'</b>: ראה שבת ל, ב. שער האמונה נח, ב. תו\"ח בראשית לא, ד ובהערה 33."],["4432","26","<b>שבצלם האלקים עשה את האדם</b>: בראשית א, כז."],["4433","27","<b>דרשה צמר ופשתים</b>: משלי לא, יג."],["4434","28","<b>סדין עשתה</b>: שם כד."],["4435","29","<b>לאהפכא חשוכא לנהורא</b>: זהר בהקדמה ד, א."],["4436","30","<b>מ\"ה. . שמברר ב\"ן</b>: ראה ע\"ח שער (ה) טנת\"א פ\"א."],["4437","31","<b>בלע ויובב</b>: ראה וישלח לו לג. דבה\"י-א א, מד. ראה זהר (אדרא רבא) קלה, א. וראה פירוש המלות סה, ג."],["4438","32","<b>מי שטרח בע\"ש יאכל</b>: ע\"ז ג, סע\"א."],["4439","33","<b>אור הגבור' האיר ביום ב'</b>: ראה ג\"כ תו\"ח בראשית ח, ג. דרך מצותיך קנא, א."],["4440","34","<b>יהי רקיע כו'</b>: בראשית א, ו."]]],[2100990240,"<b>ומה</b> שמסיים המאמר הה\"ד יודע צדיק נפש בהמתו כו'. הענין הוא לפי שהוקשה לו עדיין בפי' הפסוק למה אמר מצמיח חציר לבהמה דוקא ואמר לפרש הדבר שבהמה זו היא בחי' שם ב\"ן שהרי צדיק העליון שהוא בחי' יסוד ז\"א נא' בו יודע נפש בהמתו א\"כ מזה ראי' דבהמה דכאן הוא מיירי בבחי' מל' ג\"כ וע\"ז אמרו ז\"ל בדרך הפשט דאדם אסור<sup data-n=\"4441\">35</sup> לאכול עד שיתן מאכל לבהמתו והיינו פי' יודע צדיק נפש בהמתו למעלה וד\"ל. אך היא גופה קשיא למה נק' המל' לפעמי' בשם בהמה ולפעמי' בשמות אחרים כמו בבחי' דומם בלבד כמ\"ש אבן<sup data-n=\"4442\">36</sup> מאסו כו' מקים<sup data-n=\"4443\">37</sup> מעפר ולפעמי' בבחי' צומח כו' אך הענין הוא דקריאת השם במלכו' תלוי' בקריא' שם דז\"א כי דרך כלל יש בחי' דצח\"ם וזה למעלה במדרגה מזה המדבר גבוה מן החי והחי גבוה מן &lt;דש&gt;\nהצומח כו' ודרך כללות כל ההשתלשלו' הנה לפעמי' נק' ז\"א בשם צומח בלבד כמ\"ש כי<sup data-n=\"4444\">38</sup> האדם עץ השדה כו' ובחי' אבא נק' חיה ובחי' הכתר נק' יחידה כו' ואמנם דרך פרט יותר נקרא אבא בשם אדם<sup data-n=\"4445\">39</sup> קדמאה או אדם עילא' ובחי' חג\"ת דז\"א נק' חיוון עילאין מרכבתא לאו\"א כו' ודרך פרט יותר נק' ז\"א בחי' מדבר דהיינו כשקראו בשם אדם דאצי' כו' אזי בחי' המל' נק' בחי' בהמה דהיינו בחי' חי וכמ\"ש אדם<sup data-n=\"4446\">40</sup> ובהמה תושיע ה' ובכאן מיירי בדרך הזה (כי בדרך יותר פרטי גם בחי' המל' נק' אדם לגבי הנבראי' וכמ\"ש כתפארת<sup data-n=\"4447\">41</sup> אדם לשבת בית אלא שנק' אנפי זוטרי כמ\"ש במאמר זה בסמוך) והיינו שהביא ראי' מפסוק דיודע צדיק נפש בהמתו משום דמיירי כאן בבחי' ברורי' דשם ב\"ן שמלובש בעולם הבריא' דוקא שהוא בבחי' חי בלבד וזהו מ\"ש מצמיח חציר לבהמה דוקא כנ\"ל א\"כ ממילא בחי' ז\"א נק' מדבר והוא בחי' אדם דרכיב על בהמה כמ\"ש בסמוך וע\"כ אמר הה\"ד יודע צדיק נפש בהמתו וד\"ל.\n<b>ולהבין</b> ביותר ביאור ענין אדם דרכיב על בהמה זו כו' כמ\"ש יודע צדיק כו' שהוא עד\"מ אדם הרוכב על בהמה שמנהיגה לכל צד שירצה כו' יובן ממשל הדיבור שבטל לגבי המחשבה שבמוח שהמחשבה מנהיג הדיבור כי כמו שירצה במחשבה כך ידבר בדיבור וידוע שאותיו'<sup data-n=\"4448\">42</sup> הדיבור נק' בחי' דומם בערך המחשבה שנק' חי לפי שאות הדיבור אינו נוסף ונגדל כלל ואות המחשבה יצמח ויגדל כמו בתינוק שדעתו מתגדל גם באותיו' מחשבתו לפי השנים כו' וד\"ל. ויש לפרש עוד דמה שהביא דמיון מפסוק זה יודע צדיק כו' להורות עוד ענין א' שאחר הברורי' דשם ב\"ן שנק' מאכל לבהמתו אזי בא זמן הברורי' דמ\"ד דצדיק חי עלמין כו' שנק' אכילת אד\"ם וכמאמרם אסור לאדם לאכול עד שיתן מאכל לבהמתו שהרי נא' ואכלת<sup data-n=\"4449\">43</sup> ושבעת אחר ונתתי עשב בשדך לבהמתך כו' אך קודם שיאכל זה האדם",[["4441","35","<b>אסור לאכול עד שיתן מאכל לבהמתו</b>: ראה ברכות מ, א. וראה גם לקו\"ת בחוקותי מט, ב."],["4442","36","<b>אבן מאסו</b>: תהלים קיח, כב."],["4443","37","<b>מקים מעפר</b>: שמואל-א ב, ח."],["4444","38","<b>כי האדם עץ השדה</b>: פ' שופטים כ, יט."],["4445","39","<b>אדם קדמאה</b>: תקו\"ז ת\"ע (קכ, א)."],["4446","40","<b>אדם ובהמה תושיע ה'</b>: תהלים לו, ז."],["4447","41","<b>כתפארת אדם לשבת בית</b>: ישעי' מד, יג."],["4448","42","<b>שאותיו'. . דומם</b>: ראה ס\"י פ\"ד, מ\"ב."],["4449","43","<b>ואכלת ושבעת. . ונתתי עשב בשדך לבהמתך</b>: עקב יא, טו. שם."]]],[2100990241,"בעצמו מברר הוא מאכילת בהמתו בתחלה והיינו ענין מה שמברר המ\"ד את מ\"ן דשם ב\"ן והוא מ\"ש יודע צדיק נפש בהמתו ואמר נפש דוקא דהיינו ממה שכבר נעשה בחי' מ\"ן מהעלא' רפ\"ח ניצוצו' שכבר נתבררו ע\"י שם ב\"ן בירידתו למטה כו' שזהו ענין בירור שני דב\"ן אזי דוקא עולה בשלימו' הבירור במה שיודע צדיק מנפש בהמתו וד\"ל.\n<b>ועשב</b> לעבודת האדם, אלין אינון נשמתין דצדקייא דההוא אדם דרכיב ושליט על בהמה אכיל ואעיל לון בגוויה, ובזכותהון אתזן כל עלמא מההוא אדם כו' האדם ההוא דאשתמודע, פי' עד\"מ העשב שהוא גדל הרבה כפי הראוי ואין קוצרין אותו בכל יום כמו החציר אלא גדל הרבה בכל שיעורו והוא אינו מאכל בהמה אלא הוא עולה ונכלל בשאר צרכי האדם כך הנשמות נמשלי' לעשב שגדלין הרבה דהיינו עד שנשלם זמן הבירור שלהם בשלימות דוקא ואזי עליי' והסתלקות במדרגה יותר עליונה מחציר דמלאכי' והיינו שעולין ונכללי' בבחי' ז\"א עצמו וכמאמר הידוע שאמר בנשמות לאשתאבא<sup data-n=\"4450\">44</sup> בגופא דמלכא כו' והענין הוא לפי ששרש הנשמו' נמשך מבחי' מ\"ד דז\"א כי התהוו' הנשמו' מזווג גופני דזו\"נ כידוע וע\"כ עולין ונכללי' &lt;שה&gt;\nבשרשם בגופא דז\"א שנק' אד\"ם דרכיב על בהמ\"ה כמבואר למעלה וזהו שאמר ועשב לעבודת האדם אלין אינון נשמתין דצדיקייא דההוא אדם כו' אכיל ואעיל לון בגוויה ולהיות כי עולין ונכללי' בו בבחי' העלאת מ\"ן ע\"כ אמרו ז\"ל האבות<sup data-n=\"4451\">45</sup> הן הן המרכבה כלומר עד\"מ הבהמה שהאדם רוכב עליה שהיא בטילה לגבי הרוכב כך בחי' חג\"ת דבריא' שרש האבות בחי' מרכבה נעשי' כשעולין ונכללין בחג\"ת דז\"א עצמו וד\"ל.\n<b>ובזכותהון</b> אתזן כל עלמא כו' פי' לפי שעלו בבחי' העלא' מ\"ן מוסיפין המה כח ועוז יתירה בז\"א שיוכל להמשיך אור למטה במלכות בבחי' מ\"ד בתוספת ברכה כי עולין להוסיף מוחי' בז\"א אחר ששרשם נמשך מבחי' המוחי' דז\"א כמ\"ש בני<sup data-n=\"4452\">46</sup> בכורי ישראל כו' כמשל<sup data-n=\"4453\">47</sup> הטפה שנמשכת ממוח האב וע\"כ בהתכללותם כשהן נכללי' בז\"א עולי' ונכללים במוחי' ג\"כ ומוסיפין שם המשכות מוחי' חדשי' והיינו שאמר דבזכותהון אתזן כל עלמא בלחם שהוא עיקר הזן כו' וכמו שסיים זה המאמר בפי' פסוק זה להוציא לחם מן הארץ לאפקא מזונא לעלמא מן הארץ קדישא שהוא בחי' המל' ע\"י אור הזרוע לצדיק חי עלמין בארץ זו וזהו לעבודת האדם שהוא ז\"א כו' וד\"ל משא\"כ המלאכי' לא נעשה מהברורים שלהם שום המשכת ברכה למטה רק שמתקנין לעצמם בלבד ע\"י שמתפרדי' מחומר שלהם ונכללי' בבחי' מל' שהוא שם ב\"ן כנ\"ל אבל לא ניתוסף עי\"ז למעלה בזו\"נ שום המשכו' מוחי' חדשי' לפי שאין השרש שלהם מבחי' המוחין כלל ולכך דקדק לומר דבנשמתין דוקא אתזן כל עלמא מההוא אדם כו' להוציא לחם מן הארץ ולא ע\"י המלאכי' וד\"ל.",[["4450","44","<b>לאשתאבא בגופא דמלכא</b>: זהר ויחי ריז, ב."],["4451","45","<b>האבות הן הן המרכבה</b>: נסמן לעיל ע' תר."],["4452","46","<b>בני בכורי ישראל</b>: שמות ד, כב."],["4453","47","<b>כמשל הטפה שנמשכת ממוח האב</b>: ראה תניא פ\"ב."]]],[2100990242,"<b>ויין</b> ישמח כו' ויין דא חמרא עתיקא דנגיד מלעילא, פי' חמרא עתיקא דוקא ולא אמר חמרא סתם, כי הנה פי' יין<sup data-n=\"4454\">48</sup> ידוע שהוא בחי' בינה<sup data-n=\"4455\">49</sup> דאצי' שנק' אם הבנים וכתיב בה אם הבנים שמחה פי' כי היין משמח באדם להיות נגלה בו מן ההעלם כי נכנס<sup data-n=\"4456\">50</sup> יין יצא סוד אך שזה דוקא כששותה יין במדה שאז הוא שמח וטוב לב ומגלה כל מצפון אבל יתר מן המדה יבא על ידו לכלל כעס או לידי עצבות ומ\"ש כידוע והוא ענין מה שהדינין<sup data-n=\"4457\">51</sup> מתערין מן היין ג\"כ כמשל גבורות קשו' דכעס וכיוצא שבאה מחמימות היין כו' אבל במדה נכונה אזי כל טוב וכל חידו נמשך מן היין כמ\"ש בזוהר במ\"א. והנה מה שהיין מוציא הסוד הוא דוקא ביין<sup data-n=\"4458\">52</sup> המשומר בענביו שהוא כמו היין הישן לפי שהכח שלו חזק ביותר לפי שהוא נעלם בענבים ומפני בחי' ההעלם בא הכח הזה כי הרי יין שאינו משומר בענביו בהעלם אלא יצא לחוץ ע\"י הסחיטה וכיוצא אינו חזק כ\"כ ואינו מוציא הסוד כ\"כ נמצא שהעלם כח היין מביא סיבת גילוי ההעלם לשותהו כו'.\n<b>וכך</b> יובן הנמשל למעלה בבחי' בינה דאצי' שנק' יין המשמח שנכנס יין יצא סוד הוי' מן ההעלם דכתר עליון שנק' סתימו<sup data-n=\"4459\">53</sup> דכל סתימין כו' להיו' בגילוי במדו' דז\"א וזהו אם הבנים שמחה כו' אך זהו דוקא בחמרא עתיקא עד\"מ היין הישן והענין שלו למעלה היינו בחי' יין המשומר בענביו מששת ימי בראשית וכמ\"ש באד\"ר<sup data-n=\"4460\">54</sup> חמר טב דיתיב על דורדיי' כו' וכמ\"ש ביאור זה במ\"א ונק' חמרא עתיקא לפי שבחי' אור הכתר &lt;שו&gt;\nנעלם שם וכידוע דלטעם זה בחי' או\"א נק' לפעמים בשם זקנים וכמ\"ש ואברהם<sup data-n=\"4461\">55</sup> ושרה זקנים כו' וזהו ג\"כ טעם למצות כיבוד אב ואם דכתיב כבד<sup data-n=\"4462\">56</sup> את אביך ואמך לפי שהם בבחי' הזקנה כו' וע\"כ יש בחי' בינה שנק' ג\"כ בשם חמרא עתיקא כו' ואז נק' הכתר עתיקא דעתיקין כו' וד\"ל והיינו הטעם שכאשר נכנס יין דבינה שהוא בחי' חמרא עתיקא יצא סוד כי הזקן דעתי' סתים וע\"י היין הישן שנחה דעת זקנים ממנו נכנס יין יצא הסוד הסתום כי הכח ביין זה למעלה מבחי' הכתר הוא בא וכמבואר במשל הנ\"ל והמופת לזה הוא מן המחשבה שהיא סתומה ונעלמה תמיד באדם עד שאין יודעין לעולם מהו חושב ומהרהר וכאשר נכנס יין יצא סוד המחשבה הסתומה בגילוי קול ודיבור כו' וד\"ל.\n<b>וזהו</b> ויין דא חמרא עתיקא דנגיד מלעילא פי' מלעילא מבחי' הכתר שהוא בהעלם נגיד ונמשך כח ההעלם הזה גם בבחי' בינה דאצי' ואז נק' חמרא עתיקא מטעם הנ\"ל וזה היין דוקא מוציא הסוד דמחשבה הסתומה בקול ודיבור דזו\"נ ובזה",[["4454","48","<b>יין. . בינה</b>: ראה זהר נשא קכז, א."],["4455","49","<b>בינה. . אם הבנים שמחה</b>: ראה זהר ויחי ריט, א. יתרו פד, א. פה, ב."],["4456","50","<b>נכנס יין יצא סוד</b>: עירובין סה, סע\"א."],["4457","51","<b>שהדינין מתערין מן היין</b>: ת\"ז בהקדמה (יז, ב)."],["4458","52","<b>ביין המשומר בענביו</b>: ראה ברכות לב, ב. תו\"ח לך צא, ג הערה 32."],["4459","53","<b>סתימו דכל סתימין</b>: זח\"ב פט, א. קמו, ב. וראה תקו\"ז בהקדמה (יז, א)."],["4460","54","<b>באד\"ר חמר טב דיתיב על דורדיי'</b>: ראה זהר חדש שה\"ש סד, ב."],["4461","55","<b>ואברהם ושרה זקנים</b>: וירא י, א."],["4462","56","<b>כבד את אביך ואמך</b>: יתרו כ, יב."]]],[2100990243,"נמתקין כל הדינין הקשין דמתערין מבינה כנ\"ל במשל היין המשכר שמביא לידי כעס ורוגז כו' וד\"ל וזהו ויין ישמח לבב אנוש פי' יין זה דנק' חמרא עתיקא דוקא הוא הממתיק דינין שנאחזים בקטנו' דז\"א שנק' אנוש כמ\"ש בסמוך וד\"ל.\n<b>ישמח</b> לבב אנוש, אנוש דא רזא דההוא נער דסליק לסיבו ואתהדר כמלקדמין וע\"ד כתיב אנוש כחציר ימיו ע\"כ. פי' בחי' מט\"ט<sup data-n=\"4463\">57</sup> דיצירה נק' אנוש ונקרא נער כידוע, והענין הוא כי בהיות ידוע דאימא<sup data-n=\"4464\">58</sup> מקננא בכורסייא שהוא עולם הבריא' ופי' מקננא עד\"מ הצפור שעושה לה קן כו' כך יורדת אור אימא דאצי' ועושה לה קן לדירה בעולם הבריא' להיות הנשמו' נהנין ומשיגי' והוא הנק' עולם התענוג הנק' עוה\"ב כו' וזהו לעוצם ירידת האור דבינה דאצי' עד שמאיר בנשמו' דבריא' כו' והוא ע\"י התלבשו' אימא בחב\"ד דבריא' כו' וכך ענין ז\"א דמקנן ביציר' כידוע הרי הוא ג\"כ ענין ירידת אור מז\"א דאצי' להיות מקנן ומלובש במדו' דיצירה והוא הנק' מט\"ט כידוע וד\"ל אך הטעם שנק' התלבשו' ז\"א בו\"ק דיצירה בשם נער דוקא וגם מה שאמר דההוא נער סליק לסיבו כו' שזהו ענין התחדשות שלו בתמידות כמ\"ש תתחדש<sup data-n=\"4465\">59</sup> כנשר נעורייכי כו' הענין הוא לפי שידוע בענין עליות<sup data-n=\"4466\">60</sup> העולמו' בכלל בכל שבת ושבת וגם בפרט כי העלי' של עולם העשי' עולה ונכלל ביצי' ויצי' נכלל בבריא' ובריא' באצי' כו' הרי ו\"ק דיצי' עולין בכל שבת לשרשם כמו שהם בבחי' ז\"א דאצי' ואח\"כ חוזר ונמשך ויורד האור מאצי' לבריא' ומבריא' ליצי' בכל ו' ימי המעשה שאחר השבת כידוע ובשבת הבא חוזרי' ועולין וכן חוזר חלילה מדי שבת בשבתו בעלי' וירידה וא\"כ מובן שבחי' ו\"ק דיצי' הנק' מט\"ט מתחדש ממש בכל שבת ושבת כי כאשר עולה בשבת בבחי' ז\"א דאצי' להיות כי באצי' מאיר עדיין בחי' אור א\"ס שהוא נצחי וקדמון ע\"כ נק' ו\"ק דז\"א בבחי' זקנה ג\"כ ונקרא איש ולא אנוש ונער עד\"מ איש זקן בשנים אך כאשר חוזר ונמשך ויורד להאיר בו\"ק דיצי' כמאמר ז\"א מקנן ביצי' אזי מתחדשי' ימיו ולכך נק' נער כלומר רך בשנים &lt;שז&gt;\nכי בחי' הנצחיו' דאור א\"ס מסתתר ביצי' ונופל ממנו גם בחי' הזקנה אחר שחוזר ומתחדש מחדש בהיותו מתלבש ביצירה והגם שנעשה בחי' זקן לפי שעה כשעלה באצי' אבל כשחזר וירד ביצי' נק' נער כי הארה זו הרי מחדש היא באה והזקנה אינה אלא מצד ריבוי הזמן ובכאן הרי מתחדש בכל שבת וא\"כ לעולם אינו נק' זקן אלא בן ו' ימים בלבד והוא ענין המשנה הפעוטו'<sup data-n=\"4467\">61</sup> מקחן מקח כו' דהיינו כבר שית כו' וד\"ל וזהו שאמר אנוש דא הוא רזא דההוא נער פי' נער מט\"ט דהיינו ו\"ק דיצי' דסליק לסיבו בבחי' ו\"ק דאצי' כנ\"ל ואתהדר כמלקדמין בבחי' נער ביומין דחול כנ\"ל וע\"ד כתיב אנוש כחציר ימיו פי' עד\"מ החציר הנ\"ל שגידולו אינו בא",[["4463","57","<b>מט\"ט דיצירה נק' אנוש</b>: ראה לקו\"ת פינחס עט, ב. האזינו כו, ד. וש\"נ. שה\"ש כה, א. אוה\"ת שה\"ש ע' שצ. וע' שצג."],["4464","58","<b>דאימא מקננא בכורסייא</b>: תקו\"ז ת\"ו (כג, א). ע\"ח שער (מז) סדר אבי\"ע פ\"ג. שער (מב) דרושי (כללות) אבי\"ע פ\"ג. וראה דרך מצותיך סג, א. תניא פל\"ט."],["4465","59","<b>תתחדש כנשר נעורייכי</b>: תהלים קג, ה."],["4466","60","<b>עליות העולמות. . בכל שבת ושבת</b>: ראה ע\"ח (שער פנימית וחיצונית) ש\"מ דרוש ג. ח. טו. ראה ג\"כ אגרת התשובה פ\"י. ובכ\"מ."],["4467","61","<b>הפעוטו' מקחן מקח</b>: גיטין נט, א."]]],[2100990244,"ונמשך בהמשך ריבוי זמן ארוך אלא גדל מעט מעט בכל יום כי קוצרין אותו בכל יום ומתחדש ונגדל מחדש ביום הב' כנ\"ל ולעולם אינו נגדל הרבה כו' כך בחי' אנוש זה שהוא בחי' מט\"ט לעולם אינו בא בימי הזקנה אלא מיד דסליק לסיבו בו\"ק דאצי' בשבת חוזר ומתחדש בירידת ז\"א לקנן ביצי' ונק' נער וכמ\"ש תתחדש כנשר נעורייכי כו' וזהו אנוש כחציר ימיו וד\"ל.\n<b>ואחר</b> שביאר פי' אנוש בזה מובן מה שהתחיל לפרש הפסוק דיין ישמח לבב אנוש זה דוקא דהנה פי' לבב אנוש הוא בחי' פנימיו' דאנוש זה כמו הלב באדם שכולל בעצמו כל חלקי חיות האיברי' ונק' מלך על כל האיברי' כידוע וכמאמר לב<sup data-n=\"4468\">62</sup> פליג לכל שייפין כו' כך בחי' מט\"ט הוא המלאך הכולל כללות כל המלאכים הפרטיים שהן לריבוא רבבו' כי מתחלקי' מו\"ק דמט\"ט להתחלקו' פרטיו' עד אין שיעור כמו חסד שבחסד כו' אך בחי' ו\"ק עצמם כוללים המה את כולם יחד וההתכללו' הזאת נק' לבב אנוש כמו עד\"מ הלב שכולל כל האיברי' ובחי' י\"ס דיצי' שהן בחי' אלקו' ממש שירד האור מז\"א דאצי' כנ\"ל נק' אנוש או נער עצמו כנ\"ל ומההוא חמרא עתיקא הנ\"ל ישמח לבב אנוש להאיר במדו' דיצי' בכלל וגם בפרט להתחלקו' פרטי המלאכי' כולם הנכללי' בלבב אנוש זה והארה זו היא להמתיק הדינין כמבואר למעלה בפי' חמרא עתיקא דוקא וזהו פי' ויין ישמח לבב אנוש וד\"ל.\n<b>להצהיל</b> פנים משמן, אינון פנים דאקרון אנפי רברבי ואנפי זוטרי, פי' אנפ\"י הוא בחי' המוחי' בכל מקום ויש מוחי' דקטנו' ויש מוחי' דגדלות כמו עד\"מ הנער המוחי' שלו בבחי' הקטנות הוא ובגדול המוחי' שלו בבחי' הגדלות ולפי שמבואר למעלה בענין נער מט\"ט דאקרי נער דוקא בהיות שז\"א מלובש ביצי' והיינו ענין אנפי זוטרי עד\"מ הרביא שהוא הנק' נער בלה\"ק וכמ\"כ כתיב וירכב<sup data-n=\"4469\">63</sup> על כרוב כו' שהוא ענין הכרובים שבמקדש כלומר כרביא וכמארז\"ל רוכב<sup data-n=\"4470\">64</sup> על כרוב קל כו' וכידוע ובהיות עלי' נער זה בז\"א דאצי' כמו שאמר דסליק לסיבו כו' היינו בחי' אנפי רברבי עד\"מ איש גדול בשנים וההפרש ביניהם הוא שבאדם הגדול המוחי' שלו בבחי' הגדלו' ולכך נק' אנפי רברבי ובנער ורביא המוחי' שלו בבחי' הקטנו' כו' וד\"ל ובפרט יותר יש הפרש הזה גם במט\"ט עצמו בין בהיותו בבחי' מוחי' דגדלו' והוא בבחי' ע\"ס דבריא' ובין בהיותו בבחי' הקטנו' בע\"ס דיצי' (כמאמרם ז\"ל &lt;שח&gt;\nנער<sup data-n=\"4471\">65</sup> הייתי גם זקנתי זה שרו של עולם אמרו) ועל כל בחי' אנפין בין דגדלו' בין דקטנות אמר להצהיל פנים משמן, מנגידו דעלמא דאתי משח ורבו קדישא עילאה, פי' נגידו דעלמא דאתי הוא הארת אור אבא שמאיר ומשפיע באור אימא שנק' עלמא דאתי",[["4468","62","<b>לב פליג לכל שייפין</b>: ראה זהר שלח קסא, ב. (רע\"מ) פינחס רכא, א. אגה\"ק סל\"א. תו\"ח בראשית ז, ד. לקו\"ת שה\"ש כט, ב. לא, א."],["4469","63","<b>וירכב על כרוב</b>: שמואל-ב כב, יא."],["4470","64","<b>רוכב על כרוב קל</b>: ראה ע\"ז ג, ב."],["4471","65","<b>נער הייתי גם זקנתי זה שרו של עולם אמרו</b>: תהלים לז, כה. ראה יבמות טז, ב. וראה תוספות שם ד\"ה פסוק זה."]]],[2100990245,"כידוע והיינו שנק' משח ורבו קדישא כו' כי הקדש בבחי' אור אבא והוא ענין שמן המשחה שנק' שמן<sup data-n=\"4472\">66</sup> משחת קדש הוא כו' וד\"ל.\n<b>וביאור</b> ענין בחי' שמן זה הענין הוא מובן מתוך פי' ויין ישמח לבב אנוש הנ\"ל דהנה לבב אנוש הוא בחי' מוחי' דקטנו' דז\"א בהיותו כבר מלובש במלאכי' נבראים כנ\"ל ע\"כ אין צריך מיתוק אלא רק מבחי' אור אימא שהוא יין המשמח הנ\"ל לשמח לבב אנוש אבל בשביל המתקות הדינין מבחי' מוחי' דגדלו' שנק' אנפי רברבי (וגם אנפי זוטרי נק' אנפי עכ\"פ והוא בחי' ע\"ס עצמן דבריא' או דיצי' משא\"כ בחי' לבב אנוש שהוא רק בחי' הכלים של האורו' די\"ס דבריא' או דיצי' וד\"ל) צריך שיבא האור ממקום הגבוה יותר והוא מבחי' אור אבא דוקא והוא בחי' השמן שהוא בחשאי היפך בחי' היין שגורם שמחה בהתלהבו' והשמן שהוא בחשאי מורה ענין בחי' הביטול במציאו' שהוא בבחי' החכמה כידוע וד\"ל וזהו שאמר להצהיל פנים הצהלת פנים הוא ע\"י המשכו' מוחי' חדשים מאור אבא לכך נצהל פנים שהן אנפי רברבי כו' וכענין המבואר במ\"א כמו שר'<sup data-n=\"4473\">67</sup> אבהו מצא תוספתא חדתא וצהלו פניו מרוב החדוה כו' וזהו משמן דוקא מהמשכו' אור החכמה שלמעלה הרבה ממדרגת היין דבינה כידוע וד\"ל. ובכל זה מובן ענין סדר הפסוקי' זא\"ז מצמיח חציר לבהמ' מלאכי' בחיצוניו' היכלו' דיצי' שנכללי' בשם ב\"ן בגי' בהמה ואח\"כ עשב נשמו' לעבודת האדם כנ\"ל ואח\"כ כתיב ויין ישמח מלמעלה למטה לבב אנוש להמתיק הדינין ואח\"כ עוד ממקום גבוה יותר להצהיל פנים דחב\"ד ג\"כ משמן שהוא אור אבא כנ\"ל וד\"ל.\n<b>ולחם</b><sup data-n=\"4474\">68</sup> לבב אנוש יסעד, דא לחם דאזילו שחקים וטחנו מנא למיכלא לצדיקייא סתמא, ומתמן אתנגיד לכמה חיילין דאקרון לבב אנוש, וכולא אתי מנגידו עילאה ע\"כ. פי' בא לפרש בענין סדר הפסוקי' דהיין המשמח אין לו דמיון עם הלחם הסועד אע\"פ ששניהם בלבב אנוש אבל היין הוא רק משמח בלבד שהוא ענין נוסף על עצם החיות כנראה בחוש שהשמחה איננה חיות עצמיות באדם אלא ענין אור נוסף על העצמו' כי כשהלב שמח מתפשט ביותר וכשאינו שמח הוא מתכווץ כו' אבל לחם הסועד הוא ענין חיו' עצמי שמחיה את הנפש עד שתתפשט גם מעיקר השרש שלה להתהוות כחות הגוף ולהחיותם מחדש כו' וכך יובן הנמשל דהנה בחי' שרש החיות להתהוו' המלאכי' שנק' לבב אנוש בכלל כנ\"ל הוא הנק' לחם למעלה וע\"ז אמר ולחם לבב אנוש יסעד כלומר סועד ממש להחיותו מחדש מאין ליש כו' ואין לבחי' יין המשמח לבב אנוש דמיון בזה על היותו רק בחי' אור נוסף בלבד כנ\"ל, והיינו שמפרש והולך ממה נעשה בחי' לחם זה שיוכל לסעוד ממש כו' ואמר דההוא לחם הוא דאזילו שחקים כו' פי' שחקים המה בחי' נצח והוד כידוע וכמ\"ש שחקים<sup data-n=\"4475\">69</sup> יזלו צדק ועד\"מ הרחיים שנק' שחקים &lt;שט&gt;\nג\"כ לפי ששוחקין המה וטוחנין היטב את החטה לפרורים דקים מאד מאד כקמח כדי שעי\"ז יוכשר למאכל אדם.",[["4472","66","<b>שמן משחת קדש הוא</b>: תשא ל, כה."],["4473","67","<b>שר' אבהו מצא תוספתא חדתא</b>: ראה ירושלמי שבת פ\"ח, ה\"א."],["4474","68","<b>ולחם לבב אנוש יסעד</b>: תהלים קד, טו."],["4475","69","<b>שחקים יזלו צדק</b>: ישעי' מה, ח."]]],[2100990246,"<b>כך</b> יובן הנמשל למעלה בהיות שתחלת ירידת אור השפע בא ונמשך מבחי' אור הכתר והוא הנק' טלא<sup data-n=\"4476\">70</sup> דבדולחא כענין שנא' במן ועינו<sup data-n=\"4477\">71</sup> כעין הבדולח והיינו ג\"כ טלא<sup data-n=\"4478\">72</sup> דנטיף מעתיקא וכמ\"ש כי<sup data-n=\"4479\">73</sup> טל אורות טלך כו' כמ\"ש בע\"ח והטעם שנמשל לטל דוקא כמ\"ש אהי'<sup data-n=\"4480\">74</sup> כטל לישראל כו' היינו לפי שהארת אור הכתר הוא בבחי' ההעלם עדיין ולא בגילוי כאור החכמה וכיוצא וה\"ז כמו הטל הגשמי שאנו רואי' שאינו ניכר ונראה באיזה ממשות כמו המים שהרי ידוע שלחלחיו' הטל בלילה אינו ניכר כלל אלא למחר ביום ניכר לחלחיו' בעלמא כו' וידוע שהחכמה<sup data-n=\"4481\">75</sup> נק' מים להיותו בא מן ההעלם לגילוי כמ\"ש והחכמה<sup data-n=\"4482\">76</sup> מאין תמצא אבל הכתר<sup data-n=\"4483\">77</sup> נק' אין ממש ולכך נמשל לטל וזהו אהי' כטל וידוע דשם אהי' בכתר דוקא וזהו ג\"כ פי' כי טל אורו' טלך כו' וד\"ל וזהו שאמר דאזילו שחקים וטחני מנא למיכלא דצדיקייא כו' שהוא הטל דעתיקא שנק' טלא דבדולחא שנק' מנא וכמ\"ש והמן כו'. אך מה שאמר דאזילו שחקים שהם בחי' נו\"ה דוקא הענין הוא כידוע דכליות יועצות איך להשפיע דהיינו עד\"מ הרב שרוצה להשפיע לתלמידו דבר חכמה שא\"א לו להשפיע כמו שהשכל אצלו במהותו ממש אלא צריך שיחלקנו לחלקים רבים מאד ויברר מה שצריך להשפיע דהיינו שהרבה ממנו לא ישפיע כלל כי לא יבין אותו ויתבלבל עי\"ז לגמרי ומעט מזעיר ישפיע וגם צריך עצה איך ישפיע באיזו לבוש ילביש צרופי אותיו' כו' וזהו הנק' כליו' יועצות שהם מייעצים איך להשפיע ובהם מתברר ההשפעה בב' אופנים הא' בהתחלקו' לחלקי' רבים מאד וזהו כמשל הטחינה בחטים ממש והב' בבירור ממנו המצטרך לאופן השפע בלבד וזהו משל לרקידה שאחר הטחינה והכל כדי שיהא ראוי למקבלי' כו'.\n<b>וכך</b> יובן הנמשל בשחקים העליוני' שהם בחי' נצח והוד דז\"א שמשחקים וטוחנים לחלקי' רבים את בחי' הטלא דבדולחא הנ\"ל בב' אופני הברורי' הנ\"ל כי בחי' טל זה להיותו מבחי' אור הכתר עצמו א\"א שיתקבל למטה להיו' נהנין ממנו נשמו' ומלאכי' שמקבלי' מזו\"נ שנק' צדי\"ק וצד\"ק כידוע וזהו למיכלא לצדיקייא סתמא וכו' אם לא שיטחנו אותו בתחלה בשחקים שהם בחי' נו\"ה מטעם המבואר במשל וד\"ל. ונמצא יש כאן ג' מדרגות א' חיות תמידי לחם לבב אנוש יסעד כו' והב' יין ישמח באור נוסף לפרקי' מאור אימא והג' להצהיל פנים משמן מאור אבא כנ\"ל ולכך סדר הכתוב ללחם אחר יין ושמן כי הם רק בבחי' אורו' נוסף על חיו' העצמיו' משא\"כ הלחם שהוא בחי' החיו' העצמי וע\"כ שרשו מבחי' הכתר כנ\"ל וד\"ל.\n<b>ישבעו</b> עצי הוי' ארזי לבנון אשר נטע, עצי ה' אינון אילנין פנימאין ועילאין, כי יש ב' עצים בחי' עץ החיים ועה\"ד טו\"ר וידוע דבחי' ז\"א נק' עץ החיים ובחי'",[["4476","70","<b>טלא דבדולחא</b>: ראה זהר ויחי רכה, ב. תרומה קלו, ב. תזריע מט, א."],["4477","71","<b>ועינו כעין הבדולח</b>: בהעלותך יא, ז."],["4478","72","<b>טלא דנטיף מעתיקא</b>: ראה זהר בשלח סא, ב. סב, ב. (אדרא זוטא) האזינו רפח א."],["4479","73","<b>כי טל אורות טלך</b>: ישעי' כו, יט. ראה זהר (אד\"ר) נשא קכח, ב."],["4480","74","<b>אהי' כטל לישראל</b>: הושע יד, ו."],["4481","75","<b>שהחכמה נק' מים</b>: ראה ג\"כ תו\"ח בראשית א, א."],["4482","76","<b>והחכמה מאין תמצא</b>: איוב כח, יב."],["4483","77","<b>הכתר נק' אין</b>: ראה תקו\"ז ריש תיקון מב."]]],[2100990247,"המל' נק' עה\"ד כי יורדת לתחתית המדרגו' ג\"כ וכמ\"ש מלך<sup data-n=\"4484\">78</sup> אלקי' על גוים כו' וכמ\"ש ומלכותו<sup data-n=\"4485\">79</sup> בכל משלה כו' ועץ החיים דז\"א נק' עצי הוי' וע\"כ אמר אלין פנימאין ועילאין שלא ירדו למטה בעולם &lt;שי&gt;\nהנפרד כו' ולכך הם דוקא ישבעו ויתענגו מהטלא דבדולחא הנ\"ל וד\"ל. אשר נטע דהא אתעקרו ונטע לון קדב\"ה פי' ארזי לבנון הם היו מבחי' התוהו בתחלה וירדו לבחי' התיקון להתתקן וזהו כמשל העוקר אילן ממקום זה ונוטעו במקום אחר כדי להתתקן שם כו' וד\"ל וזהו שאמר דאתעקרו מעולם התוהו ונטע לון בבחי' התיקון וד\"ל.\n<b>מאי</b> בין עצי ה' לארזי לבנון ארזי לבנון אלין נ' תרעין דבינה דאקרון חמש מאות שנה, פי' לבנון הנה הוא בחי' הכתר עצמו שנק' לבן סתם כי ממנו מקור הלבנונית והוא שם העצם בלובן משא\"כ הלבנונית המתפשטת בדבר מה שהוא פעולת הלובן בלבד עד\"מ הסיד הלבן הוא הלבן בעצם ואשר מלבנין בו ונעשה לבן נק' רק התפשטות פעולת הלובן העצמי כו' וכך יובן הדוגמא בלובן העליון דכתר עליון שהוא בחי' מקור כל הלבנוני' והחכמה שמקבלת מן הכתר נק' לבנון בלשון נפעל לפי שכבר נפעל בו פעולת התפשטו' בלבד מלובן העצמי שבכתר עד\"מ הדבר שנתלבן כנ\"ל והנו\"ן שבלבנון נו\"ן הכפופה היא בחי' חכמה והנו\"ן הפשוטה הוא בחי' בינה כידוע ושניהם מקבלי' מלובן העליון שבכתר וענין הלובן הזה למעלה הוא ענין מקור כל החסדי' כו' וזהו מן הנהר הגדול הזה ועד הלבנון פי' נהר הגדול הוא בחי' הכתר והלבנון הוא בחי' חו\"ב ולפי שיש בחי' מרחק גדול ביניהם לכך אמר מנהר הגדול כו' ועד הלבנון וד\"ל, ופי' ארזי הלבנון אלין חמשין תרעין דבינה עד\"מ הארזים שהם גבוהי' בקומה כך הם בחי' המדות דאימא דבינה רק עד הוד אתפשטת<sup data-n=\"4486\">80</sup> והן ה' פעמי' י' לכך הן חמשים שערי' וזהו פתחו שערים כו' ולהיו' כי מהם עיקר בנין ז\"א בבחי' ה' חסדי' המגדילי' כידוע ע\"כ נק' ת\"ק שנה דהיינו בהיותם עדיין באימא דהאלפי' בחכמ' והמאו' בבינה והעשיריו' בז\"א והיחידו' במל' כידוע אך בחי' הקיצור מהם בא בז\"א ונק' ה' חסדי' בלבד וד\"ל וזהו מאי בין עצי הוי' לארזי הלבנון עצי הוי' הם עה\"ח ועה\"ד כו' שהם בחי' זו\"נ בכלל כנ\"ל וארזי הלבנון הן נ' תרעין דבינה דהיינו שרש הגדלות דזו\"נ כנ\"ל וד\"ל והיינו פי' הפסוק ישבעו עצי הוי' זו\"נ מארזי הלבנון הנ\"ל אשר נטע בבחי' התיקון כנ\"ל וד\"ל.\n<b>אשר</b> שם צפרים יקננו, בטוליהון מקננין נשמתין דצדיקייא וכל חיילין קדישין אתזנון מתמן, פי' נשמו' הגבוהו' מאד כמו נשמו'<sup data-n=\"4487\">81</sup> רב המנונא סבא שהם מיחוד דאו\"א שלמעלה הרב' מנשמו' שמיחוד זו\"נ והם הנק' צפרין עילאי' ומקננין בארזי הלבנון הנ\"ל וגם יש חיילין מלאכי' שגבוהי' מן הנשמו' דזו\"נ ואתזנון מתמן ג\"כ לקבל מוחי' משם כו' וד\"ל.",[["4484","78","<b>מלך אלקי' על גוים</b>: תהלים מז, ט."],["4485","79","<b>ומלכותו בכל משלה</b>: תהלים קג, יט."],["4486","80","<b>דבינה רק עד הוד אתפשטת</b>: ראה זהר (רע\"מ) פינחס רכג, ב."],["4487","81","<b>נשמו' רב המנונא סבא</b>: ראה זהר בהקדמה ו, א. בלק קפז, ב. לקו\"ת שמיני יח, א ואילך. מאמרי אדה\"ז אתהלך לאזניא ר\"ע קנז. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רנו ובהנסמן לשם."]]],[2100990248,"<b>חסידה</b> ברושים ביתה, ברתא דאברהם דאקרי חסיד ועבד חסד עם כל עלמא בג\"כ אקרי חסידה, פי' בחי' מל' דאצי' שמקבלת כל החסדי' העליוני' דז\"א ודאו\"א כו' והיינו ברתא דאברהם שהי' מרכבה לחסד דז\"א כידוע, ברושים בין דרועי עלמא יתבא פי' בין חו\"ג דז\"א שנק' דרועין דעלמא וכמאמר הידוע ימינא<sup data-n=\"4488\">82</sup> ושמאלא ובנייהו כלה וכמ\"ש שמאלו<sup data-n=\"4489\">83</sup> תחת לראשי וימינו תחבקיני וד\"ל.",[["4488","82","<b>ימינא ושמאלא ובנייהו כלה</b>: פיוט אזמר בשבחין (זמירות ליל שבת)."],["4489","83","<b>שמאלו תחת לראשי</b>: שה\"ש ב, ו."]]],[2100990249,"<h3>וידעת היום</h3>\n<b>בעזר\"ה שבת נחמו</b>\n&lt;שיא&gt;\n\nוידעת<sup data-n=\"4490\">1</sup> היום והשבות אל לבבך<sup data-n=\"4491\">2</sup> כי ה' הוא האלקים בשמים ממעל וכו'. הנה יש להבין מה שאמר וידעת היו\"ם דאין יום בלא ערב ובקר כמ\"ש ויהי<sup data-n=\"4492\">3</sup> ערב ויהי בקר יום אחד ולמה תלה ידיעה זאת ביום שכלול מערב ובקר דוקא. אך הענין הוא דבכאן מזכיר ענין חיבור ב' הפכים כא' בג' דברים האלה כי כמו שהיום כלול מב' הפכים ערב ובקר כך אמר והשבות אל לבבך שיש ב'<sup data-n=\"4493\">4</sup> לבבות יצ\"ט ויצה\"ר ב' הפכים ויתאחדו כא' וכך יהי' ג\"כ חיבור ב' הפכים למעלה והוא שיהי' הוי' האלקי'<sup data-n=\"4494\">5</sup> וזהו שאמר כי ה' הוא האלקי' וכו' וזהו תוכן כונה הכללית בפסוק זה במה שסמך כאן ג' עניני' אלה זה לזה והוא מ\"ש היו\"ם ואח\"כ אל לבב\"ך לפי שזה משל לזה והנמשל משניהם הוא מה שלמעלה ג\"כ יהי' עי\"ז חיבור ב' הפכים דהיינו מ\"ש כי ה' הוא האלקי' וכו' ולהבין ביאור הדברים והאיך המשל דומה לנמשל כו' הנה תחלה יש להקדים ענין אחד בפי' ואהבת את ה' אלקיך מהו את ה' את הוא הטפל כו' ומה יש לרבות דבר חוץ ממנו ית' הלא אין<sup data-n=\"4495\">6</sup> עוד מלבדו כו'.",[["4490","1","<b>וידעת היום והשבות אל לבבך</b>: הנחת כ\"ק אדמו\"ר האמצעי, נעתק מגוכתי\"ק 1025 (פא, א).\nמאמר זה באריכות מכ\"ק אדמו\"ר האמצעי נדפס במאמרי אדה\"א ואתחנן ע' קעה.\nהנחת המהרי\"ל נדפס בלקו\"ת ואתחנן ז, ד. — וראה אוה\"ת ואתחנן ע' קעט ואילך.\nוראה אמרי בינה שער הק\"ש פמ\"ד. לכמה ענינים במאמר זה ראה גם תו\"ח בראשית לח, ב ואילך. תצוה שיח, ג."],["4491","2","<b>וידעת היום והשבות אל לבבך</b>: ואתחנן ד, לט."],["4492","3","<b>ויהי ערב ויהי בקר</b>: בראשית א, ה."],["4493","4","<b>ב' לבבות</b>: ראה ברכות נד, א."],["4494","5","<b>האלקי'</b>: בלקו\"ת שם יש הג\"ה מכ\"ק אדמו\"ר הצ\"צ (ועיין מזה בר\"ח [ בראשית חכמה] שער האהבה ספ\"ה ובספר עה\"ק [ עבודת הקודש] ח\"א פרק יא יב ובזוהר פ' וארא דכ\"ו ע\"ב ודכ\"ז ע\"א ובפי' הרמ\"ז)."],["4495","6","<b>אין עוד מלבדו</b>: ואתחנן ד, לה."]]],[2100990250,"<b>אך</b> הענין הוא דאמרו ז\"ל שמעון<sup data-n=\"4496\">7</sup> העמסוני היה דורש כל אתין שבתורה כיון שהגיע לאת<sup data-n=\"4497\">8</sup> ה' אלקיך תירא פירש כו' וידוע<sup data-n=\"4498\">*8</sup> הקושיא למה פירש באת זה ולא באת דואהבת את ה' כו' דמאותו הטעם שפירש באת דיראה כך יש לו לפרוש מאת דאהבה כו' אמנם הנה ידוע דעיקר מדת התפעלות האהבה היא מרחוק דוקא לפי שמצד הריחוק תגדל הצמאון והתשוקה ביותר לדבר הנאהב משא\"כ אם הדבר מקרוב וביותר באהבת האב אל הבן שתגדל הגילוי אור בתשוקה נפלאה באב כשבנו רחוק דוקא כידוע וכמ\"כ באהבת כנ\"י כלפי מעלה כמ\"ש ואהבת<sup data-n=\"4499\">9</sup> את ה' כו' מצד הריחוק דוקא תגדל אור גילוי האהבה והתשוקה ביותר וכמ\"ש צמאה<sup data-n=\"4500\">10</sup> לך נפשי כמה לך כו' בארץ ציה ועיף בלי מים פי' בארץ ציה דוקא להיותו שם בתכלית הריחוק ע\"כ משם דוקא תגדל הצמאון והתשוקה מטעם הנ\"ל, וענין ארץ ציה ועיף בלי מים היינו גם כל השתלשלו' העולמו' בכלל מאחר דכתיב הודו<sup data-n=\"4501\">11</sup> על ארץ ושמים כו' שאין כל השפע באה בעולמו' עליונים ותחתוני' גם בג\"ע<sup data-n=\"4502\">12</sup> העליון והתחתון שנק' ארץ ושמים העליוני' כידוע בספרי הקבלה רק מבחי' זיו ואור דמל' דאצי' והוא הנק' זיו השכינה בג\"ע ואף גם זאת ההארה משתלשלת ובאה בהתלבשו' וצמצומי' רבים בצמצום אחר צמצום עד עוה\"ז השפל מכולם אבל במהותו ועצמותו ית' לית<sup data-n=\"4503\">13</sup> מחשבה תפיס' בי' כלל אך מרחוק<sup data-n=\"4504\">14</sup> ה' נראה עליהם בבחי' מקיף וסובב וע\"כ תגדל התשוקה והצמאון לבחי' סובב כ\"ע מטעם הנ\"ל שהאהבה בצמאון באה מצד הריחוק והיינו מ\"ש צמאה לך נפשי בארץ ציה דוקא וקאי גם על העולם היותר עליון אחר דאין להעולמו' ערך כלל עם עצמו' אלקו' וכו' מטעם שאינם משיגי' כלל במהותו רק בבחי' הזיו בלבד וזהו ג\"כ מ\"ש מזמור לדוד בהיותו במדבר יהודה פי' כי עוה\"ז השפל נק' מדבר להיותו האחרון בכל סדר ההשתלשלו' והשפע מתצמצם בו בצמצום היותר אחרון וע\"כ הוא נמשל למדבר שאין בו חיות כו' ואמנם אדרבה היא הנותנת להיו' &lt;שיב&gt;\nמשם דוקא בחי' ההודיי' לבחי' סובב כ\"ע מטעם הריחוק כנ\"ל וזהו שאמר מזמור<sup data-n=\"4505\">15</sup> לדוד בהיותו במדב\"ר יהודה דוקא וע\"כ נק' מדבר יהוד\"ה ע\"ש בחי' ההודיי' כמ\"ש ותקרא<sup data-n=\"4506\">16</sup> שמו יהוד\"ה כי אמרה הפעם אודה את ה' כו' וד\"ל.\n<b>והנה</b> האהבה עם היראה המה ב' הפכים דהאהבה<sup data-n=\"4507\">17</sup> היא באה ע\"י בחי' הריחוק דוקא כנ\"ל אבל היראה באה מצד הקירוב דוקא ולא מצד הריחוק שהרי כל<sup data-n=\"4508\">18</sup> הקרב קרב ביותר להתבונן באור א\"ס ב\"ה עצמו איך שהוא סובב כ\"ע וארץ ושמים",[["4496","7","<b>שמעון העמסוני</b>: פסחים כב, ב. וש\"נ לעקב י, כ. קידושין נז, רע\"א. ב\"ק מא. וראה הנסמן במאמרי אדה\"א שם ע' קעו."],["4497","8","<b>לאת ה' אלקיך תירא</b>: ואתחנן ו, יג."],["4498","*8","<b>וידוע הקושיא</b>: ראה לקמן ע' תרלה הערה 2 וש\"נ."],["4499","9","<b>ואהבת את ה' אלקיך</b>: ואתחנן ו, ה."],["4500","10","<b>צמאה לך נפשי</b>: תהלים סג, ב."],["4501","11","<b>הודו על ארץ ושמים</b>: תהלים קמח, יג."],["4502","12","<b>בג\"ע העליון והתחתון. . ארץ ושמים. . בספרי הקבלה</b>: ראה ג\"כ לקו\"ת עקב טז, א."],["4503","13","<b>לית מחשבה תפיס' בי'</b>: תקו\"ז בהקדמה יז, א."],["4504","14","<b>מרחוק ה' נראה עליהם</b>: ע\"פ ירמי' לא, ב."],["4505","15","<b>מזמור לדוד</b>: תהלים סג, א."],["4506","16","<b>ותקרא שמו יהודה</b>: ויצא כט, לה."],["4507","17","<b>דהאהבה. . הריחוק. . היראה. . הקירוב</b>: ראה לקו\"ת ואתחנן ז, סע\"ד ואילך."],["4508","18","<b>כל הקרב קרב ביותר</b>: וראה תו\"א כז, ג. תו\"ח תולדות קמז, ג."]]],[2100990251,"הם מקבלים רק בחי' הוד וזיו מהתחלקו' אור וזיו האלקי שמתחלק בעולמו' כו' אבל אור א\"ס עצמו סובב הכל בהשווא' א' כמ\"ש השוה<sup data-n=\"4509\">19</sup> ומשוה כו' קטן וגדול שם הוא כו' אזי מיד תפול על האדם אימה ויראה בבחי' הביטול מעצמותו לגמרי וכל שמתקרב יותר יותר יבא לבחי' הביטול האמיתי כו' כידוע וא\"כ הרי מובן שהיראה היפך האהבה מן הקצה לקצה ולכאורה אינו מובן איך לפ\"ז ישכנו ב' המדו' אוי\"ר באדם יחד אחר שהם ב' הפכים ממש כנ\"ל.\n<b>אך</b> הענין הוא דהנה מ\"ש ואהבת את ה' כו' את הטפל לה' אלקיך פי' את הטפל הוא בחי' הביטול הנ\"ל שבאה בהתבוננו' מקרוב דוקא איך שהוא סובב כו' וזהו שהוא הוי' אלקיך פי' אלקיך גם בהשתלשלו' העולמו' למטה מטה בבחי' ממלא כ\"ע גם שם הוא נמצא בבחי' סובב כי אין פי' סובב למעלה ולא למטה אלא הענין הוא שהוא בחי' ההעלם דאין בחי' הגילוי תופס מקום כלל וא\"כ גם בבחי' אלקי' דממלא הוא בחי' הוי' דסובב וכמאמר דלית<sup data-n=\"4510\">20</sup> אתר פנוי מיני' פי' מיני' מבחי' סובב וכמ\"ש ואת<sup data-n=\"4511\">21</sup> השמים והארץ אני מלא אנ\"י ממש ולא כבודו וזיוו בלבד וד\"ל ומה שאמר ב' הפכי' כא' ואהבת את ה' כו' האהבה אינה באה רק מצד הריחוק כנ\"ל ואת ה' כו' היינו מצד הקירוב כנ\"ל הענין הוא דכתיב שלום<sup data-n=\"4512\">22</sup> שלום לרחוק ולקרוב כו' לרחוק<sup data-n=\"4513\">23</sup> שנעשה קרוב פי' לאכללא<sup data-n=\"4514\">24</sup> שמאלא בימינא ולעשו' מבחי' הריחוק קירוב דהיינו שיוכלל האהבה ביראה וישכנו יחד אע\"פ שהם ב' הפכי' כנ\"ל אבל ע\"י השלום יתחברו יחד כמ\"ש שלום לרחוק ולקרוב כו' אך מי הוא העושה השלום הזה הענין הוא דכתיב ויקרא<sup data-n=\"4515\">25</sup> לו ה' שלום שה' עצמו נק' שלום לפי שהוי' נק' אל עליון כלומר עליון בערך מכל ההשתלשלות עד דקמי' כחשיכ'<sup data-n=\"4516\">26</sup> כאורה כו' רוחניו' וגשמיו' שוין כו' וזהו אל<sup data-n=\"4517\">27</sup> עליון קונה שמים וארץ יחד בהשווא' א' וכנ\"ל וע\"כ על ידו דוקא יתחברו עליונים ותחתונים יחד אע\"פ שהם ב' הפכי' כי להיותו למעלה משניהם ע\"כ יוכל לחבר שניהם כמו לחבר רוחניו' בגשמיו' כו' וכענין הידוע בפי' עושה<sup data-n=\"4518\">28</sup> השלום במרומיו בין מיכאל וגבריאל שר של אש ומים ואין מכבי' זא\"ז לפי שבאה עליהם ההארה שלמעלה משניהם כו' וזהו פי' וענין הוי\"ו<sup data-n=\"4519\">29</sup> דוהנורא דכמו דגדולה וגבורה",[["4509","19","<b>השוה ומשוה כו' קטן וגדול שם הוא</b>: פיוט (לימים הנוראים) האוחז מדת משפט. וראה איוב ג, יח."],["4510","20","<b>דלית אתר פנוי מיני</b>: תקו\"ז תנ\"ז (צא, סע\"ב)."],["4511","21","<b>ואת השמים ואת הארץ אני מלא</b>: ירמי' כג, כד."],["4512","22","<b>שלום שלום לרחוק ולקרוב</b>: ישעי' נז, יט."],["4513","23","<b>לרחוק שנעשה קרוב</b>: ראה ברכות לד, ב."],["4514","24","<b>לאכללא שמאלא בימינא</b>: באוה\"ת דרושים לשבועות ע' קצב: בזוהר פ' קרח (ראה שם ר\"פ קרח ובאור החמה שם]. לקו\"ת מטות פז, ג. לעיל ע' תקמב."],["4515","25","<b>ויקרא לו ה' שלום</b>: שופטים ו, כד."],["4516","26","<b>כחשיכ' כאורה</b>: תהלים קלט, יב."],["4517","27","<b>אל עליון קונה שמים וארץ</b>: נוסח התפלה."],["4518","28","<b>עושה השלום במרומיו בין מיכאל וגבריאל</b>: איוב כה, ב. ראה במדב\"ר פי\"ב, ח. תנחומא ויגש ו. זח\"א השמטות רסג, א. מגלה עמוקות אופן קעז. אגרת הקדש סי\"ב."],["4519","29","<b>הוי\"ו דוהנורא</b>: ראה תו\"א יא, א. לקו\"ת דברים ח, ג ביאוה\"ז עז, ב. סה\"מ תקס\"ז ע' כה ואילך. מאמרי אדה\"א בראשית ע' קפ."]]],[2100990252,"המה ב' הפכי' והנורא הוא בחי' ממוצע לכוללם יחד כך בעולמו' נמשך בחי' נורא להיות על ידו שלום<sup data-n=\"4520\">30</sup> בין כל ב' הפכים כי ענין הנורא הוא עוצם גילוי אור העצמו' שמרומם ונשגב מכל ההשתלשלו' והוא הנק' אל עליון וגילוי זה הוא הנק' נורא כי בהעלמו אינו נק' נורא עד\"מ מלך ב\"ו שכאשר מתגלה ונופל האימה על עבדיו אז נק' נורא והוי\"ו הוא בחי' המשכת גילוי אורו עד שיקרא בשם נורא וזהו והנורא ולא יש וי\"ו בגדול וגיבור לפי שנורא זה ענין &lt;שיג&gt;\nגילוי דוקא כו' והוא העושה השלום לרחוק ולקרוב גם למטה להיו' האהבה במקום היראה והביטול יחד ישכנו ואינם סותרי' זא\"ז וד\"ל.\n<b>וזהו</b> ואהבת את ה' כו' אהבה וביטול יחד וזהו בא ע\"י שהאהבה היא בכל לבבך דוקא, כי פי' בכל<sup data-n=\"4521\">31</sup> לבבך היינו בשני יצריך ביצ\"ט וביצה\"ר כידוע והיינו ענין לאכפייא ולאהפכא<sup data-n=\"4522\">32</sup> חשוכא לנהורא כו' בסור<sup data-n=\"4523\">33</sup> מרע ועשה טוב גם בדברים המותרי' כמו קדש<sup data-n=\"4524\">34</sup> עצמך כו' וגם לשמור עצמו מלה\"ר ולעשו' הכל נגד טבעו כו' וזהו שומר<sup data-n=\"4525\">35</sup> פיו ולשונו שומר מצרת נפשו פי' צרת נפשו הוא ענין ובחי' המיצר והדוחק שיש בנפשו דהיינו מפני שלא תוכל לסבול בעצמה ב' הפכי' דאוי\"ר הנ\"ל זהו הנק' צרת נפשו והשמירה מזה המיצר הוא שומר פיו ולשונו מלה\"ר כו' וכיוצא בזה בכל סור מרע כו' ואז נא' הרחיבי<sup data-n=\"4526\">36</sup> מקום אהלך כו' שתתרחב הנפש לסבול ב' הפכי' דאוי\"ר כנ\"ל וזהו ענין העקידה דיצחק שהיה עקוד<sup data-n=\"4527\">37</sup> ע\"ג המזבח ממעל לעצים פי' ממעל לעצים היינו למעלה<sup data-n=\"4528\">38</sup> מעה\"ח ומעה\"ד כידוע והעקידה היתה בחי' התכללו' האוי\"ר יחד (ואמנם התכללו' זו דוקא כשהאהבה היא עיקר והיראה כלולה בה ולא בהיפך ובזה מתורץ מה שפירש שמעון דוקא מאת ה' דיראה ולא רצה לרבו' ולכלול בה האהבה להיו' בבחי' טפל כו' וד\"ל).\n<b>אך</b> הנה כל זה הוא רק בענין הרצון שרוצה שיהי' בחי' גילוי אלקו' שבאוי\"ר זו אין כאן גילוי אלקו' ממש עדיין אבל כדי שיבא לידי גילוי ממש הוא ע\"י המצות דהנה כתיב תחת<sup data-n=\"4529\">39</sup> אשר לא עבדת ה' כו' בשמחה ובטוב לבב מרוב כל פי' למעלה מרוב כל שהוא חיי העוה\"ב שנק' רוב כל וכמארז\"ל יפה<sup data-n=\"4530\">40</sup> שעה א' בתשובה ומע\"ט בעוה\"ז מכל חיי העוה\"ב והטעם הוא כי באמרו אשר<sup data-n=\"4531\">41</sup> קדשנו במצוותיו הענין הוא",[["4520","30","<b>שלום. . ב' הפכים</b>: ראה גם מאמרי אדה\"א — קונטרסים ע' שסז ואילך."],["4521","31","<b>בכל לבבך היינו בשני יצריך</b>: ואתחנן ו, ה. ראה ברכות נד, א."],["4522","32","<b>ולאהפכא חשוכא לנהורא</b>: זהר בהקדמה ד, א."],["4523","33","<b>בסור מרע ועשה טוב</b>: לשון הפסוק תהלים לד, טו."],["4524","34","<b>קדש עצמך</b>: יבמות כ, א. נדה יב, א."],["4525","35","<b>שומר פיו ולשונו שומר מצרת נפשו</b>: משלי כא, כג."],["4526","36","<b>הרחיבי מקום אהלך</b>: ישעי' נד, ב."],["4527","37","<b>עקוד ע\"ג המזבח ממעל לעצים</b>: וירא כב, ט."],["4528","38","<b>למעלה מעה\"ח ומעה\"ד כידוע</b>: ראה גם תו\"א יז, ג. לקו\"ת ואתחנן ח, ב. סה\"מ תקס\"ה ח\"ב תתקנד. תו\"ח בראשית קמז, ד. תרל\"ב ח\"א ע' ב. תרל\"ג ח\"ב ע' תקא."],["4529","39","<b>תחת אשר לא עבדת ה'</b>: תבוא כח, כז. וראה לעיל ד\"ה ועתה יגדל."],["4530","40","<b>יפה שעה א' בתשובה ומע\"ט בעוה\"ז</b>: אבות פ\"ד, מי\"ז."],["4531","41","<b>אשר קדשנו במצוותיו. . קדשנו בקדש העליון</b>: נוסח ברכת המצות. ראה לקו\"ת בהעלתך ל, ד. דרושים לר\"ה נד, א. תו\"ח שמות ז, ב."]]],[2100990253,"שקדשנו בקדש העליון שהוא בחי' סובב כ\"ע מבחי' עצמו' ומהות אור הא\"ס וע\"ז אומרי' הברכה בא\"י פי' ברוך<sup data-n=\"4532\">42</sup> הוא בחי' המשכה מלמעלה עד שיהי' נק' ג\"כ בשם מלך העולם בבחי' ממלא כו' וזהו שאמר אחר ואהבת את ה' כו' והיו הדברים האלה אשר אנכי מצוך אנכי הוא בחי' מהותו ועצמותו ית' ולא בחי' שם בלבד וענין המשכה זאת שע\"י המצות צריך להיו' בשמחה וטוב לבב דוקא והוא האהבה שאחר הביטול והיראה כי יוכל להיו' שיהי' האהבה והשמחה גם אחר שיהי' בו בחי' הביטול כענין וכל<sup data-n=\"4533\">43</sup> הלבבות יראוך וכל קרב וכליות יזמרו לשמך הרי הלב<sup data-n=\"4534\">44</sup> הוא ביראה והקרב וכליו' יזמרו בשמחה כו' ואינם סותרים זא\"ז והטעם הוא כי הקרב והכליו' הם יותר פנימיים מן הלב וע\"כ יוכל להיו' שבלב יהי' היראה והביטול ובקרב וכליו' בבחי' הפנימי' יהי' אור השמחה כי השמחה תהי' מבפנים והיראה מבחוץ וגם במקום א' ממש יוכלו לשכון יחד השמחה והיראה כענין וגילו ברעדה שאמרו ז\"ל במקום<sup data-n=\"4535\">45</sup> גילה שם תהא רעדה במקום גילה ממש כו' ואמנם אין זה אלא בשמחה של מצוה דוקא ולא בשמחה זולתה מטעם שהמצוה שרשה מבחי' סובב כ\"ע כנ\"ל שמקשר עליון ותחתון וכן ב' הפכי' אהבה ויראה כנ\"ל.\n<b>וזהו</b> תחת אשר לא עבדת כו' דוקא העבודה צ\"ל בשמחה וטוב לבב וזה גבוה גם מחיי העוה\"ב כי בעוה\"ב אין שם רק &lt;שיד&gt;\nבחי' גילוי זיו בלבד כמ\"ש בי\"ה<sup data-n=\"4536\">46</sup> צור עולמי' ביו\"ד<sup data-n=\"4537\">47</sup> נברא העוה\"ב כו' והיו\"ד הוא רק בחי' אות א' משמו ית' משא\"כ בחי' עצמו' אלקו' דאנכי כו' שאינו אלא במעשה המצות דוקא כנ\"ל וע\"כ יפה שעה א' במע\"ט בעוה\"ז גם מכל חיי העוה\"ב וד\"ל וזהו אשר אנכי מצוך היום דוקא היום כי היום<sup data-n=\"4538\">48</sup> לעשותם ולמחר כו' וידוע דאנכי<sup data-n=\"4539\">49</sup> ולא יהי' לך מפי הגבורה שמענום כו' ואח\"כ אמר ושננתם<sup data-n=\"4540\">50</sup> לבניך ודברת בם כו' פי' שבא לפרש באיזה דבר הוא שמתגלה בחי' אנכי שאמר קודם ואומר שע\"י הדיבור<sup data-n=\"4541\">51</sup> בד\"ת דוקא הוא בא בגילוי והטעם הוא כי הנה האהבה בלתי יראה אתערותא דלעילא ג\"כ כמים הפנים באהבה כזאת והוא מ\"ש שמאלו<sup data-n=\"4542\">52</sup> תחת לראשי וימינו תחבקיני פי' תחבקיני הוא ענין הארת המקיף בלבד שחופף מלמעלה עד\"מ החיבוק שמחבק ביד שאין האהבה הזאת מגעת בתוך האדם בפנימיותו ותוך תוכו וע\"כ מיד אחר התפלה חולפת ועוברת.",[["4532","42","<b>ברוך. . המשכה</b>: ראה תו\"א מקץ לז, ג. ובכ\"מ."],["4533","43","<b>וכל הלבבות יראוך</b>: פיוט נשמת. תו\"ח חיי שרה קל, רע\"מ."],["4534","44","<b>הלב הוא ביראה והקרב. . בשמחה</b>: ראה ג\"כ לקו\"ת בלק עג, א."],["4535","45","<b>במקום גילה שם תהא רעדה</b>: תהלים ב, יא. ברכות ל, ב. ראה תו\"ח בראשית לח, ב ואילך."],["4536","46","<b>בי\"ה צור עולמי'</b>: ישעי' כו, ד."],["4537","47","<b>ביו\"ד נברא העוה\"ב</b>: ראה מנחות כט, ב."],["4538","48","<b>היום לעשותם ולמחר כו'</b>: ואתחנן ז, יא. וראה עירובין כב, א."],["4539","49","<b>דאנכי ולא יהי' לך מפי הגבורה שמענום</b>: מכות כד, רע\"א."],["4540","50","<b>ושננתם לבניך</b>: ואתחנן ו, ז."],["4541","51","<b>הדיבור בד\"ת</b>: ראה הל' ת\"ת לאדה\"ז פ\"ב, הי\"ב."],["4542","52","<b>שמאלו תחת לראשי</b>: שה\"ש ב, ו. ח, ג."]]],[2100990254,"<b>וזהו</b> מצד שאין השמאל נכלל בימין אבל כשהיראה שהיא בקו השמאל נכללת באהבה ע\"ד הנ\"ל אזי יש לה קיום נצחי מפני שנכנס האור בתוך תוכו כנ\"ל ולא יעבור גם אחר התפלה בכל היום והוא השמחה אשר מבפנים ובמקום גילה שם תהא רעדה בחי' הביטול כנ\"ל וזהו ע\"י הדיבור בד\"ת דוקא כי הנה זהו מדרגת משה דכתיב בי' מחוקק כמ\"ש כי<sup data-n=\"4543\">53</sup> שם חלקת מחוקק ספון וענין החקיקה ידוע שהוא דוקא לחקוק חלל להיות כלי קיבול שיתפשט בו האור בתוך תוכו והיינו ע\"י בחי' קול דתורה שעושה בחי' החקיקה בנפש ע\"י בחי' משה<sup data-n=\"4544\">54</sup> שהוא בחי' הביטול דמ\"ה דחכמה כמ\"ש ואשים<sup data-n=\"4545\">55</sup> דברי בפיך כו' וכידוע והיינו השמחה והביטול יחד אשר שוכנים בבחי' הפנימי' דוקא וזהו וזאת<sup data-n=\"4546\">56</sup> התורה אשר שם משה לפני בנ\"י פי' שם את התורה בתוך בנ\"י בבחי' הפנימיו' שלהם להיותם בחי' כלי קיבול לקבל בתוך תוכם וזהו פי' לפנ\"י לפני דוקא וזהו קול<sup data-n=\"4547\">57</sup> קורא במדבר פנו דרך הוי' פי' קול דתורה דוקא הוא אשר מתגלה בו בחי' הוי' דסובב כ\"ע גם בבחי' המדבר כמ\"ש המגביהי<sup data-n=\"4548\">58</sup> לשבת המשפילי לראו' כו' מטעם הנ\"ל דבחי' סובב מקשר הכל בהשווא' א' דקמי' כחשיכה כאורה כו' וזהו קול קורא דתורה גם במדבר פנו שם דרך להוי' כו' וד\"ל.\n<b>וזהו</b> שאמר ושננתם לבניך ודברת בם שבדיבור דד\"ת הוא שמתגלה דוקא בחי' אנכי וע\"כ אמרו ות\"ת<sup data-n=\"4549\">59</sup> כנגד כולם ולכך סמיכת ג' אלה הפסוקי' יש להם קשר וחיבור זע\"ז כי באהבה דאת ה' אלקיך שהוא אהבה ויראה יחד כנ\"ל הוא בא לבחי' אנכי שמקשר ומחבר ב' הפכי' וגילוי זה עדיין אינו בא למטה אלא ע\"י המצות ואח\"כ בת\"ת שכנגד כולם ואח\"כ וקשרתם<sup data-n=\"4550\">60</sup> כו' כי הנה הוקשה<sup data-n=\"4551\">61</sup> כל התורה לתפילין לפי שבתפילין הרי נמשך בחי' אחד באותיו' הפרשיו' דק\"ש בפ' שמע הכתובה ע\"ג קלף גשמי וכך הוא שרש כל התורה כולה שיהי' נמשך בחי' קדושה העליונה דסובב כ\"ע גם למטה מטה כנ\"ל וד\"ל.\n<b>וזהו</b> וידעת היום והשבות אל לבבך כו', דהנה כתיב ויהי<sup data-n=\"4552\">62</sup> ערב ויהי בקר יום אחד דאין נק' יום אלא מערב ובקר יחד ומזה אמרו בגמ' דכברייתו<sup data-n=\"4553\">63</sup> של עולם ברישא חשוכא והדר נהורא דכתיב ויהי ערב כו' והענין הוא &lt;שטו&gt;\nשבתחלה נעשה בחי' הצמצום של החושך ואח\"כ נמשך בחי' ההתפשטו' הנק' אור והוא מדת יום ומדת לילה שאין יום בלא לילה לפניו שהוא בחי' הצמצום שלפני בחי' ההתפשטות וענין זה אחד עם מה שאמר אח\"כ והשבות אל לבבך דהנה ב' לבבות יש בב' מיני",[["4543","53","<b>כי שם חלקת מחוקק</b>: ברכה לג, כא. ראה ב\"ב טו, א. ביאוה\"ז בשלח מד, סע\"ד. לקו\"ת חוקת סג, ב. סד, ב."],["4544","54","<b>משה. . הביטול דמ\"ה</b>: ראה בשלח טז, ז."],["4545","55","<b>ואשים דברי בפיך</b>: ישעי' נא, טז."],["4546","56","<b>וזאת התורה אשר שם משה לפני בנ\"י</b>: ואתחנן ד, מד."],["4547","57","<b>קול קורא במדבר</b>: ישעי' מ, ג."],["4548","58","<b>המגביהי לשבת המשפילי לראו'</b>: תהלים קיג, ה-ו."],["4549","59","<b>ות\"ת כנגד כולם</b>: פאה בתחלתה."],["4550","60","<b>וקשרתם</b>: ואתחנן ו, ח."],["4551","61","<b>הוקשה כל התורה לתפילין</b>: קידושין לה, א."],["4552","62","<b>ויהי ערב ויהי בקר יום אחד</b>: בראשית א, ה."],["4553","63","<b>דכברייתו של עולם ברישא חשוכא</b>: ראה שבת עז, ב."]]],[2100990255,"התפעלו' הנ\"ל ביראה מקרוב בבחי' הביטול ובבחי' האהבה כנ\"ל שהוא בחי' הצמצום ובחי' ההתפשטו' כו' וד\"ל. אך עדיין יש להבין מה שסמך ג' עניני' אלה כא' דוידעת היום אז והשבות אל לבבך כי ה' הוא האלקי' כו' אך הענין הוא דפי' בכל<sup data-n=\"4554\">64</sup> לבבך היינו בשני יצריך ביצ\"ט כו'.\n<b>דהנה</b> כתיב ישת<sup data-n=\"4555\">65</sup> חושך סתרו וכתיב מגלה<sup data-n=\"4556\">66</sup> עמוקות מני חושך, פי' חושך הוא לשון העלם והוא בחי' העלם העצמו' והוא בחי' התוהו שקדם לבחי' התיקון וכמ\"ש והארץ<sup data-n=\"4557\">67</sup> היתה תוהו וחושך כו' וכאשר נגלה האור מבחי' העלם זה ע\"ז נאמר מגלה עמוקות מני חושך וא\"א להיות בחי' גילוי אור זה מבחי' העלם העצמו' להיות כי אין ערך כלל בין עצמות המאציל לנאצלי' ונבראי' יש מאין כידוע כ\"א ע\"י בחי' צמצום בתחלה והוא לצמצם א\"ע ולהעלים האור בתחלה עד\"מ כשאדם משפיע איזה שכל לתינוק קטן שצריך לצמצם א\"ע דהיינו ביטול עצמותו בתחלה בכדי שיוכל להשפיע בצמצום לפי ערך קבלת התינוק כידוע והנמשל מובן למעלה דבתחלה הי' צריך להיות בחי' צמצום העצמו' עד שיוכל להאיר בבחי' גילוי אור מן ההעלם וצמצום זה גורם גילוי האור בתמידו' וד\"ל.\n<b>והנה</b> ידוע דע\"י אתעדל\"ת<sup data-n=\"4558\">68</sup> נעשה אתעדל\"ע כי רוח<sup data-n=\"4559\">69</sup> אייתי רוח כו' ממש באותו האופן שמעלין מ\"ן באתעדל\"ת כך יהי' אופן אתעדל\"ע בהמשכת מ\"ד כו' וכך גם בענין בחי' ביטול וצמצום העצמו' הנ\"ל הרי נעשה למעלה ע\"י אתעדל\"ת דוקא והוא בבחי' ביטול העצמו' באדם התחתון דהיינו דוקא בביטול רצון הטבעי בסור<sup data-n=\"4560\">70</sup> מרע ועשה טוב שיהא הכל נגד רצונו הטבעי והוא להיות מבטל עצמותו לגמרי נגד רצון ה' שמלובש בתורה ומצות כמאמר בטל<sup data-n=\"4561\">71</sup> רצונך כו' וזהו הנק' לאכפייא כו' והיינו בכל לבבך בשני יצריך ביצ\"ט וביצה\"ר דוקא והוא כשיהי' כפוף היצה\"ר ויהי' נכלל ביצ\"ט בעסק התורה והמצו' ובכל מיני כפיי' במדו' הרעות להפוך הכל לטוב ולקדושה האלקית עי\"ז נעשה ג\"כ אתעדל\"ע באופן כזה והוא להיו' למעלה באלקו' בחי' ביטול עצמותו ולהיו' מגלה עמוקות מני חושך ע\"י צמצום זה כנ\"ל וד\"ל.\n<b>וזהו</b> וידעת היום והשבות אל לבבך כו', פי' דוקא בכל לבבך בשני יצריך כנ\"ל והיינו כדי לחבר למעלה מדת יום במדת לילה שהוא הנק' יום כמ\"ש ויהי ערב ויהי בקר כו' וכמארז\"ל ברישא חשוכא והדר נהורא פי' בתחלה להיו' צמצום",[["4554","64","<b>בכל לבבך. . בשני יצריך</b>: ספרי ואתחנן ו, ה. ברכות נד, א (במשנה)."],["4555","65","<b>ישת חשך סתרו</b>: תהלים יח, יב."],["4556","66","<b>מגלה עמוקות מני חושך</b>: איוב יב, כב."],["4557","67","<b>והארץ היתה תוהו וחושך</b>: בראשית א, ב."],["4558","68","<b>אתעדל\"ת נעשה אתעדל\"ע</b>: ראה זהר לך פח, א. וראה תו\"א בראשית ב, ב. הוספות מג\"א קיט, ד."],["4559","69","<b>רוח אייתי רוח</b>: ראה זהר תרומה קסב, ריש ע\"ב. וירא צט, ריש ע\"ב. סידור ערב שבת קסג, ד. אמרי בינה שער התפילין פל\"א."],["4560","70","<b>בסור מרע ועשה טוב</b>: לשון הפסוק תהלים לד, טו."],["4561","71","<b>בטל רצונך</b>: אבות פ\"ב, מ\"ד."]]],[2100990256,"האור ואח\"כ בחי' גילוי אור בהתפשטו' כנ\"ל שזהו אינו אלא ע\"י אתעדל\"ת דוקא ג\"כ באופן כזה והוא במה שאמר והשבות אל לבבך בהתהפכו' וביטול הנפש הבהמיו' בבחי' ביטול הרצון כנ\"ל והיינו שסמך ענין וידעת היום להיו' חיבור יום ולילה עם מ\"ש והשבות אל לבבך מפני שזה תלוי בזה וד\"ל.\n&lt;שטז&gt;\n<b>כי</b> הוי' הוא האלקי' בשמים ממעל וכו', דהנה אמרו ז\"ל במקום<sup data-n=\"4562\">72</sup> גדולתו שם אתה מוצא ענותנותו ויש להבין מהו שאמר ש\"ם אתה מוצא ש\"ם דוקא הל\"ל במקום גדולתו ענותנותו, אך הענין הוא דהגדולה והענוה הרי המה ב' הפכי' שהגדולה הוא בחי' ההתפשטו' במרחב גדול והענוה היא היפך ההתפשטו' (אלא) ואדרבה מלבד בחי' העדר ההתפשטו' אף גם הוא בצמצום וביטול עצמותו מכל וכל כו' ולהיות כן לא ישכנו ב' מדות הללו באדם כא' בשעה ורגע אחת שבשעה שהוא במדת הגדולה וההתפשטו' א\"א להיו' אז בבחי' הצמצום כו' אבל מדת הקדב\"ה אינו כמדת ב\"ו וע\"כ אמרו דגם במקום גדולתו שם אתה מוצא ענותנותו פי' שם דוקא באותה מדת הגדולה שם נמצאת מדת הענוה ואינם ב' הפכי' כלל וד\"ל.\n<b>ולהבין</b> טעם ושרש לזה הנה הוא מובן עפ\"י הנ\"ל, דהנה בחי' הגדולה למעלה הוא בחי' ההתפשטו' גילוי אור וכמ\"ש ולגדולתו<sup data-n=\"4563\">73</sup> אין חקר כי כמו שהוא בעצם בחי' א\"ס כך אין סוף להתפשטותו כנודע ובחי' הענוה למעלה הוא בחי' הצמצום והעדר ההתפשטו' אלא אדרבה בחי' ביטול עצמותו כו' וע\"ד הנ\"ל בפי' ישת חושך סתרו כו' ובאמת אם הי' בחי' האור הנשפע ערך והשתוות אל עצמו' אור א\"ס כמו אצל האדם שגדולתו יש לה ערך אליו כו' א\"כ גם למעלה הרי היה מדת הענוה היפך מדת הגדולה ולא היו שוכנים כא' כו' אבל מאחר שנא' לך<sup data-n=\"4564\">74</sup> ה' הגדולה כו' שאין לההתפשטו' גילוי אור ערך אליו כלל וכלל כביטול זיו השמש כו' א\"כ אין ב' מדו' הללו הענוה והגדולה סותרים זא\"ז לגבי בחי' עצמות אור הא\"ס וכמ\"ש קמי' כחשיכה כאורה פי' חושך הוא הצמצום והאור הוא הגילוי שניהם שוין לפניו ממש שזהו לעתיד ולילה כיום יאיר כחשיכה כאורה כו' והיינו שאמרו במקום גדולתו שם אתה מוצא ענותנותו פי' במקום א' ממש ישכנו בחי' ההעלם והצמצום שהוא ענותנותו עם מדת ההתפשטו' שהוא בחי' הגדולה ואינם ב' הפכי' כלל משום דקמי' כחשיכה כאורה וד\"ל.\n<b>ועתה</b> יובן עוד דמלבד שמבואר דמטעם דקמי' כחשיכה כאורה כו' ע\"כ בחי' הצמצום עם בחי' ההתפשטו' באין כאחד מעצמו' המאציל הנה ידוע דמפני עוצם רוממותו דוקא יוכל לירד ולהשפיל א\"ע ביותר דזה הכלל<sup data-n=\"4565\">75</sup> ידוע דכל הגבוה",[["4562","72","<b>במקום גדולתו שם אתה מוצא ענותנותו</b>: ראה תניא פ\"ד. אגה\"ק ס\"ח. והוא ממגילה לא, א ע\"פ גירסת דקדוקי סופרים שם. וראה בהנסמן בליקוט פירושים חיטריק לאגה\"ק שם (ע' קצ)."],["4563","73","<b>ולגדולתו אין חקר</b>: תהלים קמה, ג."],["4564","74","<b>לך ה' הגדולה</b>: דברי הימים-א כט, יא."],["4565","75","<b>הכלל ידוע דכל הגבוה גבוה יותר</b>: ראה שערי אורה שער הפורים נה, א. סה, א. לעיל (ח\"א) ע' תח. ע' תסא."]]],[2100990257,"גבוה ביותר יותר יוכל להשפיל א\"ע כמ\"ש המגביהי לשבת כו' המשפילי לראות וכו' וא\"כ גם כאן יובן עוד דמה שיוכל להשפיל א\"ע זהו מפני עוצם רוממו' עצמו' המאציל והיינו במקום גדולתו פי' מפני עוצם גדולתו בעצמותו יוכל ג\"כ להיות בצמצום הענוה ושם אתה מוצא ענוותנותו לפי ערך הרוממו' וע\"ד הנ\"ל שצמצום העלם העצמו' אינו נק' צמצום אלא מה שמצמצם העלם עצמותו בתחלה לבא לידי גילוי אור הוא הנק' צמצום וזה תלוי בערך גדולת עצמותו ונמצא מובן שיש ג' מדרגו' א' העלם גדולת עצמותו והב' הצמצום והג' הגילוי אור שאחר הצמצום וד\"ל.\n<b>וזהו</b> כי הוי' הוא האלקי' פי' בחי' הצמצום נק' אלקים והוא לפני התפשטו' דשם הוי' כמאמר ברישא חשוכא והדר נהורא כו' ולהיו' כי הגדולה והענוה שניהם שווין לקמי' העצמו' ע\"כ אמר כי ה' הוא האלקי' הכל א' משום דקמי' כחשיכה כאורה כנ\"ל וד\"ל. ומה שאמר עוד בשמים ממעל כו' בא לפרש עוד &lt;שיז&gt;\nענין אחר והוא בפי' ענין העלם העצמו' שקודם גם לבחי' הצמצום כנ\"ל וכפי פי' הב' הנ\"ל במאמר במקום גדולתו שם אתה מוצא ענוותנותו שלפי ערך הרוממו' בעצמו' כך יוכל לירד ולהשפיל א\"ע כו' וזהו שאמר בשמים ממעל ועל הארץ מתחת אין עוד, פי' בשמים ממעל הוא עצם הרוממו' שאין לו שיעור למעלה בעילוי אחר עילוי וכשם שאור א\"ס אין לו שיעור למעלה עד אין קץ כו' כך למטה עד אין תכלית הוא מתפשט כי א\"ס להתפשטותו ולפי שהכל שיעור א' דלפי עומק<sup data-n=\"4566\">76</sup> רום כך עומק תחת כמ\"ש בס' יצירה ע\"כ בשמים ממעל ועל הארץ מתחת דהיינו בעומק רום ובעומק תחת הכל אין עוד אבל בהשווא' א' משום דהא בהא תליא ומשניהם כאחד הוא שניתן שיעור ומדה במדת יום ובמדת לילה למטה בגילוי אור א\"ס בנאצלי' ונבראי' דהיינו מ\"ש ויהי ערב ויהי בקר כו' ברישא חשוכא והדר נהורא כו' שיהי' בהשווא' א' ג\"כ אך במדה ושיעור כמ\"ש ויהי ערב כו' אבל באמת צמצום והתפשטו' הללו אין להם שיעור מדת יום אין לו שיעור למטה ומדת לילה אין לו שיעור למעלה כנ\"ל וזהו כי ה' הוא האלקי' בחי' הצמצום עם בחי' ההתפשטו' שניהם בבחי' א\"ס ממש משום דבשמים ממעל ועל הארץ מתחת אין עוד בבחי' א\"ס וד\"ל.",[["4566","76","<b>עומק רום כך עומק תחת כמ\"ש בס' יצירה</b>: ראה ס\"י פ\"א מ\"ה."]]],[2100990258,"<h3>להבין שרש הדברים</h3>\n<b>בעזר\"ה</b>\n<b>להבין</b><sup data-n=\"4567\">1</sup> שרש הדברים הנ\"ל. הנה בתשובת<sup data-n=\"4568\">2</sup> מהרי\"ל הקשה במאמר זה דשמעון העמסוני הי' דורש כל אתין כו' האיך דרש ואהבת את ה' ולמה לא פירש עד שהגיע לאת ה' אלקיך תירא כו'. אך הענין הוא דשרש בחי' את היינו בחי' מל'<sup data-n=\"4569\">4</sup> שנק' את וכמ\"ש וברכת<sup data-n=\"4570\">5</sup> את ה' כו' וכמבואר בזוהר<sup data-n=\"4571\">6</sup> ע\"פ ברכו ה' מלאכיו כו' מטעם דבחי' מל' נבנית מבחי' אותיו' וכללותם מא' עד תי\"ו וז\"ש ואתה<sup data-n=\"4572\">7</sup> מחי' את כולם כידוע והנה ידוע דבחי' מל' היא נקרא' סופא דכל דרגין כו' וע\"כ נק' ג\"כ בשם את הוי' כי ענין את הוא בחי' הטפל כו' לפי שהיא בחי' טפל להוי' שהוא בחי' ז\"א דאצי' כו' וידוע דמדת היראה הוא בבחי' המל' שנק' יראה תתא' כמ\"ש שום<sup data-n=\"4573\">8</sup> תשים עליך מלך וא\"כ א\"א לרבות מתיבת את כ\"א בחי' היראה דוקא לפי שהיראה נק' את כנ\"ל אבל א\"א לרבות האהבה מתיבת את אחר שאין תיבת את סובל כלל ענין ופי' אהבה ולזה באת<sup data-n=\"4574\">3</sup> ה' אלקיך תירא א\"א כלל לרבות האהבה מתיבת את אחר שאהבה לא נק' את אמנם באת דואהבת את ה' כו' יוכל לרבות היראה מתיבת את כי היראה נק' את להיותה בחי' טפל כנ\"ל וע\"כ לא פירש עד שהגיע לאת ה' אלקיך תירא דוקא ולא פירש באת דאהבה לפי שריבה בה מדת היראה ובזה מתורץ קושיית מהרי\"ל גם ע\"ד הפשט וד\"ל.\n&lt;שיח&gt;\n<b>ועתה</b> יש להבין שרש ענין ואהבת את ה' כו'. דהנה בעבודת ה' ידוע שהאהבה מרחוק דוקא היא עד\"מ מי שעומד בקרוב אל המלך בהיכלו פנימה הרי אין לו אהבה ותשוקה אל המלך כ\"א בחי' אהבה בתענוגי' שמתענג על כבוד הדרת מלך כו' משא\"כ אם עומד מבחוץ שתגדל תשוקתו ליכנס בהיכל המלך כו' וכמ\"כ יובן למשכיל בעבודת ה' שמ\"ש צמאה<sup data-n=\"4575\">9</sup> לך נפשי כו' כמו בארץ ציה ועיף בלי מים דוקא היינו הסיבה לתגבורת האהבה משא\"כ ביראה נהפוך הוא שמקרוב דוקא יתפעל ביראה וכמ\"ש וירא<sup data-n=\"4576\">10</sup> העם וינועו ויעמדו מרחוק פי' כי מה שעמדו מרחוק הי' כדי לברוח מן היראה הגדולה הזאת דמפני שנפל עליהם יראה גדולה כשעמדו מקרוב דוקא ע\"כ נסוגו אחור שתפול מעליהם היראה הרי עיקר היראה מקרוב כו' וא\"כ הרי האהבה והיראה ב' הפכי' וצריך לחברם יחד ולעשו' שלום ביניהם וכמ\"ש שלום<sup data-n=\"4577\">11</sup> לרחוק כו' לרחוק שנעשה קרוב כו' וכמ\"ש למעלה והשלום הזה נעשה מבחי' וי\"ו<sup data-n=\"4578\">12</sup> דוהנורא.",[["4567","1","<b>להבין שרש הדברים הנ\"ל</b>: הנחת כ\"ק אדמו\"ר האמצעי, נעתק מגוכתי\"ק 1025 (פו, ב)."],["4568","2","<b>בתשובת מהרי\"ל הקשה במאמר זה</b>: סימן סא. ראה ג\"כ לקו\"ת (כאן) ואתחנן. סה\"מ תקס\"ג ח\"ב ע' תרצה (נדפס ג\"כ במאמרי אדה\"ז הקצרים ע' שכח. אוה\"ת דברים כרך ה' ע' ב'כ)."],["4569","4","<b>מל' שנק' אות</b>: ראה ג\"כ לקו\"ת נשא כז, ב."],["4570","5","<b>וברכת את ה'</b>: עקב ח, יו\"ד."],["4571","6","<b>בזוהר ע\"פ ברכו ה' מלאכיו</b>: ראה זהר בלק דק\"צ ע\"ב ואילך."],["4572","7","<b>ואתה מחי' את כולם</b>: נחמי' ח, ו."],["4573","8","<b>שום תשים עליך מלך</b>: שופטים יז, טו."],["4574","3","<b>באת ה' אלקיך תירא</b>: ואתחנן ו, יג."],["4575","9","<b>צמאה לך נפשי</b>: תהלים סג, ב."],["4576","10","<b>וירא העם וינועו ויעמדו מרחוק</b>: יתרו כ, טו."],["4577","11","<b>שלום לרחוק כו' לרחוק שנעשה קרוב</b>: ישעי' נז, יט. ראה ברכות לד, ב."],["4578","12","<b>וי\"ו דוהנורא</b>: תפלת העמידה. וראה מאמרי אדה\"ז — ענינים ע' נא."]]],[2100990259,"<b>ולהבין</b> זה יש להקדים תחלה שרש ענין אוי\"ר למעלה דהנה ידוע דאותיו' שם<sup data-n=\"4579\">13</sup> הוי' הן ד' עולמו' אבי\"ע בכלל היו\"ד הוא באצי' והה\"א בבריא' והוי\"ו ביצי' כו' כמאמר אור<sup data-n=\"4580\">14</sup> אבא מקנן באצי' ואימא מקננ' בבריא' וז\"א ביצי' ומל' בעשי' כו' וביאור הדברים הנה פי' אצילות<sup data-n=\"4581\">15</sup> מלבד ענין ההפרשה יש בו ג\"כ פי' אצל וסמיכות כמו ואהי'<sup data-n=\"4582\">16</sup> אצלו אמון כו' והטעם הוא להיו' בבחי' האצי' עדיין הכל ביחוד עליון כי שם איהו<sup data-n=\"4583\">17</sup> וחיוהי וגרמוהי חד כידוע וע\"כ כללות בחי' האצילות הוא בחי' היראה אשר היא מקרוב דוקא כי בחי' האצי' קרוב הוא אל אור א\"ס כו' וע\"כ היו\"ד באצי' בכלל כנ\"ל דאור אבא מקנן באצי' כו' שהוא בחי' כח מה דחכמה שהוא בחי' ביטול המציאו' להיות כי היראה בחכמה תלוי' כמאמר אם<sup data-n=\"4584\">18</sup> אין חכמה אין יראה ואם אין יראה אין חכמה כו' וא\"כ החכמה והיראה ענין א' הם מאחר דהא בהא תליא והטעם הוא לפי שהיראה בחי' ביטול הוא וגם החכמה בבחי' ביטול הוא כידוע וחכמה דאצי' להיותו מקרוב נופל בו בחי' היראה כמאמר בראשית<sup data-n=\"4585\">19</sup> ירא בושת כי מקרוב הוא כנ\"ל והוא בחי' הביטול דחכמה דאצי' כי בחי' חכמה<sup data-n=\"4586\">20</sup> דאצי' הוא ראשית הגילוי מן ההעלם דכתר דאצי' כמשי\"ת בסמוך ונק' החכמה<sup data-n=\"4587\">21</sup> ירא' עילא' והמל' ירא' תתא' כמבואר בר\"מ בסדר דשם הוי' שהיו\"ד בחכמ' כו' שהן נקראי' דחילו<sup data-n=\"4588\">22</sup> ורחימו רחימו ודחילו דחילו ורחימו י\"ה או\"א רחימו דחילו ו\"ה זו\"נ כו' ע\"כ בכלל היו\"ד באצי' אבל הה\"א בבריא' לפי שמשם<sup data-n=\"4589\">23</sup> יפרד כו' והוא עומד מרחוק ולא מקרוב לא שייך שם בחי' הירא' שהוא בחי' הביטול דחכמ' כמו באצי' אלא דוקא האהבה שבאה מצד ההתבוננו' דה\"א ראשונה שבשם הוי' שהוא בחי' בינה והיינו דאימא<sup data-n=\"4590\">24</sup> מקננא בכורסייא כו' וע\"כ משם יפרד להיו' נמצא גם עה\"ד טו\"ר כו' משום דבינה<sup data-n=\"4591\">25</sup> מינה דינין מתערין עד\"מ ההתלהבו' שמסתעף מזה הכעס כו' וכמ\"ש במ\"א משא\"כ בביטול דחכמה שבאצי' אין שם שרש יניק' לרע כלל כידוע וד\"ל.",[["4579","13","<b>שם הוי' הן ד' עולמו' אבי\"ע</b>: ראה ע\"ח (שער סדר אצי') ש\"ג פ\"א. לקו\"ת להאריז\"ל בראשית עה\"פ (ג, כג) וישלחהו ה\"א."],["4580","14","<b>אור אבא מקנן באצי'</b>: רמ\"ז לזח\"ב רכ, ב. תו\"א משפטים עה, א. ועוד."],["4581","15","<b>אצילות. . ההפרשה</b>: ראה פרדס שער טז (שער אבי\"ע) בתחלתו. וראה תו\"א ג, א."],["4582","16","<b>ואהי' אצלו אמון</b>: משלי ח, ל."],["4583","17","<b>איהו וחיוהי וגרמוהי חד</b>: תקו\"ז בהקדמה יז, א."],["4584","18","<b>אם אין חכמה אין יראה</b>: אבות פ\"ג, מי\"ז. וראה תניא ספכ\"ג, רפמ\"ג. סידור שער הציצית ה, א. אמרי בינה שער הציצית פו, ריש ע\"ד."],["4585","19","<b>בראשית ירא בושת</b>: בראשית א, א. ת\"ז ת\"ז ותכ\"ח."],["4586","20","<b>חכמה דאצי' הוא ראשית הגילוי</b>: ראה תהלים קיא, א. וראה לקו\"ת ברכה צח, ב. שה\"ש יח, ד. אוה\"ת מג\"א ע' קלג ואילך."],["4587","21","<b>החכמה ירא' עילא'</b>: ראה לקו\"ת ויקרא ו, ד. במדבר יז, ג. נשא כא, א. שלח מג, ג. מטות פב, א. ראה כז, ג."],["4588","22","<b>דחילו ורחימו</b>: ראה תקו\"ז ת\"י (כה, ב). וראה תניא פט\"ז ואילך."],["4589","23","<b>שמשם יפרד</b>: לשון הפסוק בראשית ב, יו\"ד."],["4590","24","<b>אימא מקננא בכורסייא</b>: תקו\"ז ת\"י (כג, א)."],["4591","25","<b>דבינה מינה דינין מתערין</b>: ראה זהר ויקרא י, סע\"ב. יא, רע\"א."]]],[2100990260,"<b>והנה</b> בחי' הכתר דאצי' נק' אל עליון להיותו עליון בבחי' ההעלם של עצמות המאציל עדיין ועליו נא' ישת<sup data-n=\"4592\">26</sup> חושך סתרו וכן מגלה עמוקות מני חושך כו' והחכמה היא בחי' ראשית הגילוי מהעלם דכתר זה &lt;שיט&gt;\nוכמ\"ש והחכמה<sup data-n=\"4593\">27</sup> מאין תמצא מאין דהעלם הכתר וע\"כ נק'<sup data-n=\"4594\">28</sup> החכמה אתה כמ\"ש כי<sup data-n=\"4595\">29</sup> אתה אבינו לפי שאתה בחי' הגילוי הוא כידוע דג' מדרגו' נקראו בשם אתה ע\"ש בחי' ראשית הגילוי והן חכמה וחסד ומלכו' החכמה מטעם שהיא ראשית הגילוי מן הכתר כנ\"ל והחסד להיותו ראשית הבנין בו\"ק דז\"א כמ\"ש כי<sup data-n=\"4596\">30</sup> אמרתי עולם חסד יבנה וכן כי<sup data-n=\"4597\">31</sup> זכר חסדו כו' והמלכות להיותה באה בבחי' התפשטו' ממש להחיות רוח שפלים והיינו בבחי' אותיו' ממש וכמ\"ש ואתה<sup data-n=\"4598\">32</sup> מחי' את כולם באותיו' דמא' עד תי\"ו כידוע וד\"ל ואמנם הנה כתיב או<sup data-n=\"4599\">33</sup> יחזק במעוזי יעשה שלום לי שלום יעשה ב'<sup data-n=\"4600\">34</sup> שלומו' בפמליא ש\"מ ובפשמ\"ט והיינו בין י\"ה שנק' פשמ\"ע ובין ו\"ה שנק' פשמ\"ט כמ\"ש במ\"א.\n<b>וביאור</b> ענין זה השלום הנה זה השלום בא מבחי' אור הכתר דוקא דהנה הכתר<sup data-n=\"4601\">35</sup> נק' נורא והוא בחי' ת\"ת דא\"א והוי\"ו דוהנורא הוא הארת אור הכתר למטה לעשו' שלום בין י\"ה שהן חו\"ב<sup data-n=\"4602\">36</sup> תרין ריעין כו' שהמה שרש לאוי\"ר כי דחילו ורחימו הן י\"ה כנ\"ל והטעם שנעשה השלום בין ב' הפכי' די\"ה הוא לפי שאור הכתר בעצמו נבדל הוא בערך מחו\"ב כי הרי נק' אל עליון להיותו בבחי' ההעלם כנ\"ל כמ\"ש ישת חושך סתרו וע\"כ בבוא ההארה העליונה הזאת לחו\"ב מתבטלי' אורו' דחו\"ב לגבי בחי' ההעלם דכתר ונעשה בהם בחי' ההתכללות והיו לאחדים ממש כדוגמא שמצינו בשלום שנעשה בין מיכאל וגבריאל מפני כשמאיר עליהם אור האלקי שלמעלה משניהם מתבטלי' לגמרי כו' וכמ\"ש במ\"א וזהו יעשה שלום לי בפשמ\"ע ע\"י ווי\"ו דוהנורא שנמשך להיו' אל עליון על חו\"ב ואז נק' החכמה ירא' עילא' כנ\"ל דכאשר הכתר נק' נורא נק' החכמה יראה שירא מן הכתר ומתבייש כמאמר בראשית ירא בושת כו' וממילא מובן איך שנעשה שלום זה באוי\"ר דחילו ורחימו הגם שהם ב' הפכי' כנ\"ל דזה מקרוב וזה מרחוק וכמ\"ש שלום לרחוק לרחוק שנעשה קרוב דמן האהבה נעשה ירא' ומהירא' אהבה דהיינו בבחי' ההתכללו' מטעם דנתגלה בחי' אור הכתר דישת חושך סתרו ולא שייך שם כלל בחי' התפעלו' כלל לא אהבה ולא יראה מאחר שהוא נעלם בבחי' העלם עצמו' המאציל ואיננו מושג כלל באצי' עד שיתכן הסתעפות ההתפעלו' ממנו באוי\"ר כי התפעלו' אוי\"ר לא שייך אלא בדבר המושג דוקא כידוע והוא אור הבא דוקא בבחי' הגילוי כו' וזהו פי' הגדול",[["4592","26","<b>ישת חשך סתרו. . מגלה עמוקות מני חושך</b>: תהלים יח, יב. איוב יב, כב."],["4593","27","<b>והחכמה מאין תמצא</b>: איוב כח, יב."],["4594","28","<b>נק' החכמה אתה</b>: ראה ג\"כ דרך מצותיך קפד, א."],["4595","29","<b>כי אתה אבינו</b>: ישעי' סג, טז."],["4596","30","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["4597","31","<b>כי זכר חסדו</b>: תהלים צח, ג."],["4598","32","<b>ואתה מחי' את כולם</b>: נחמי' ח, א."],["4599","33","<b>או יחזק במעוזי</b>: ישעי' כז, ה."],["4600","34","<b>ב' שלומו' בפמליא ש\"מ</b>: נסמן לעיל ע' תמט — במיכאל וגבריאל."],["4601","35","<b>הכתר נק' נורא</b>: ראה ג\"כ תו\"ח חיי\"ש קלט, ג. קמח, א. מאמרי אדה\"א נביאים וכתובים ע' תקמט ואילך."],["4602","36","<b>חו\"ב תרין ריעין</b>: ראה זח\"ג ד, א."]]],[2100990261,"הגבור והנורא ה' דהגדול הוא מקור החסדי' דקו הימין חח\"נ וה' דגבור מקור הגבורו' בקו השמאל והוי\"ו דוהנורא<sup data-n=\"4603\">37</sup> שהוא בחי' ת\"ת שבכתר הוא המכריע ועושה שלום בב' הקוין כו' והיינו שלום בפשמ\"ע וד\"ל.\n<b>וכמ\"כ</b> יובן ענין השלום כזה שנעשה בין י\"ה כך נעשה בו\"ה והן רחימו דחילו שהן אהבה דז\"א וירא' תתא' דמלכו' שהן נק' ו\"ה כידוע והטעם שבחי' ז\"א הוא בבחי' אהבה הוא להיותו רובו מבחי' החסדי' כמ\"ש כי זכר חסדו כו' והוי\"ו מורה על בחי' החסדי' והה\"א דמל' הוא בחי' ירא' תתא' וגם הם מתכללים זה בזה והיו לאחדים מפני התכללות של חו\"ב שלמעלה מהם ע\"י וי\"ו דוהנורא כנ\"ל וזהו השלום בפשמ\"ט וד\"ל.\n<b>וזהו</b> שרש ענין ואהבת את הוי' פי' א\"ת הוי' א\"ת דירא' דמלכו' שנק' ירא' תתא' שנכללת באהבה וחסד דז\"א או לפי הנ\"ל בשרש דחילו ורחימו שהן &lt;שכ&gt;\nי\"ה הרי יו\"ד החכמה נק' ירא' ונכללת באהבה דה\"א דבינה וכמ\"ש שלום לרחוק דוקא לרחוק שנעשה קרוב וירא' עילא' נכללת באהבה כו' וזה היה ענין העקידה דיצחק שהי' יראה ופחד<sup data-n=\"4604\">38</sup> דיצחק נכלל באברהם איש החסד כו' ויש התכללות בהיפך שהאהבה נכללת ביראה כענין וכל<sup data-n=\"4605\">39</sup> קרב וכליו' יזמרו לשמך כו' שהלב ביראה ופחד והקרב וכליו' יזמרו הרי הירא' מבחוץ והאהבה נכללת בפנים והטעם הוא כי נקבה<sup data-n=\"4606\">40</sup> תסובב גבר דהיינו שהנוק' נגלית למטה בבחי' חיצוניו' והמשפיע שהוא הגבר לעולם הוא מבפנים וכך היראה נגלית מבחוץ כי המל' נק' ירא' תתא' ואהבה דחסד שהוא הזמרה בפנים היא בקרב וכליו' וע\"כ אמר וכל קרב וכליו' יזמרו ולא אמר וכל פה יזמר כי עיקר רננה<sup data-n=\"4607\">41</sup> בפה דוקא הוא כידוע אך הענין הוא משום דבכאן היראה תסובב מבחוץ ולא יוכל לבא אור האהבה דרננה בפה מפני הירא' אלא נשאר הרינון רק בכליות וקרב מבפנים וגם ללב לא יוכל הרינון להתפשט כי הלב מלא ירא' ופחד כמו שאמר וכל הלבבו' יראוך כו' ע\"כ נשאר הרינה בתוך היותר פנימי והן הקרב וכליו' כי מטעם שהמנגד מתפשט כולו מבחוץ בהכרח שיברח ממנו ויתכווץ אל תוך תוכו כדוגמא שמצינו בהיפך זה ממש באברהם שהי' איש החסד ולכאורה יפלא שלא הי' לאברהם מדת הירא' ופחד אלא ודאי הי' בו רק שמפני שגבר בו אור האהבה מבחוץ ובהתפשטו' עד שהירא' ופחד שבתוכו הוכרח לברוח ולהתכווץ אל תוך תוכו וכמ\"ש וארכבותי'<sup data-n=\"4608\">42</sup> דא לדא נקשן כו' וד\"ל, וכל זה השינוי באופן ההתכללו' אם הירא' מבחוץ או האהבה מבחוץ תלוי בהארת המשפיע והוא באור הכתר דנק' נורא כי עד\"מ המלך שפניו מאירו' בחדוה לשריו היושבי' עמו הרי ישמחו גם הם עמו",[["4603","37","<b>דוהנורא שהוא בחי' ת\"ת</b>: ראה ג\"כ תו\"א נח יא, א."],["4604","38","<b>ופחד דיצחק</b>: לשון הפסוק ויצא לא, מב."],["4605","39","<b>וכל קרב וכליו' יזמרו לשמך</b>: תפלת נשמת כל חי."],["4606","40","<b>נקבה תסובב גבר</b>: ירמי' לא, כא."],["4607","41","<b>רננה בפה</b>: ראה זהר ויקרא ח, ב. סוכה נא, א."],["4608","42","<b>וארכבותי' דא לדא נקשן</b>: דניאל ה, ו."]]],[2100990262,"אבל הביטול והפחד יתכווץ אצלם בתוך תוכם בקרב וכליו' ואם המלך מראה להם פנים זועפו' יהי' בהיפך כו' וכמ\"ש במ\"א וד\"ל.\n<b>ועתה</b> יש להבין שרש ענין והיו הדברים האלה אשר אנכי כו'. דהנה אנכי<sup data-n=\"4609\">43</sup> הוא בחי' כתר עליון שנק' אנכי<sup data-n=\"4610\">44</sup> כלומר מי שאנכי וידוע דשרש המצות מבחי' הכתר הם באי' ונמשכי' כי תרי\"ג<sup data-n=\"4611\">45</sup> ארחי' דגלגלתא דא\"א משם שרש המצות כידוע וזהו והיו הדברים האלה אשר אנכי מצוך היום דוקא היום ולא לע\"ל משום דהיום<sup data-n=\"4612\">46</sup> לעשותם ולמחר לקבל שכרם והנה השכר הוא מה שנהנין<sup data-n=\"4613\">47</sup> מזיו השכינה בעוה\"ב וזה הזיו אינו אלא בחי' הארה בעלמא בלבד שמאיר ובא מבחי' הכתר ונק' זיווא עילא' דע\"י והוא טלא<sup data-n=\"4614\">48</sup> דנטיף מעתיקא להחיו' בו המתים כמ\"ש כי<sup data-n=\"4615\">49</sup> טל אורו' טלך כו' כידוע אבל המצות עצמם שנעשי' בפועל היום הרי הם באים ונמשכי' מבחי' עצמו' הכתר והוא בחי' גילוי אנכי ממש וזהו אשר אנכי מצוך היום דוקא ולא לע\"ל להיו' כי היום במעשה מתגלה בחי' אנכי ממש ולמחר בקבלת שכר לא יגלה רק בחי' הזיו בלבד דמאחר שמושג בנבראי' בהכרח שהוא בא רק מבחי' זיו בלבד והיינו שאמרו דיפה שעה א' בתשובה ומע\"ט בעוה\"ז מכל חיי העוה\"ב כו' וגם זהו מ\"ש בשמחה וטוב לבב מרוב כל כנ\"ל ואמנם הנה שמחה זו של מצוה להיותה מבחי' אור הכתר ע\"כ בכחה להיו' בבחי' השלום בין ב' הפכי' &lt;שכא&gt;\nאוי\"ר והיינו שמחה וביטול יחד ולא ע\"ד הנ\"ל בפי' וכל קרב וכליו' יזמרו שהחדוה בפנים והיראה מבחוץ אלא היפך זה שהחדוה והשמחה של מצוה מאירה מבחוץ והירא' והביטול מבפנים ואז יוכל להיו' הרינון בפה דוקא ולא בקרב וכליו' בלבד וזהו בשמחה ובטוב לבב היפך ענין וכל הלבבו' יראוך כו' והיינו חיבור וקשר הפסוקי' ואהבת את הוי' שהירא' מבפנים כו' ואז והיו הדברי' האלה אשר אנכי מצוך על לבבך בשמחה של מצוה שהיא בטוב לבב דוקא ברננה דפה ואח\"כ אמר ושננתם לבניך ודברת בם ודוקא בדיבור כו' כמ\"ש קול<sup data-n=\"4616\">50</sup> קורא במדבר פנו דרך הוי' כו' לפי שהתורה הוא בחי' קו האמצעי בחי' דת\"י שעולה עד בחי' פנימית הכתר וע\"כ בתורה תלוי' סיבת השלום בפשמ\"ע כו' כמ\"ש או יחזק במעוזי ולפי שע\"י הדיבור והקול הקדב\"ה<sup data-n=\"4617\">51</sup> יושב ושונה כנגדו להמשיך מהעלם דכתר בחכמה כו'.\n<b>ובזה</b> מובן מ\"ש שומר<sup data-n=\"4618\">52</sup> פיו ולשונו שומר מצרת נפשו להיו' חיבור ב' הפכי' כנ\"ל דוקא בשמירת פיו מדברי' בטילי' כו' לפי שבקול קורא בתורה צריך להיו'",[["4609","43","<b>אנכי הוא בחי' כתר</b>: ראה זהר (רע\"מ) פינחס רנו, ב."],["4610","44","<b>אנכי. . מי שאנכי</b>: ראה תניא מהדורא קמא ספמ\"ט (ע' תו). אבן עזרא תולדות כז, יט."],["4611","45","<b>תרי\"ג ארחי' דגלגלתא</b>: ראה זהר (אד\"ר) נשא קכט, א. קלו, א."],["4612","46","<b>דהיום לעשותם</b>: ואתחנן ז, יא. ראה עירובין כב, א."],["4613","47","<b>שנהנין מזיו השכינה</b>: ראה ברכות יז, א."],["4614","48","<b>טלא דנטיף מעתיקא</b>: ראה זהר בשלח סא, ב. סב, ב. (אדרא זוטא) האזינו רפח, א."],["4615","49","<b>כי טל אורו' טלך</b>: ישעי' כו, יט."],["4616","50","<b>קול קורא במדבר</b>: ישעי' מ, ג."],["4617","51","<b>הקב\"ה יושב ושונה כנגדו</b>: תדבא\"ר רפי\"ח. ילקוט שמעוני איכה רמז תתרלד."],["4618","52","<b>שומר פיו</b>: משלי כא, כג."]]],[2100990263,"השלום כנ\"ל וע\"כ בדברו דברי' בטילי' ממשיך בסט\"א אותו השלום וכמ\"ש והתברך<sup data-n=\"4619\">53</sup> בלבבו לאמר שלום יהי' לי למען ספות הרוה כו' אבל שומר פיו ולשונו יאיר בקולו קול התורה מבחי' אור הכתר בחכמה כו' ולכך ת\"ת<sup data-n=\"4620\">54</sup> כנגד כולם לפי שהדיבור בד\"ת קורא<sup data-n=\"4621\">55</sup> את הדורות מראש כו' עד\"מ אדם שקורא לחבירו שיבא מן ההעלם לגילוי כו' ואח\"כ במצות הוא הגילוי וד\"ל.\n<b>וזהו</b> וידעת היום והשבות אל לבבך כו', פי' ע\"י בכל לבבך דאתכפיא סט\"א דיצה\"ר דוקא בא מזה סיבת חיבור ב' הפכי' הנ\"ל מהארת אור הכתר דאל עליון כנ\"ל והטעם הוא לפי שברורי' דרפ\"ח ניצוצי' דתוהו שרשם בבחי' התוהו שלפני התיקון נק' חושך וכמ\"ש מגלה<sup data-n=\"4622\">56</sup> עמוקו' מני חושך עמוקו' הן י\"ס דתוהו כו' וכמ\"ש והארץ<sup data-n=\"4623\">57</sup> היתה תוהו וחושך כו' כידוע וכשנפלו בעולם הבריא' בעה\"ד טו\"ר נק' חושך גמור וכמ\"ש ולחושך<sup data-n=\"4624\">58</sup> קרא לילה וזהו וכד<sup data-n=\"4625\">59</sup> אתכפיא סט\"א אסתלק יקרא דקדב\"ה פי' אסתלק ממש להיו' כי עולי' רפ\"ח ניצוצי' לשרשם בהתהפכו' חשוכא לנהורא ומרירו למיתקא כידוע וכתיב יתרון<sup data-n=\"4626\">60</sup> האור מתוך החושך דוקא כי כאשר בחי' ההעלם מתגלה ודאי יש יתרון אור הרבה מאור הקדום הנמדד במדה מן ההעלם וזהו דאסתלק יקר\"א כו' לפי שהתוהו גבוה הרבה מבחי' התיקון וידוע דז\"א שנק' קדב\"ה הוא בחי' התיקון וע\"י ברורי' דתוהו אסתלק יקרא דקדב\"ה וד\"ל.\n<b>והמשל</b> לזה הוא ידוע שהמלך גם בהיותו טרוד מאד מאד ברוממו' גדולת מלכותו ולא יפנה מטרדתו ורוממתו גם לכל דבר גדול דהרי כולא קמי' כאין כו' אך כשמראין לפניו דבר חידוש כצפור המדברת כו' יפנה לזה כו' כך בחי' הברורי' דרפ\"ח להיותו דבר חדש מאד כמו הציפור שהוא בחי' חי יהי' בחי' מדבר כך בחי' התוהו שנק' חיה ובהמה בנפילתם כידוע יתהפך לבחי' מדבר אדם בבחי' התיקון דמב\"ן נתהפך למ\"ה כו' ועי\"ז החידוש הוא נפנה מן ההעלם דכתר הנק' אל עליון להאיר למטה בחו\"ב וזו\"נ כנ\"ל לעשו' השלום וזהו וידעת היום לחבר יום ולילה וכן ב' הפכי' דאוי\"ר ובפרט בכל לבבך &lt;שכב&gt;\nדאתכפיא סט\"א אז יתחברו ג\"כ הוי' עם אלקי' והיו לאחדי' מ\"ה וב\"ן דזו\"נ כי יאיר אור הכתר דאל עליון עי\"ז מטעם הנ\"ל וד\"ל (ועי\"ל שהוי' הוא התפשטו' ואלקי' הוא הצמצום דהעלם ויתרון האור אשר בא מתוך החושך מחבר להיו' הוי' הוא האלקי' שלפני שם הוי' כו' והיינו בשמים ממעל שהוא בחי' ההעלם ועל הארץ מתחת שהוא בחי' ההתפשטו' שניהם יהיו בהשווא' א' בבחי' אין עוד וד\"ל).",[["4619","53","<b>והתברך בלבבו</b>: נצבים כט, יח."],["4620","54","<b>ת\"ת כנגד כולם</b>: פאה בתחלתו."],["4621","55","<b>קורא את הדורות מראש</b>: ישעי' מא, ד."],["4622","56","<b>מגלה עמוקות מני חושך</b>: איוב יב, כב."],["4623","57","<b>והארץ היתה תהו וחושך</b>: בראשית א, ב."],["4624","58","<b>ולחושך קרא לילה</b>: שם ה."],["4625","59","<b>כד אתכפיא סט\"א אסתלק יקרא דקב\"ה</b>: בתניא פכ\"ז (לד, א) ובלקו\"ת ר\"פ פקודי מציין לזהר ח\"ב קכח, ב. (ובלקו\"ת שם מציין גם לזהר שם סז, ב. וראה גם שם קפד, א). וראה גם תו\"א ויקהל פט, ד. לקו\"ת חוקת סה, ג."],["4626","60","<b>יתרון האור מתוך החושך</b>: ראה קהלת ב, יג."]]],[2100990264,"<h3>כי תשמע בקול</h3>\n<b>בעזר\"ה שבת פ' ראה</b>\n<b>כי</b><sup data-n=\"4627\">1</sup> תשמע בקול ה' אלקיך<sup data-n=\"4628\">2</sup>, לשמור את כל מצוותיו אשר אנכי מצוך היום, לעשות הישר בעיני ה' אלקיך. הנה מה שיש לדקדק בפסוק זה רבות הנה הא' מה שכתוב כי תשמע בקול ולא אמר כי תשמע לקול וכמ\"ש במקומו' רבים ואם<sup data-n=\"4629\">3</sup> שמוע תשמעו לקול ה' כו', והב' מ\"ש בקול ה' אלקיך ולא אמר בקול ה' סתם והג' מה סמך ענין שמירת המצות בענין שמיעת קול ה' הל\"ל וכי תשמע אל מצות ה' וכמ\"ש והי'<sup data-n=\"4630\">4</sup> אם שמוע תשמעו אל מצותי כו' ומאחר שמפרש שמירת המצות בענין בפ\"ע משמע שזה תלוי בזה והם ב' דברים ולכאורה הוא ענין א' דהשמירה במצות היינו לשמוע בקול ה' שציוה לעשו' המצות והד' מ\"ש לעשות הישר בעיני ה' וכי יתכן לומר ענין יושר דבר בעיני ה' כמו בעיני אדם אחר שהוא למעלה מן ההשתלשלו' וכולא<sup data-n=\"4631\">5</sup> קמי' כלא כו' וא\"כ איך יתכן לומר כלפי מעלה שזה הדבר ישר בעיניו וזה אינו ישר כו' וגם יש להבין מהו אשר ישר בעיני ה' ומהו שאינו ישר כו'. אך הנה יש להקדים ענין א' דלפעמי' נא' עין<sup data-n=\"4632\">6</sup> ה' אל יריאיו דמשמע עין א' ולפעמי' נא' עיני<sup data-n=\"4633\">7</sup> ה' אל צדיקי' דמשמע ב' עינים וגם כאן אמר לעשות הישר בעיני ה' כו'.\nא. <b>והענין</b> הוא דהנה ארז\"ל כל<sup data-n=\"4634\">8</sup> מי שיש בו תורה ואין בו יראת שמים דומה לגזבר שמסרו לו מפתחות הפנימיו' ולא מסרו לו מפתחו' החיצוניו' כו' הרי מפתחו' החיצוניו' הוא בחי' יראה ומפתחו' הפנימי' הוא בחי' תורה וביאור ענין זה הנה אמרו בזוהר דרמ\"ח<sup data-n=\"4635\">9</sup> מ\"ע נק' רמ\"ח איברי' דמלכא כי כמו באיברי האדם הנה האברים הם כחות מתפשטי' ונמשכין כאו\"א כח המשכה מיוחדת כו' כך המצות המה כחות המשכות מאלקות דהיינו רמ\"ח איברי' דמלכא כו' ומהם נמשך ענין הארת זיו השכינה בג\"ע העליון ובג\"ע התחתון מה שצדיקים<sup data-n=\"4636\">10</sup> יושבין ונהנין מזיו כו' והוא קבלת שכר שלהם ממעשה המצות שעשו בעוה\"ז לפי שע\"י המצות נמשך",[["4627","1","<b>כי תשמע בקול ה' אלקיך</b>: הנחת כ\"ק אדה\"א. נעתק מגוכתי\"ק 1025 (פז, ב).\nנוסח אחר (הנחת המהרי\"ל) נמצא בכת\"י — ונאמר ע\"י כ\"ק אדמו\"ר הצ\"צ ביום ש\"ק פ' כי תצא תקפ\"ט. נדפס בתוס' הגהות בלקו\"ת ראה כב, ד. (וראה רשימת הכתבי-יד בלקו\"ת שם). ובלי הגהות בתו\"א לעמברג תרי\"א כא, א. ועם הגהות באוה\"ת דברים ע' ב'שכט (משנת תקפ\"ט).\nוראה בארוכה ד\"ה זה לאדמו\"ר האמצעי במאמרי אדה\"א ראה ע' שצו ואילך. (הובא בסה\"מ תרל\"ו ח\"ב ע' שז. — כי תשמע בקול הארוך דאאזמו\"ר ז\"ל)."],["4628","2","<b>כי תשמע בקול ה' אלקיך</b>: פ' ראה יג, יט."],["4629","3","<b>ואם שמוע תשמעו לקול ה'</b>: בשלח טו, כו."],["4630","4","<b>והי' אם שמוע תשמעו אל מצותי</b>: עקב יא, יג."],["4631","5","<b>וכולא קמי' כלא</b>: ראה זהר בהקדמה יא, ב."],["4632","6","<b>עין ה' אל יריאיו</b>: תהלים לג, יח."],["4633","7","<b>עיני ה' אל צדיקי'</b>: שם לד, טז."],["4634","8","<b>כל מי שיש בו תורה</b>: ראה שבת לא סע\"א ואילך — בגמ' כל אדם. ובר\"ח ת\"ח. אבל בכ\"מ בדא\"ח מובא כבפנים ומהם בלקו\"ת, אוה\"ת. וראה הערה במאמרי אדה\"א שם."],["4635","9","<b>דרמ\"ח מ\"ע נק' רמ\"ח אברי' דמלכא</b>: בתניא פכ\"ג: ובתיקוני'. ראה תקו\"ז ת\"ל (עד, ס\"א). ובאגה\"ת רפ\"א (דף צ, ב): בזהר. וראה זהר וישלח קע, ב. בסה\"מ תקס\"ה ע' תתעו: בר\"מ. ראה רע\"מ משפטים קיח, א."],["4636","10","<b>שצדיקים יושבין ונהנין מזיו</b>: ברכות יז, א."]]],[2100990265,"הארת הזיו בג\"ע כמאמר שכר<sup data-n=\"4637\">11</sup> מצוה מצוה פי' המצוה עצמה היא נעשה שכר ליהנו' מזיו &lt;שכג&gt;\nהשכינה על ידה כי שרש המצות נק' אבר דמלכא שממנו נמשך כח המשכה האלקי' בג\"ע וכמ\"ש ויניחהו<sup data-n=\"4638\">12</sup> בג\"ע לעבדה זו רמ\"ח מ\"ע ולשמרה זו שס\"ה ל\"ת כידוע הרי שכל תיקון ריבוי האור בג\"ע הוא ע\"י מ\"ע ואמנם כדי שיהא העונג מהזיו מורגש באופן הגבלת נשמו' המקבלי' בג\"ע בהכרח שיבא אור המשכה זו מאור א\"ס שהוא בלתי מוגבל ע\"י כמה צמצומי' עד שיהא באופן גילוי השגת הנשמ' להיו' נהנין מזיו כו' וד\"ל.\nב. <b>והנה</b> אמרו ז\"ל התקן<sup data-n=\"4639\">13</sup> עצמך בפרוזדור כדי שתיכנס לטרקלין פי' כי בעוה\"ב שם הנשמו' בלתי גופים ויכולי' לקבל הזיו האלקי ע\"י המצות שעשו בעוה\"ז כנ\"ל אך בעוה\"ז הנשמו' מלובשים בגופים חומריים וא\"א להם לקבל בעצמם האור וזיו שנעשה ונמשך ע\"י מעשה המצוה רק בדרך הכנה בלבד כמו שהאדם מכין א\"ע בפרוזדור ליכנס לטרקלין שמקשט א\"ע בלבושים נאים בכדי שיוכל לעמוד בטרקלין כו' והכנה זאת בנפש האדם הוא ע\"י שתתבונן בבחי' ממלא כ\"ע איך שהוא ית' מחי' כל העולמו' מאין ליש וכמ\"ש ואתה<sup data-n=\"4640\">14</sup> מחי' את כולם וכן אתה<sup data-n=\"4641\">15</sup> עשית את השמים ושמי השמים כו' וכמו יוצר<sup data-n=\"4642\">16</sup> משרתים ואשר משרתיו כולם עומדי' ואו' ביראה כו' והאופנים וחיו' ברעש גדול כו' וכיוצא באלה שמזה נופל בחי' היראה על האדם וזה נק' מפתחות החיצוניו' עד\"מ המפתח לפתוח פתח ההיכל החיצוני כך כל העולמו' אינם מקבלי' רק מבחי' חיצוניו' ואחוריי' דהיינו רק ע\"י בחי' צמצום האור האלקי כידוע דשם<sup data-n=\"4643\">17</sup> אלקים הוא המצמצם כו' וגם הביטול וההשתחוואה של כל העולמו' ע\"י היראה ופחד כנ\"ל אין זה אלא כמו בחי' מפתחו' להיכלו' החיצוניו' ולא יש בזה עדיין שום כניסה לבחי' הפנימי'.\nג. <b>דהיינו</b> לבחי' אור האלקי עצמו שנק' בשם אלקי ממש וכל העולמו' אינם מקבלים בחי' אלקי ממש אלא רק הארה וזיו בעלמא ונק' בשם אלקות כו' ולא עצמו' אלקי כו' מפני שכל ביטול שלהם נמשך רק מבחי' ממלא כ\"ע כמו באמרם הללו<sup data-n=\"4644\">18</sup> ה' מן השמים כו' וכיוצא בזה באמרינו ברוך<sup data-n=\"4645\">19</sup> שאמר והי' העולם שכל זה מסיבת השתלשלו' אלקו' בעולמו' ולא מצד עצמו' אור האלקי שנא' בו אתה<sup data-n=\"4646\">20</sup> הוא ה' לבדך לבדך ממש בלי שום שינוי כלל מקודם<sup data-n=\"4647\">21</sup> שנברא העולם לאחר",[["4637","11","<b>שכר מצוה מצוה</b>: אבות פ\"ד, מ\"ב. תניא פל\"ט."],["4638","12","<b>ויניחהו בג\"ע לעבדה</b>: בראשית ב, טו. וראה זהר בראשית כז, א. תרומה קסה, ב. וראה ביאוה\"ז חיי שרה קכט, ד. שער האמונה פל\"ה. לקו\"ש ח\"כ ע' 262 הערה 8."],["4639","13","<b>התקן עצמך בפרוזדור</b>: אבות פ\"ד מט\"ז."],["4640","14","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו."],["4641","15","<b>אתה עשית את השמים ושמי השמים</b>: שם."],["4642","16","<b>יוצר משרתים ואשר משרתיו</b>: ע\"פ ברכת יוצר."],["4643","17","<b>דשם אלקים הוא המצמצם</b>: נסמן לעיל ע' תלט."],["4644","18","<b>הללו ה' מן השמים</b>: תהלים קמח, א."],["4645","19","<b>ברוך שאמר והי' העולם</b>: ברכת ברוך שאמר."],["4646","20","<b>אתה הוא ה' לבדך</b>: נחמי' ט, ו."],["4647","21","<b>מקודם שנברא העולם</b>: ראה תפלת שחר. של\"ה ג, ב."]]],[2100990266,"שנברא העולם כי אין בחי' ממלא כ\"ע תופס מקום כלל עד שלא יש שינוי בזה כלל כמ\"ש אני<sup data-n=\"4648\">22</sup> הוי' לא שניתי כו' וכידוע ואפי' הארת הזיו בג\"ע כלא חשיב לגבי עצמו' אלקי שהרי אמרו דביו\"ד<sup data-n=\"4649\">23</sup> נברא העוה\"ב ובה\"א נברא העוה\"ז שנא' כי<sup data-n=\"4650\">24</sup> בי\"ה ה' צור עולמי' באותיו' יו\"ד ה\"א והרי עד\"מ בנפש האדם אותיו' מחשבתו המה בטילים בתכלית לגבי עצמותו ובפרט אותיו' יו\"ד וה\"א בלבד שחולפים ועוברים במחשבה כרגע בלי תפיסת מקום כלל וכלל כך גם העוה\"ב שנברא ביו\"ד דבודאי הוא בטל ונכלל לגבי אור עצמו' בחי' מחשבתו ית' וכמ\"ש וחשב<sup data-n=\"4651\">25</sup> מחשבות כו' וכן כי<sup data-n=\"4652\">26</sup> לא מחשבותי כו' מפני שנא' מה מאד<sup data-n=\"4653\">27</sup> עמקו מחשבותיך כו' וכך כל העולמו' דממלא כ\"ע כלא ממש חשיבי לגבי בחי' העצמו' וכאשר &lt;שכד&gt;\nישים האדם אל לבו בחי' עצמו' אלקו' שלמעלה מן ההשתלשלו' ויתפעל באהבה ודביקו' לדבקה נפשו בבחי' עצמו' אור אלקי וכמ\"ש ואהבת<sup data-n=\"4654\">28</sup> ה' אלקיך שיהי' הוי' דבחי' סובב כ\"ע אלקיך ממש דהיינו בקרבו ממש כמ\"ש על<sup data-n=\"4655\">29</sup> כי אין אלקי בקרבי מצאוני הרעו' האלה כו' אזי נמסרו לו גם מפתחו' הפנימיו'.\nד. <b>והוא</b> בחי' תורה דהנה בתורה אמר כאן כי תשמע בקול ה' כו' שהוא קול דתורה לפי שהקורא<sup data-n=\"4656\">30</sup> בתורה הקדב\"ה יושב וקורא כנגדו הרי נק' קול ה' ועד\"מ קול הבל הלב שבאדם שהוא כח המשכה שיוצא מהבל הלב בדיבור בפה דהיינו המשכה מרוחניו' דהבל הלב לגשמיו' קול הדיבור והקול הוא המחבר רוחניו' הלב עם גשמיות הדיבור כך למעלה ע\"י קול דתורה מקשר האדם ומחבר בחי' רוחניו' דאור האלקי עצמו לבא בבחי' גילוי הדיבור בבחי' ממלא כ\"ע וזהו לפי שהקדב\"ה שהוא בחי' סובב כ\"ע יושב וקורא ג\"כ בקולו הוא קול הוי' שנמשך מהבל לב העליון דבחי' עצמו' כו' וזהו שאמרו ז\"ל דכל<sup data-n=\"4657\">31</sup> הקורא בתורה קורא בשמותיו של הקדב\"ה עד\"מ כאדם שקורא לחבירו בשמו שהוא נפנה כולו ע\"י קריאת שמו כך כתיב קורא<sup data-n=\"4658\">32</sup> הדורו' מראש שנגלה מבחי' ההעלם וכמ\"ש קרוב<sup data-n=\"4659\">33</sup> ה' לכל אשר יקראוהו באמת ואין<sup data-n=\"4660\">34</sup> אמת אלא תורה שבה יקראוהו לבחי' עצמו' אלקו' שיבא לידי גילוי מן ההעלם מטעם שדבר ה' זו הלכה מפני שקול ה' היא התורה כמ\"ש קול<sup data-n=\"4661\">35</sup> ה'",[["4648","22","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["4649","23","<b>דביו\"ד נברא העוה\"ב</b>: מנחות כט, ב."],["4650","24","<b>כי בי\"ה ה' צור עולמי'</b>: ישעי' כו, ד."],["4651","25","<b>וחשב מחשבות</b>: שמואל-ב יד, יד."],["4652","26","<b>כי לא מחשבותי</b>: ישעי' נה, ח."],["4653","27","<b>מאד עמקו מחשבותיך</b>: תהלים צב, ו."],["4654","28","<b>ואהבת את ה' אלקיך</b>: ואתחנן ו, ה."],["4655","29","<b>על כי אין אלקי בקרבי</b>: דברים לא, יז."],["4656","30","<b>הקב\"ה יושב וקורא כנגדו</b>: ראה תנא דבי אליהו רבא רפי\"ח. ילקוט שמעוני איכה ב, יט (רמז תתרלד). וראה בהנסמן במאמרי אדמו\"ר האמצעי ראה ע' שפז."],["4657","31","<b>דכל הקורא בתורה קורא בשמותיו של הקב\"ה</b>: ראה זהר יתרו פז, א. פתיחת הרמב\"ן עה\"ת."],["4658","32","<b>קורא הדורות מראש</b>: ישעי' מא, ד. וראה ביאוה\"ז להצ\"צ ח\"א ע' רנט ואילך."],["4659","33","<b>קרוב ה' לכל אשר יקראוהו באמת</b>: תהלים קמה, יח."],["4660","34","<b>ואין אמת אלא תורה</b>: ירושלמי ר\"ה פג, ה\"ח. איכה רבא פתיחתא ב. ילקוט שמעוני דניאל (ח, יב) רמז תתרסו. תקו\"ז תכ\"א (נ, א). וראה ברכות ה, ב."],["4661","35","<b>קול ה' יחיל מדבר</b>: תהלים כט, ח."]]],[2100990267,"יחיל מדבר כו' וזהו שכל הקורא בתורה קורא בשמותיו כמו בכל מסכת<sup data-n=\"4662\">36</sup> שלומד וקורא יש בה קריאת שם משמו' ה' בפרט במס' זו יש שם זה שנפנה לקוראו בקריא' שקוראו במסכת זו ובמס' אחרת הוא קורא שם אחר כו' והכל קריאת והמשכת אור א\"ס ב\"ה ממש ממהותו ועצמותו וע\"כ אמרו ז\"ל דהתורה הוא בחי' מפתחו' הפנימיו' עד\"מ המפתח לפתוח ההיכל הפנימיי' ביותר כך הקול דתורה הוא מפתח לפתוח בחי' אורות הפנימיו' שבאור האלקי עצמו כי הקדב\"ה יושב וקורא כנגדו כו' ונמשך עי\"ז ומתחבר מבחי' אור א\"ס ממש בעולמו' וזהו לפי ששרש התורה הוא בחי' רצון העליון וע\"י קול דתורה נמשך ובא בחי' רצון העליון בגילוי וזהו קרוב ה' כו' לכל אשר יקראוהו באמת מפני שקדם לומר טוב ה' לכל כו' עד פותח את ידך ומשביע לכל חי רצון פי' רצון העליון וד\"ל וזהו שאמרו כל מי שיש בו תורה ואין בו יראה דומה לגזבר שמסרו לו מפתחו' החיצוניו' דהיינו בחי' ממלא כ\"ע ולא מסרו לו מפתחו' הפנימיו' דהיינו בחי' סובב כ\"ע לפי שע\"י קול דתורה דוקא נגלה ונמשך בחי' עצמו' אור א\"ס אך כל האומר אין לי אלא תורה אפי' תורה אין לו וע\"כ צריך להיו' הכנה בנפש האדם לזה מקודם בתפלה והיינו בסדר הנסדר בתפלה בב\"ש ויוצר אור עד ש\"ע.\nה. <b>דהנה</b> במגלת אסתר כתוב שיש חצר החיצונה וחצר הפנימי' והמלך<sup data-n=\"4663\">37</sup> יושב על כסא מלכותו בבית המלכות כו'. ענין חצר החיצונה הוא עד ב\"ש ומב\"ש עד ישתבח וחצר<sup data-n=\"4664\">*37</sup> הפנימי הוא ביוצר אור וק\"ש עד ש\"ע והמלך יושב על כסא מלכותו בבית המלכו' הוא בתפלת י\"ח ומשם נא' ויושט<sup data-n=\"4665\">38</sup> &lt;שכה&gt;\nלה המלך שרביט הזהב כו'.\n<b>וביאור</b> הדברים כי עד<sup data-n=\"4666\">39</sup> ב\"ש האדם צריך להשפיל א\"ע בבחי' חיצוניות מדבקותו בהגשמת עניני עוה\"ז וכן למעלה הוא עליי' המלכו' מע' שרים דעשי' וכמ\"ש מי<sup data-n=\"4667\">40</sup> זאת עולה מן המדבר כו' והוא הנק' חצר החיצונה וכמ\"כ מב\"ש עד ישתבח הגם שהמלאכי' עולין ג\"כ בשיר וזמרה כל זה נחשב מבחי' חיצוניו' אבל חצר הפנימיו' הוא מברכת יוצר עד ק\"ש ועד בכלל לפי שביחוד עליון דק\"ש צריך האדם לדבקה נפשו האלקי' למסור<sup data-n=\"4668\">41</sup> נפשו באחד באמרו ואהבת ה' כו' בכל מאדך עד שבהגיע האדם לסמיכת גאולה לתפלה ה\"ז כמו שיוצא מחצר הפנימי' ליכנס",[["4662","36","<b>מסכת. . קריאת שם</b>: ראה זהר פינחס רטז, א."],["4663","37","<b>והמלך יושב על כסא מלכותו בבית המלכות</b>: אסתר ה, א."],["4664","*37","<b>וחצר הפנימי. . וק\"ש. . בתפלת י\"ח</b>: ראה אוה\"ת תצוה ע' א'תקסד — ושם מציין שכ\"ה במק\"מ פ' ויחי דרכ\"ח ע\"ב שזהו ענין ויושט המלך את שרביט הזהב הוא ענין סמיכת גאולה לתפלה. וראה גם תו\"א צד, ג."],["4665","38","<b>ויושט לה המלך שרביט הזהב</b>: אסתר ה, ב — ויושט המלך."],["4666","39","<b>עד ב\"ש האדם צריך להשפיל א\"ע</b>: ראה סה\"מ תקס\"ז ע' רנה ואילך. תק\"ע ע' נא. נביאים ע' יט ואילך. ענינים ע' תמח ואילך. דרך חיים שער התפלה פל\"ח מו, ד פס\"ו. אוה\"ת ואתחנן ע' קסט."],["4667","40","<b>מי זאת עולה מן המדבר</b>: שה\"ש ג, ו. ח, ה."],["4668","41","<b>למסור נפשו באחד</b>: באוה\"ת בהר כרך ד מציין לזהר. ראה (זהר) רעיא מהימנא משפטים קיט, א־ צו לג, א. פע\"ח שם פי\"ב."]]],[2100990268,"להיכל המלך עצמו שיושב שם על כסא מלכותו כו' כי למעלה היינו בחי' העלא' מ\"ן דנשמו' דבריא' בהיכל הרצון שבאמת ויציב להיו' נכללי' באצי' ובהגיע הנשמה לזה אזי כתיב ויושט לה המלך שרביט הזהב הן בחי' ה\"ג כי רשפי אש האהבה שהי' בק\"ש לנפש האלקי' מלמטה למעלה אח\"כ בשעת כניסתה ליכנס לבחי' האצי' חוזר אור זה אליה בבחי' ההמשכה מלמעלה למטה ג\"כ מבחי' גבורו' רשפי אש האהבה הנק' שלהובא<sup data-n=\"4669\">42</sup> דרחימותא כי רוח<sup data-n=\"4670\">43</sup> אייתי רוח כו' והושטת שרביט הזהב מגיע לה מהיכל המלך פנימה שהוא יושב בבחי' האצי' כדי שתוכל עי\"ז ליקרב וליכנס בהיכל המלך פנימה וכמ\"ש במ\"א בענין זה באריכות וד\"ל.\n<b>וזהו</b> כי תשמע בקול ה' אלקיך לשמור כל מצוותיו אשר אנכי מצוך היום. דהנה אנו רואים שהתפעלו' אוי\"ר שבתפלה חולפת ועוברת מיד אחר התפלה ואין לה קיום כלל משא\"כ עסק התורה לשמה כל היום יש לה קיום נצחי ואינו מתבטל לעולם וכמ\"ש ודברת<sup data-n=\"4671\">44</sup> בם בשבתך בביתך וגם ובלכתך בדרך בשכבך ובקומך אבל לתפלה צריך שעת הכושר דוקא ולא כל העיתים שוות כו' מפני שהתורה נק' אמת וכמ\"ש קרוב ה' כו' לכל אשר יקראוהו באמת ואין אמת אלא תורה וכתיב שפת<sup data-n=\"4672\">45</sup> אמת תכון לעד שאין לה הפסק וביטול כלל וע\"כ נמשכת כל היום ואין לה זמן קבוע כמו התפלה כי שרש התורה למעלה מן הזמן וע\"כ אמר והיו<sup data-n=\"4673\">46</sup> הדברים האלה אשר אנכי מצוך היום כל היום במשמע וגם בזמן היותר אחרון היום נקרא כי הוא למעלה מן הזמן ע\"כ כל הזמנים כיום אחד ועל כולם או' היום כו'.\nו. <b>ועוד</b> יש יתרון מעלה בתורה מבתפלה כי בתורה אמר קרוב ה' לכל אשר יקראוהו הכל במשמע כל מי שיקרא בתורה יהי' מי שיהי' וכמ\"ש קרוב ה' לכל קוראיו לכל אשר יקראוהו כפל ב\"פ לכל כי הנה אנו רואים שלא כהעוה\"ב העוה\"ז דהעוה\"ב אינו אלא למי שראוי לה דוקא וגם זאת אחר המירוק ביסורי<sup data-n=\"4674\">47</sup> גיהנם ונהר<sup data-n=\"4675\">48</sup> דינור כידוע לפי שהעוה\"ב הוא בחי' זיו והארה האלקית שבאה בהשתלשלו' המדרגו' מעילה לעילה עד שכאו\"א משיג לפום שיעורא דילי' וע\"כ אין האור מאיר אלא לפי הכלי הראוי לזה וכמ\"ש מי<sup data-n=\"4676\">49</sup> יעלה בהר ה' ומי יקום במקום קדשו נקי כפים ובר לבב כו' אבל העוה\"ז הוא בהיפוך זה שיוכל לקבל אור האלקי גם ממדרגה היותר עליונ' &lt;שכו&gt;\nבהשתלשלו' גם מי שאינו ראוי לה כלל וכלל וכמ\"ש",[["4669","42","<b>שלהובא דרחימותא</b>: ראה זח\"ג פד, א. וראה גם מאמרי אדמו\"ר האמצעי בראשית ע' תקג. דברים ח\"א ע' קעח."],["4670","43","<b>רוח אייתי רוח</b>: ראה זהר תרומה קסב, רע\"ב. וירא צ, רע\"ב. סידור ערב שבת קסג, ד. ועוד."],["4671","44","<b>ודברת בם בשבתך בביתך</b>: ואתחנן ו, ז."],["4672","45","<b>שפת אמת תכון לעד</b>: משלי יב, יט."],["4673","46","<b>והיו הדברים האלה</b>: ואתחנן ו, ו."],["4674","47","<b>ביסורי גיהנם ונהר דינור כידוע</b>: ראה לקו\"ת (כאן) ראה כג, ג — ע\"י יסורים של גיהנם ונהר דינור כו' וכמארז\"ל [ברכות ה, סע\"א] שלש מתנות טובות נתן הקב\"ה לישראל וכולם לא נתנו אלא ע\"י יסורים."],["4675","48","<b>ונהר דינור</b>: דניאל ז, י."],["4676","49","<b>מי יעלה בהר ה'</b>: תהלים כד, ג."]]],[2100990269,"אשר<sup data-n=\"4677\">50</sup> אנכי מצוך היום וידוע דפי' אנכי<sup data-n=\"4678\">51</sup> הוא מי שאנכי בחי' סובב כ\"ע כנ\"ל ובקריאתו בתורה בקול קורא הוא ממשיך גילוי בחי' סובב כ\"ע ממהותו ועצמותו שהוא תמידי ולמעלה מן ההשתלשלו' ע\"כ נא' בה קרוב ה' לכל קוראיו לכל אשר יקראוהו יהי' מי שיהי' גם למי שאינו ראוי כראוי כו' וע\"כ אמר אשר אנכי מצוך היום היום דוקא בעוה\"ז ולא בעוה\"ב מטעם הנ\"ל וד\"ל וזהו ג\"כ הטעם שבתורה נא' שפת אמת תכון לעד משא\"כ בתפלה שהיא בבחי' זמן ע\"כ חולפת ועוברת כו' וזהו כי תשמע בקול ה' אלקיך, פי' בקול במה שיש גנוז ונעלם בקול והוא קול דתורה שבו גנוז אור הוי' אלקיך בחי' סובב דממלא כ\"ע דהיינו מבחי' עצמות אור א\"ס שלמעלה מן הזמן שהוא ענין מפתחות הפנימיו' הנ\"ל וע\"כ לא אמר לקול ה' אלא בקול ה' אשר אנכי מצוך היום כנ\"ל וד\"ל.\n<b>אך</b> הנה אמרו ז\"ל דהאומר<sup data-n=\"4679\">52</sup> אין לי אלא תורה אפי' תורה אין לו, ולכאורה בקול דתורה הרי יכול להמשיך מבחי' סובב כ\"ע שכולל גם בחי' היראה שהיא רק מפתחות החיצוניות ולמה אפי' תורה אין לו אבל הענין הוא משום דבתורה עצמה יש ב' מדרגו' הא' סור מרע בשס\"ה ל\"ת והכלל הוא לבער הרע מכל וכל וכמ\"ש ובערת<sup data-n=\"4680\">53</sup> הרע מקרבך ונכלל בזה כל השס\"ה ל\"ת וכמשל<sup data-n=\"4681\">54</sup> כיבוד הבית כדי שיכנס המלך להיכל נקי מכל דבר טינוף ואם לא יהא נקי לא יכנס בו כמבואר בספרי היראה כי הוא ית' טהור<sup data-n=\"4682\">55</sup> עינים מראות ברע וזהו ולא<sup data-n=\"4683\">56</sup> תתורו אחרי לבבכם ואחרי עיניכם אשר אתם זונים אחריהם הרי שקרא בשם זונה לכל הדבק אחרי הרע וכמו שהזונה<sup data-n=\"4684\">57</sup> אסורה לבעלה כך הניצוץ נאסר מלהיו' בה גילוי אור אלקי ואחרי תטהר מכל רע אזי יוכל להיו' בה גילוי אלקו' במ\"ע וע\"כ אמרו דהאומר אין לי אלא תורה דהיינו בהמשכת גילוי אלקו' בקול קורא אפי' תורה אין לו דהאיך ישכון אור אלקי בהיכל וכלי מטונף קודם הביעור מן הרע כנ\"ל.\n<b>ובזה</b> יובן מה שמכריז ר'<sup data-n=\"4685\">58</sup> אלכסנדרי ווי למאן דלית לי' דירתא ותרעא לדירתא עביד שהוא על ת\"ח שאין בו יראת חטא שאז נק' תורתו רק תרעא לדירתא פחותה ממדרג' היראה שנק' מפתחו' החיצוניו' בהיכל ודירה עכ\"פ אבל תורה בלא יראת חטא אינו אלא כמו עד\"מ השער לבית בלבד שאינו בית דירה כלל כמארז\"ל נתאוו'<sup data-n=\"4686\">59</sup> הקדב\"ה לו דירה בתחתוני' וכאשר אינו סור מרע בתכלית אינו בית דירה",[["4677","50","<b>אשר אנכי מצוך היום</b>: ואתחנן ו, ו."],["4678","51","<b>אנכי הוא מי שאנכי</b>: ראה תניא מהדורא קמא ספמ\"ט ע' תו. אבן עזרא תולדות כז, יט."],["4679","52","<b>דהאומר אין לי אלא תורה</b>: יבמות קט, ב."],["4680","53","<b>ובערת הרע מקרבך</b>: דברים יג, ו. יז, ז."],["4681","54","<b>וכמשל כיבוד הבית</b>: ראה ג\"כ לקו\"ת האזינו עז, א."],["4682","55","<b>טהור עינים מראות ברע</b>: ראה חבקוק א, יג. ובמנחת שי שם."],["4683","56","<b>ולא תתורו אחרי לבבכם</b>: שלח טו, לט."],["4684","57","<b>שהזונה אסורה לבעלה</b>: ראה נשא ה, יב ואילך."],["4685","58","<b>ר' אלכסנדרי ווי למאן דלית לי' דירתא</b>: ראה שבת לא, ב: ר' ינאי."],["4686","59","<b>נתאוו' הקב\"ה לו דירה בתחתוני'</b>: ראה תניא פל\"ו ובליקוט פירושים לשם."]]],[2100990270,"כלל להשרא' גילוי אלקו' כו' וד\"ל, וזהו כי תשמע בקול ה' אלקיך לשמור את כל מצוותיו דוקא ואם לאו אפי' תורה אין לו מטעם הנ\"ל.\n<b>לשמור</b> את כל מצוותיו. פי' את כל מצוותיו כמו הולך<sup data-n=\"4687\">60</sup> את חכמים יחכם, דלשון את משמעו ענין טפל ובטל ולכאורה אינו מובן מהו ענין אשר הוא בחי' טפל ובטל שיש במצות שאו' ע\"ז את כל מצוותיו כו'. אך הענין הוא דיש במצות ב' מדרגות הא' שנק' בחי' איברים דמלכא שהענין הוא בחי' המשכות אלקות כידוע דרמ\"ח איברי' דמלכא היינו רמ\"ח המשכו' חסד<sup data-n=\"4688\">61</sup> דרועא ימינא כו' והב' שהן בחי' כלים מקבלי' האור בלבד כמ\"ש כי נר<sup data-n=\"4689\">62</sup> מצוה כו' שהמצוה נק' נר ועד\"מ הנר שהוא מקבל הפתילה עם השמן ומחזיק &lt;שכז&gt;\nאת האור ובלעדי הכלי של הנר אין מקום לאור להאיר בשמן ופתילה כי אין אור בלא כלי כידוע כך התורה נק' אור וכתיב כי<sup data-n=\"4690\">63</sup> אתה תאיר נרי במעשה המצו' שנק' נר תאיר אור התורה בהם וכמ\"ש ותורה<sup data-n=\"4691\">64</sup> אור וכו' וזהו שנא' בצדקה<sup data-n=\"4692\">65</sup> תכונני שנעשה עי\"ז מכון לשבתו ית' וכמ\"ש מכון<sup data-n=\"4693\">66</sup> לשבתך פעלת ה' כי הנה כללו'<sup data-n=\"4694\">67</sup> כל המצות נק' בשם צדקה כמ\"ש והי'<sup data-n=\"4695\">68</sup> מעשה הצדקה שלום לפי שכללו' בחי' המעשה של המצו' נק' צדקה וכמו שסתם<sup data-n=\"4696\">69</sup> מצוה נק' צדקה כמ\"כ צדקה נק' מצוה סתם וכמ\"ש בנחמי'<sup data-n=\"4697\">70</sup> והעמדנו עלינו מצות לתת שלישית השקל וכו' וזהו והי' מעשה הצדקה שלום פי' מי שמחבר העליון בתחתון נק' שלום מפני שעושה השלום בין ב' הפכי' וכך ע\"י המצות נתחבר העליון בתחתון והיו לאחדים כי אין אור בלא כלי כנ\"ל והיינו בצדקה תכונני שע\"י כללו' המצות שנק' בשם צדקה תכונני להיו' כלי מכון ובדרך כלל נק' הצדקה בלבד ג\"כ בשם מכון אחר שנק' מצוה סתם וכמ\"ש והעמדנו עלינו מצות כו' וד\"ל.\n<b>והנה</b> על בחי' גילוי האור שמתלבש במצות בבחי' אור בכלי אין כל נברא גם מהמלאכי' היותר עליונים יכולי' להשיגו כי זה האור מבחי' עצמותו ומהותו ית' כמ\"ש אשר אנכי מצוך אנכי מי שאנכי כו' דלית<sup data-n=\"4698\">71</sup> מחשבה תפיס' בי' כלל וע\"ז אומרי' המלאכי' איה<sup data-n=\"4699\">72</sup> מקום כבודו כי נעלם הוא כו' אך לאחר שאו' קדוש ג\"פ או' מלא כה\"כ דהיינו במצות שנק' כלים ממש לגילוי אור עצמו' הא\"ס ב\"ה כנ\"ל בפי' בצדקה תכונני שנק' מכון לשבתך כו'.",[["4687","60","<b>הולך את חכמים יחכם</b>: משלי יג, כ."],["4688","61","<b>חסד דרועא ימינא</b>: תקו\"ז בהקדמה."],["4689","62","<b>כי נר מצוה</b>: משלי ו, כג."],["4690","63","<b>כי אתה תאיר נרי</b>: תהלים יח, כט."],["4691","64","<b>ותורה אור</b>: משלי שם."],["4692","65","<b>בצדקה תכונני</b>: ישעי' נד, יד."],["4693","66","<b>מכון לשבתך פעלת ה'</b>: בשלח טו, יז."],["4694","67","<b>כללות כל המצות נק' בשם צדקה</b>: ראה ואתחנן ו, כה. ובכ\"מ. מאמרי אדה\"א תצא ע' תקיח. ע' תרכז. ע' תרנט. ועוד."],["4695","68","<b>והי' מעשה הצדקה שלום</b>: ישעי' לב, יז."],["4696","69","<b>סתם מצוה נק' צדקה</b>: ראה תניא פל\"ז — בכל תלמוד ירושלמי. לקו\"ת שה\"ש מד, ג."],["4697","70","<b>בנחמי' והעמדנו עלינו מצות</b>: יו\"ד, לג."],["4698","71","<b>דלית מחשבה תפיס' בי' כלל</b>: תקו\"ז בהקדמה."],["4699","72","<b>איה מקום כבודו</b>: נוסח קדושת כתר."]]],[2100990271,"<b>ולכאורה</b> יש להבין מהיכן קיבלו המלאכי' שפע ואור לעצמותם אחר שאו' איה מקום כבודו כו' אך הנה ידוע דהמלאכי' מקבלי' שרש שפעם מבחי' זיו והארה בעלמא של שם הוי' כו' וכמ\"ש יהללו<sup data-n=\"4700\">73</sup> את שם הוי' בחי' שם בעלמא כו' אבל לעצמו' אור המאציל אין להם שום השגה ותפיס' כלל וע\"כ או' איה כו' שאינו מושג ואח\"כ חוזרי' ואו' מלא כה\"כ שאותו האור שאינו מושג להם נגלה ונראה למטה והוא בכלים של מעשה המצות שהם בחי' כלים לאור זה דוקא וכנ\"ל וזהו שארז\"ל דיפה<sup data-n=\"4701\">74</sup> שעה א' בתשובה ומע\"ט בעוה\"ז מכל חיי העוה\"ב משום דהעוה\"ב שאינו אלא בחי' זיו והארה בעלמא לא נמשך רק מבחי' חיצוניו' דמעשה המצו' כמאמר היום<sup data-n=\"4702\">75</sup> לעשותם ולמחר לקבל שכרם אבל במעשה המצות מצד עצמם שהם בחי' כלים לקבל האור וכמ\"ש כי נר מצו' כו' ע\"ז נא' עין לא ראתה כו' שהוא גבוה מהעוה\"ב הרבה מטעם הנ\"ל וד\"ל.\n<b>ובזה</b> יובן מ\"ש אל<sup data-n=\"4703\">76</sup> יתהלל המתהלל כו' כ\"א בזאת יתהלל השכל וידוע אותי כי אני ה' עושה חסד ומשפט וצדקה כי באלה חפצתי נאם ה', פי' השכל וידוע אותי היינו אותי ממש דהיינו לבחי' עצמות אור א\"ס ב\"ה דלית מחשבה תפיס' בי' כלל ובמה תלוי' ידיעה זו לידע ולהשכיל אותי ממש ע\"ז אמר כי אני ה' עושה חסד ומשפט כו' פי' החסד והמשפט והצדקה המה כלים מכלים שונים להיו' נכנס בהם גילוי אור השכלת ידיעה זו לידע ולהשכיל אותי ממש והגם דלית מחשבה תפיס' בי' ואין כלי שיוכל לקבל אור עצמותו אך אני ה' עושה חסד משפט כו' שיהיו בחי' כלים לאור זה &lt;שכח&gt;\nוהיינו כי באלה חפצתי פי' בכלים כאלה חפצתי שיהא בהם גילוי עצמותו וע\"כ המה בחי' כלים וזהו ע\"ד הנ\"ל בפי' בצדקה תכונני שהמצו' נבחרו להיו' בחי' מכון וכלי לשבתו ית' וכמ\"ש מכון<sup data-n=\"4704\">77</sup> לשבתך פעלת ה' כו' וד\"ל.\n<b>וזהו</b> לשמור את כל מצוותיו אשר אנכי מצוך היום, פי' את הוא בחי' הטפל שיש במצו' והוא מה שנמשך משכר מצוה ליהנו' מזיו השכינה בג\"ע כו' והשמירה במעשה המצו' הוא מצד המעשה עצמה כי המצוה מצד עצמה היא בחי' כלי לאור וכמ\"ש כי נר מצוה כו' וכנ\"ל וזהו לשמור את כל מצוותיו כי ע\"י כלים של המצו' משתמר האור דתורה שהקדים לומר כי תשמע בקול ה' שהוא קול דתורה כנ\"ל כי אין אור משתמר בלתי כלי וכמ\"ש כי נר מצוה ותורה אור וכנ\"ל וע\"כ אמרו דהאומר שאין לו אלא תורה אפי' תורה אין לו אלא צ\"ל תורה וגמ\"ח יחד לפי שע\"י גמ\"ח שהן כללו' המצות כנ\"ל שהצדקה נק' מצוה סתם יש כלי לשכון בו עצמו' אור א\"ס כנ\"ל וד\"ל. וזהו אשר אנכי מצוך אנכי מי שאנכי כו' ודוקא היום ולא למחר כי היום לעשותם ולמחר לקבל שכרם כידוע ומבואר למעלה דמעשה המצות בעוה\"ז גדול הרבה מהעוה\"ב מטעם שהיום יש גילוי אנכי במעשה המצוה מצד שהיא בחי' כלי",[["4700","73","<b>יהללו את שם הוי'</b>: תהלים קמח ה, יג."],["4701","74","<b>דיפה שעה א' בתשובה</b>: אבות פ\"ד, מי\"ז."],["4702","75","<b>היום לעשותם ומחר לקבל שכר</b>: ואתחנן ז, יא. עירובין כב, א."],["4703","76","<b>אל יתהלל המתהלל</b>: ראה ירמי' ט, כג — כי אם בזאת יתהלל המתהלל."],["4704","77","<b>מכון לשבתך פעלת ה'</b>: בשלח טו, יז."]]],[2100990272,"לאור ולעתיד לא יאיר אור העוה\"ב רק מצד בחי' חיצוניו' הכלים של המצו' דהיינו מה שנק' איברי' דמלכא וכמ\"ש כי בי\"ה צור עולמי' ביו\"ד נברא העוה\"ב באות א' דיו\"ד בלבד אך ע\"י המצות מרחיבי' אורו וכל זה הרוחב אין לו דמיון וערך לגבי פנימי' האור הגנוז במעשה המצו' מצד שהם בחי' כלים לקבלה כנ\"ל וע\"ז נא' עין לא ראתה כו' וזהו אשר אנכי מצוך היום היום דוקא וד\"ל.\n<b>לעשות</b> הישר בעיני ה' אלקיך. פי' שלא יהא המכוון בשביל שיהא נק' קדוש ע\"י תורה ומצות כמ\"ש קדושי'<sup data-n=\"4705\">78</sup> תהיו כו' או ע\"מ<sup data-n=\"4706\">79</sup> לקבל פרס בעוה\"ב וכיוצא אלא תהא הכונה רק לעשות עי\"ז הישר בעיני ה' כו', והענין הוא כי הנה כתיב כי<sup data-n=\"4707\">80</sup> אל דיעו' הוי' וידוע הפי' בזה שיש ב'<sup data-n=\"4708\">81</sup> דיעות הא' הנק' יחודא עילא' והיינו כמ\"ש משמים<sup data-n=\"4709\">82</sup> הביט ה' כו' וההבטה וההשגחה הזאת היא מלמעלה למטה דקמי' כולא כלא חשיבא וא\"כ למטה נק' אין באמת כי באמת כלא חשיבא ולמעלה הוא בחי' היש באמת להיותו מקור האמיתי כו' אבל דיעה הב' שהוא מלמטה למעלה הוא בהיפך שלמעלה הוא בחי' אין ולמטה הוא בחי' יש נפרד כי התהוות הבריאה הוא יש מאין כידוע אך שבחי' אין זה הוא שם המושאל בלבד כי לא נק' אין אלא מפני שהוא נעלם מהמקבלים כידוע. והנה השגחה שמלמעלה למטה הוא בשם הוי' והשגחה שמלמטה למעלה הוא בשם אלקי' שהוא המצמצם כידוע וכאשר יש יחוד בין ב' שמו' דהוי' ואלקי' וכמ\"ש אתה<sup data-n=\"4710\">83</sup> הראית לדעת כי הוי' הוא האלקי' וכיוצא אזי נעשי' ב' השגחו' הללו בהשווא' א' מלמטה למעלה כמו מלמעלה למטה וז\"ש ישר<sup data-n=\"4711\">84</sup> יחזו פנימו שמסתכלי' פב\"פ ביושר ובהשוואה א' בלתי יהיו ב' הפכי' כנ\"ל וד\"ל.\n<b>וזהו</b> עיני ה' אל צדיקי' שהוא ההשגחה מלמעלה למטה כמ\"ש משמים הביט ה' כו' וכן השקיפה ממעון קדשך מן השמים כו' ולפעמי' נא' עין ה' אל &lt;שכט&gt;\nיריאיו עין א' וכן לעתיד נאמר עין<sup data-n=\"4712\">85</sup> בעין נרא' אתה ה' דכשם<sup data-n=\"4713\">86</sup> שבא לראו' כו' והענין הוא דזהו מדבר לאחר היחוד דהוי' ואלקי' כנ\"ל דאז נא' ישר יחזו פנימו שההשגחה מלמטה למעלה כמו מלמעלה למטה ממש ע\"כ נק' עין א' בהשוואת ראי' והשגה א' כו' והיינו מ\"ש בזוהר לאתתקנא<sup data-n=\"4714\">87</sup> ברזא דאחד למהוי אחד באחד משום דאחד תתא' יהי' כדוגמת אחד עילא' והיינו ענין יחוד דהוי'<sup data-n=\"4715\">88</sup> ואלקי' שנק' יח\"ע ויח\"ת והיינו למהוי אחד באחד וד\"ל ואז דוקא יהי' זמן תח\"ה משום דכתיב אז ונגלה<sup data-n=\"4716\">89</sup> כבוד ה' כו' וכן ולא<sup data-n=\"4717\">90</sup> יכנף עוד מוריך והיו עיניך רואו' כו' והענין הוא",[["4705","78","<b>קדושי' תהיו</b>: קדושים יט, ב."],["4706","79","<b>ע\"מ לקבל פרס</b>: אבות פ\"א, מ\"ג."],["4707","80","<b>כי אל דיעות הוי'</b>: שמואל-א ב, ג."],["4708","81","<b>ב' דיעות</b>: ראה לעיל ע' תנט. וראה הנסמן באוה\"ת בהעלותך כרך ו ע' א'תשנג."],["4709","82","<b>משמים הביט ה'</b>: תהלים לג, יג."],["4710","83","<b>אתה הראת לדעת</b>: ואתחנן ד, לה."],["4711","84","<b>ישר יחזו פנימו</b>: תהלים יא, ז."],["4712","85","<b>עין בעין נרא'</b>: במדבר יד, יד."],["4713","86","<b>דכשם שבא לראו'</b>: חגיגה ב, א."],["4714","87","<b>לאתתקנא ברזא באחד</b>: זהר תרומה קלה, סע\"א."],["4715","88","<b>דהוי' ואלקי'. . יח\"ע ויח\"ת</b>: ראה לקו\"ת ראה כד, א."],["4716","89","<b>ונגלה כבוד ה'</b>: ישעי' מ, ה."],["4717","90","<b>ולא יכנף עוד מוריך</b>: ישעי' ל, כ."]]],[2100990273,"כי מאן<sup data-n=\"4718\">91</sup> דלא כרע במודים אינו קם בתח\"ה וענין הכריעה במודים ידוע שהוא להודו' בהודאה שלמעלה מן השכל שמלמטה למעלה בשם אלקי' המצמצם הוא ג\"כ כמו בהשגחה שמלמעלה למטה דקמי' כלא כו' והיינו ענין שאנו או' מודים אנחנו לך כו' ואזי ע\"י הודאה זו נעשה היחוד בשם הוי' ואלקי' למהוי אחד באחד כנ\"ל ואמנם מי שלא כרע במודים אין לו כלי לקבל האור דיחוד זה לעתיד דכתיב אז עין בעין כו' וד\"ל.\n<b>וזהו</b> לעשות הישר בעיני ה' אלקיד דהיינו שיהי' ה' אלקיך יח\"ע ויח\"ת הנ\"ל מסתכלים ביושר פב\"פ מלמטה למעלה כמו מלמעלה למטה כמ\"ש ישר יחזו פנימו וכנ\"ל שזהו אינו אלא ע\"י התורה והמצות דוקא כמ\"ש כי תשמע בקול ה' לשמור כל מצוותיו לפי שעי\"ז נמשך האור בכלי מעצמו' אור א\"ס דקמי' ב' הדיעו' שוין כמ\"ש כי אל דיעו' הוי' שסובל ב' הדיעות והוא לפי שבחי' אנכי מי שאנכי שנק' סובב כ\"ע הוא כמשל העיגול שאין בו מעלה ומטה כלל ע\"כ שוה ומשוה להיו' ע\"י המצו' הסתכלו' ביושר למטה כמו למעלה כנ\"ל וזהו לעשות הישר בעיני ה' אלקיך ולא לשום כונה אחרת אלא רק שעי\"ז יהי' עין בעין כו' שזהו הישר והטוב בעיני ה' אלקיך וד\"ל.",[["4718","91","<b>מאן דלא כרע במודים</b>: ראה ב\"ק טז, סע\"א. זח\"ב ק, א. זח\"ג קסד, א."]]],[2100990274,"<h3>להבין שרשי הדברים</h3>\n<b>בעזר\"ה</b>\n<b>להבין</b><sup data-n=\"4719\">1</sup> שרשי הדברים הנ\"ל. הנה מבואר בחנוך<sup data-n=\"4720\">2</sup> קטן בענין יחודא עילא' ויחודא תתאה שבחי' שם אלקים הוא המצמצם כו'. ושרש הדברים דשם הוי' ושם אלקים המה ב' מדות עליונות שהמאציל מתלבש בהם לפעמים מתלבש בשם הוי' ונק' יחודא עילאה ולפעמים הוא מתלבש בשם אלקים ונק' יחודא תתאה והענין הוא כי בחי' עצמות המאציל הוא למעלה לגמרי מבחי' אור ושפע ואמנם כאשר רוצה להשפיע צריך שיתלבש בלבוש הנק' מדה כענין ומד\"ו ב\"ד שהלבוש נק' מדה ולפעמי' מתלבש במדת החסד שהוא שם הוי' והענין הוא שמשגיח בהשגחה של חסד ולפעמי' מתלבש בלבוש ומדה שנק' דין וצמצום והוא שמשגיח בהשגחה של דין וצמצום שהוא בחי' שם אלקים, והנה כאשר משגיח בהשגחה של שם הוי' היינו שרש &lt;של&gt;\nענין יחודא עילאה שהוא מלמעלה למטה דכתיב אתה<sup data-n=\"4721\">3</sup> ה' לבדך כו' וכולא<sup data-n=\"4722\">4</sup> קמיה כלא",[["4719","1","<b>להבין שרשי הדברים הנ\"ל</b>: הנחת כ\"ק אדה\"א. נעתק מגוכתי\"ק 1025 (פט, א). נאמר ג\"כ ע\"י כ\"ק אדמו\"ר הצ\"צ בשנת תקפ\"ט. ונמצא בכת\"י 13 לג, ב. 2025 קפה, א.\nנדפס בשינויים ותוס' הגהות בלקו\"ת ראה כג, ד. וראה מאמרי אדה\"ז על פרשיות התורה ע' תתא."],["4720","2","<b>בחנוך קטן</b>: שער היחוד והאמונה פ\"ו. וראה לעיל ע' תלט."],["4721","3","<b>אתה ה' לבדך</b>: ישעי' לז, כ."],["4722","4","<b>וכולא קמי כלא</b>: ראה זהר בהקדמה יא, ב."]]],[2100990275,"כו' כנ\"ל שלמעלה היש האמיתי שנק' מקור ולמטה האין ממש וע\"ז אמר משמים<sup data-n=\"4723\">5</sup> הביט הוי' כלומר שמשגיח למטה באופן כמו שהוא בעצם שבאמת קמי' כלא חשיב והוא מצד מדת החסד שמתגלה בטובו כו' ולפעמי' משגיח במדת הצמצום והדין דהיינו להסתיר ולהעלים א\"ע בשם אלקים המצמצם כו' כדי שע\"י צמצום זה נעשה הנברא בבחי' יש נפרד וה\"ז מאין ליש שהוא היפך הענין של מדת שם הוי' כו' וד\"ל.\n<b>ודרך</b> כלל ב' השגחו' הללו השגחה הראשונה דשם הוי' הוא בבחי' ז\"א דאצילו' והשגחה השניה בבחי' מלכו' דאצי' שהוא שם אלקים ודרך פרט גם באצילות עצמו יש ב' מדו' הללו בז\"א בחסד וגבור' לפעמי' משגיח באופן שהוא עושה למטה בחי' אין וכענין אין עוד ולפעמי' משגיח באופן שעושה בזה למטה בחי' יש נפרד כו' ומזה מסתעפים ב' מדרגו' הביטול בביטול דיחודא עילא' הוא בחי' ביטול אמיתי משום דבאמת קמי' כלא ממש ובחי' הביטול דיחודא [תתאה] היינו מ\"ש וצבא<sup data-n=\"4724\">6</sup> השמים לך משתחווי' שהוא בחי' ביטול היש בלבד כידוע שזהו ענין ההודאה במודים ומאן דלא כרע במודים כו' וד\"ל.\n<b>וזהו</b> פי' עיני<sup data-n=\"4725\">7</sup> ה' אל צדיקים. דהנה פי' צדיקים הוא יחוד ב' מדרגו' הנ\"ל דשם הוי' ואלקים דצדיק הוא כח המחבר ומקשר ויש ב' מדרגו' בצדיק הא' הנק' צדיק<sup data-n=\"4726\">8</sup> עליון והב' צדיק תחתון והם יוסף ובנימין כידוע וענין צדיק עליון הוא בחי' קישור וחיבור אור המשפיע במקבל ובחי' צדיק תחתון הוא בחי' התקשרות המקבל במשפיע וכתיב עיני ה' אל צדיקים להיות כי ב' עינים יש הא' עין המשגיח מלמעלה למטה והיינו בשם הוי' דקמי' כלא והעין הב' שמשגיח באופן שהוא מלמטה למעלה שלמעלה האין כו' וכנ\"ל וזהו ענין אל<sup data-n=\"4727\">9</sup> דיעו' הוי' כו' ולהיות בחי' יחוד וחיבור בין ב' העינים הללו דהיינו בין בחי' שם הוי' ושם אלקים היינו מ\"ש עיני<sup data-n=\"4728\">10</sup> ה' אל צדיקים שבחי' ב' צדיקים הנ\"ל יוסף ובנימין המה המחברים ומקשרים ב' השגחו' הללו להיות לאחדים ממש כי בחי' צדיק עליון מחבר העליון בתחתון ונק' שושבינא<sup data-n=\"4729\">11</sup> דמלכא וצדיק תחתון מחבר התחתון בעליון מלמטה למעלה וכענין עליו' העולמו' בשבת וע\"י אמצעו' שניהם מתייחדי' שם הוי' ואלקי' יחד ונעשה ב' מיני ביטול הנ\"ל ג\"כ בענין א' דהיינו שלמטה ג\"כ נעשה בחי' ביטול האמיתי כמו איך דקמי' כלא כו' וזהו בתנאי דוקא כאשר יש הכנה לזה בתחלה ביחודא תתא' והיינו בבחי' הביטול של הנבראי' שנק' ביטול היש כנ\"ל.\n<b>וזהו</b> מ\"ש בזוהר לענין עליו' העולמו' בשבת ואתתקנת<sup data-n=\"4730\">12</sup> ברזא דאחד למשרי עלה רזא דאחד כו' למהוי אחד באחד כו' דדוקא לאחר שניתקנה המלכו' ברזא",[["4723","5","<b>משמים הביט הוי'</b>: תהלים לג, יג."],["4724","6","<b>וצבא השמים לך משתחווי'</b>: נחמי' ט, ו."],["4725","7","<b>עיני ה' אל צדיקים</b>: תהלים לד, טז."],["4726","8","<b>צדיק עליון. . יוסף ובנימין</b>: ראה ג\"כ תו\"א פ, ד."],["4727","9","<b>אל דיעות הוי'</b>: שמואל-א ב, ג."],["4728","10","<b>עיני ה' אל צדיקים</b>: תהלים לד, טז."],["4729","11","<b>שושבינא דמלכא</b>: ראה זהר (רעיא מהימנא) ויקרא כ, א. מצורע נג, ב."],["4730","12","<b>ואתתקנת ברזא דאחד</b>: זהר שמות קלה, ב."]]],[2100990276,"דאחד ביחודא תתא' אז ישכון עלי' אור יחודא עילא' הנ\"ל להיו' למטה כמו למעלה וזהו למהוי אחד באחד (וע\"ז נא' עיני ה' אל צדיקי' צדיק וצדק כו' אבל מ\"ש עין<sup data-n=\"4731\">13</sup> ה' אל יריאיו היינו עין א' בלבד או יח\"ע או יח\"ת ולא בחי' התכללות משניהם יחד כו' או י\"ל דעין ה' אל יריאיו הם בחי' זו\"נ כאשר הם עולין באו\"א ומאיר עליהם &lt;שלא&gt;\nמבחי' עינא<sup data-n=\"4732\">14</sup> פקיחא דכתר דשם ב' עיינין אתהדרו לחד כמ\"ש באד\"ר וד\"ל) ואמנם גם בשבת אין היחוד דהוי' ואלקי' רק בבחי' הפנימיו' ולא בבחי' החיצוניו' שהרי בחיצוניו' העולמו' אין הפרש ניכר בין ימות החול ליום השבת כי בעוה\"ז הגשמי הרי כל גידול שפע דצח\"ם הוא בשבת כמו בחול לפי שיש עדיין אחיז' להיכלו' דנוגה בסטרא דקדוש' המסתירי' ומצמצמי' לבלתי הגלו' נגלות אור היחוד הנ\"ל גם בחיצוניו' העולמות אבל לע\"ל דכתיב ואת<sup data-n=\"4733\">15</sup> רוח הטומא' אעביר כו' ולא יסתיר מאומה אזי כתיב ונגלה<sup data-n=\"4734\">16</sup> כבוד הוי' כו' ולא<sup data-n=\"4735\">17</sup> יכנף עוד מוריך והיו<sup data-n=\"4736\">18</sup> עיניך רואות את מוריך וכן כתיב עין<sup data-n=\"4737\">19</sup> בעין נראה אתה ה' כו' דהיינו גם בחיצוניו' העולמו' כמו שעתה הוא היחוד הנ\"ל בפנימיו' ע\"י צדיקי' הנ\"ל כמאמרם ז\"ל עמוד<sup data-n=\"4738\">*19</sup> א' וצדיק שמו וכמ\"ש כי<sup data-n=\"4739\">20</sup> כל בשמים ובארץ ותרגומו דאחיד בשמיא וארעא שמחבר עליון בתחתון וכנ\"ל ובכל שבת יש מעין ודוגמא מה שיהי' ביום שכולו שבת אך ורק בבחי' הפנימיו' אבל ביום שכולו שבת הרי יהי' בחיצוניו' כמו בפנימיו' בהשווא' א' מטעם שיתברר כל הרע ויוסר הצמצום דשם אלקי' וכמארז\"ל ברמז לעתיד<sup data-n=\"4740\">21</sup> הקדב\"ה מוציא חמה מנרתקה שהוא שם האלקי' המלביש לשם הוי' כמ\"ש כי<sup data-n=\"4741\">22</sup> שמש ומגן ה' אלקים כמ\"ש בלק\"א וד\"ל ולכך נא' לע\"ל ונגלה כבוד ה' וראו כל בשר כו' לפי שבזמן התחיי' גם הגופים יהיו כמו בחי' מרכבה בלתי אכילה כו' כי העוה\"ב<sup data-n=\"4742\">23</sup> אין בו אכילה כו' וכל זה מטעם שישתווה בחי' החיצוניו' לבחי' הפנימיו' לגמרי מטעם הנ\"ל דהיחוד העליון יאיר למטה כמו שהוא למעלה ממש וד\"ל.\n<b>והנה</b> ע\"ד הנ\"ל בענין ב' יחוד' יח\"ע ויח\"ת דהוי' אלקי' שהוא בחי' זו\"נ בכלל כך יובן ענין זה עוד למעלה יותר דרך כלל דהנה ידוע דבחי' ז\"א לגבי בחי' עתיק' הוא כערך בחי' חיצוניו' לגבי בחי' הפנימיו' כי בחי' עתיק' הוא מבחי' עצמו' המאציל עדיין שלמעלה הרבה מבחי' השתלשלו' דאצי' ובחי' ז\"א הוא בחי' האצי' אורו' בכלים כו' וזהו שאמר בע\"ח דגם שז\"א הוא נק' בשם הוי' לגבי התחתונים אבל לגבי בחי' ע\"י נחשב רק לבחי' שם אלקי' וז\"ש יעקב והי'<sup data-n=\"4743\">24</sup> הוי' לי לאלקים שהוא",[["4731","13","<b>עין ה' אל יריאיו</b>: תהלים לג, יח."],["4732","14","<b>עינא פקיחא דכתר</b>: ראה זהר נשא (אדרא רבא) קכט, ב."],["4733","15","<b>ואת רוח הטומאה אעביר</b>: זכרי' יג, ב."],["4734","16","<b>ונגלה כבוד הוי'</b>: ישעי' מ, ה."],["4735","17","<b>ולא יכנף עוד מוריך</b>: ישעי' ל, כ."],["4736","18","<b>והיו עיניך רואות את מוריך</b>: ישעי' ל, כ."],["4737","19","<b>עין בעין נראה אתה ה'</b>: שלח יד, יד."],["4738","*19","<b>עמוד א' וצדיק שמו</b>: ראה חגיגה יב, ב."],["4739","20","<b>כי כל בשמים ובארץ ותרגומו דאחיד</b>: דברי הימים-א כט, יא. ראה זהר בראשית לא, א."],["4740","21","<b>לעתיד הקדב\"ה מוציא חמה מנרתקה</b>: נדרים ח, ב."],["4741","22","<b>כי שמש ומגן ה' אלקים כמ\"ש בלק\"א</b>: תהלים פד, יב. שער היחוד והאמונה פ\"ד."],["4742","23","<b>כי העוה\"ב אין בו אכילה</b>: ראה ברכות יז, א."],["4743","24","<b>והי' הוי' לי לאלקים</b>: ויצא כח, כא. וראה תו\"ח שמות מח, ג."]]],[2100990277,"בחי' עליי' ז\"א לגבי עתיק' שנחשב שם לבחי' אלקי' בלבד כי האצי' אינו אלא בחי' צמצום המאציל ע\"י שם אלקי' שהוא המצמצם בכל מקום כנודע וזהו שאנו או' בנעילה<sup data-n=\"4744\">25</sup> דיו\"כ ז\"פ כי הוי' הוא האלקי' דהיינו ז' עליו' לז\"א שהוא הוי' שיהי' בבחי' האלקי' לגבי עתיקא ששם עולין זו\"נ ביו\"כ כידוע וד\"ל.\n<b>והנה</b> כמו שמבואר למעלה בענין ב' השגחות דב' מדו' הוי' ואלקי' שהם ב' הפכי' שהשגחת שם הוי' הוא מלמעלה למטה להיו' באופן כמו שהוא בעצמו דקמי' כלא חשיב כו' והשגחה דשם אלקי' הוא בהיפוך לצמצם ולהעלים א\"ע להיו' דוקא נראה העולם ליש ודבר כו' כנ\"ל באריכות כך יתפרש ג\"כ ענין שני המדו' הללו דהוי' ואלקי' בבחי' עתיק' ובבחי' ז\"א דבבחי' עתיק שהוא שם הוי' בדרך כלל הנה השגחתו מלמעלה למטה באופן &lt;שלב&gt;\nדקמי' כלא כו' והשגחה דבחי' ז\"א הוא בבחי' הצמצום דשם אלקי' בהיפוך כנ\"ל והנה ע\"ז נאמר ג\"כ עיני הוי' אל צדיקי' להיו' התחברו' עליון בתחתון ותחתון בעליון והוא ענין אסתכלותא<sup data-n=\"4745\">26</sup> דעתיקא בז\"א מלמעלה למטה שממשיך לו ש\"ע נהורין ואז נק' ארך אפים כמ\"ש חנון<sup data-n=\"4746\">27</sup> ורחום הוי' ארך אפים שגם ז\"א נק' ארך אפים להיות כי ארך גי' רכ\"א שהן ש\"ע נהורין עם ק\"נ אורו' דאבא שקבועי' תמיד בז\"א כל זה בא לו מפני בחי' הארת הפנים דעתיקא כמ\"ש יאר<sup data-n=\"4747\">28</sup> ה' פניו אליך כו' דהיינו ארך אפים ונעשה ש\"ע נהורין ואסתכלותא דז\"א בעתיקא הוא מלמטה למעלה וכדי שיהי' ההשגחה פב\"פ דע\"י בז\"א בהשווא' א' מלמטה למעלה כמו מלמעלה למטה כנ\"ל בפי' עיני ה' אל צדיקים בזו\"נ הוא ע\"י קול דתורה דוקא מפני שנמסר על ידי זה מפתחות הפנימיו' פי' בקול דתורה נמשך מבחי' פנימי' אור המאציל דע\"י שיסתכל בז\"א פב\"פ ויתחבר עליון בתחתון ותחתון בעליון ע\"ד הנ\"ל בשמו' דהוי' ואלקי' בזו\"נ וכידוע דקול<sup data-n=\"4748\">29</sup> דתורה נק' קול יעקב ובקול פנימיותו מאיר מבחי' עתיק' והוא שנק' מפתחו' הפנימיו' וע\"ז אמרו הקדב\"ה<sup data-n=\"4749\">30</sup> יושב וקורא ושונה כנגדו כו' וד\"ל.\n<b>וזהו</b> כי תשמע בקול ה' אלקיך כו' לעשות הישר בעיני ה' אלקיך פי' בקול דהוי' הוא בחי' ז\"א שנעשה בחי' אלקי' לגבי עתיקא ואזי מסתכל בו בחי' ע\"י להאיר לו פניו כנ\"ל ונעשה יחוד וחיבור ב' השגחו' כאחד וזהו לעשות הישר בעיני ה' אלקיך וכמ\"ש ישר<sup data-n=\"4750\">31</sup> יחזו פנימו דהיינו שיהא ההשגחו' עין בעין מלמעלה למטה ומלמטה למעלה בהשווא' א' ביושר א' ולא יהיו ב' הפכי' כנ\"ל בענין יח\"ע ויח\"ת דזו\"נ וכך יתפרש באסתכלותא דע\"י בז\"א שע\"ז נא' ג\"כ לעשו' הישר בעיני הוי' אלקיך אלא שהוא דרך כלל יותר כנ\"ל וד\"ל.",[["4744","25","<b>בנעילה דיו\"כ ז\"פ כי הוי' הוא האלקי'</b>: ראה תו\"ח בראשית לו, ג. מאמרי אדה\"א הנחות תקע\"ז ע' שמו."],["4745","26","<b>אסתכלותא דעתיקא בז\"א</b>: ראה זח\"ג טו, א."],["4746","27","<b>חנון ורחום הוי' ארך אפים</b>: תהלים קמה, ח."],["4747","28","<b>יאר ה' פניו</b>: נשא ו, כה."],["4748","29","<b>דקול דתורה נק' קול יעקב</b>: ראה ג\"כ לקו\"ת ואתחנן ח, ג."],["4749","30","<b>הקב\"ה יושב וקורא ושונה כנגדו</b>: תנדבא\"ר רפי\"ח."],["4750","31","<b>ישר יחזו פנימו</b>: תהלים יא, ז."]]],[2100990278,"<b>אך</b> הטעם להסתכלו' פב\"פ ביושר שהוא ע\"י קול תורה דוקא הוא מפני שהתורה נק' דרך הישר כמ\"ש כי<sup data-n=\"4751\">32</sup> ישרים דרכי ה' כו' לפי שהתורה<sup data-n=\"4752\">33</sup> היא בבחי' קו האמצעי שנק' ישר כמ\"ש בע\"ח להיותה בבחי' התיקון וההתכללו' כו' וידוע דקו האמצעי מבריח<sup data-n=\"4753\">34</sup> מן הקצה לקצה ע\"כ על ידו דוקא יתחבר העליון בתחתון דהיינו ע\"י בז\"א כמ\"ש ישר יחזו פנימו ע\"י קו האמצעי שנק' ישר יחזו פנימו באסתכלותא הנ\"ל והיינו ע\"י קול דתורה והיינו כי תשמע בקול במה שיש בקול דתורה גנוז מאור דע\"י לפי שהיא בחי' קו האמצעי כו' כדי לעשות הישר בעיני ה' אלקיך לאסתכלא אנפין באנפין כנ\"ל וד\"ל.\n<b>ובכל</b> זה מובן ג\"כ שרש ענין מה שאמר לפעמי' עין ה' אל יריאיו עין א' וכן לעתיד נא' עין בעין כו' דהיינו לאחר שנתייחד העליון בתחתון וב' ההשגחות שוות ממש אזי עין א' לשניהם והיינו בחי' עינא<sup data-n=\"4754\">35</sup> פקיחא דלא נאים כו' ששם אין התחלקו' כלל ותרין עיינין אתהדרו לחד כו' ומשום שלמטה יהי' כמו למעלה לכך נא' עין בעין כו' וד\"ל.\n<b>לשמור</b> כל מצוותיו כו'. הנה המצות הם ענין שמירה לשמור האור בתוכן כמבואר ומחיצוניו' שלהם נמשך האור והזיו בעוה\"ב כו' ולהבין שרש ענין זה יש להקדים בענין המצות דלכאורה אינו מובן מה שלפעמי' משמעו' ענין המצות שהן רק בחי' המשכו' גילוי אלקו' שהרי נק' רמ\"ח &lt;שלג&gt;\nאיברי' ור\"ל רמ\"ח המשכו' כו' ולפעמי' משמעו' ענינם שהן היפך ההמשכה אלא נק' כלים של קבלה כמ\"ש כי<sup data-n=\"4755\">36</sup> נר מצוה ותורה אור הרי זה היפך ההמשכה כי הנר אינו אלא מקבל האור בתוכו כו'.\n<b>אך</b> הענין הוא דשניהם אמת דלגבי בחי' פנימי' האור שגנוז בעצמו' המאציל לא נקראו רק בחי' כלי קבלה בלבד להכניס האור בתוכן בלבד עד\"מ האבר שהוא רק בחי' כלי בעלמא לאור וחיות הנפש השוכן בה שהוא כמשל הנר לגבי האור אבל לגבי בחי' העולמו' התחתוני' שנאצלו ונבראו יש מאין כמו העוה\"ב שנהנין מזיו וכיוצא נק' המצות בשם בחי' המשכו' שממשיכי' את ההשפעה מאור המאציל מלמעלה למטה עד\"מ האיברי' שיש בהם בחי' ההמשכות מן הכחות המלובשי' בהם כמו חסד<sup data-n=\"4756\">37</sup> דרועא ימינא להחיו' רוח שפלי' כו' וכיוצא ועד\"ז הרי יובן דהמצות מבחי' החיצוניו' שלהם נק' המשכו' להיו' מקור לעוה\"ב כענין שכר<sup data-n=\"4757\">38</sup> מצוה מצוה כידוע ומצד בחי' הפנימי' נק' כלים לאור ולא ממשיכי' המשכו' וא\"כ דהמצוה הנעשית בעוה\"ז גדול מעלתה משכר המצוה בג\"ע כשנהנה מזיו כו' שהרי בעשותו",[["4751","32","<b>כי ישרים דרכי הוי'</b>: הושע יד, י."],["4752","33","<b>שהתורה. . ישר</b>: ראה יהושע י, יג. ובתרגום ומפרשים שם. תו\"ח בראשית מא, ד."],["4753","34","<b>מבריח מן הקצה לקצה</b>: ע\"פ לשון הכתוב תרומה כו, כח. ויקהל לו, לג. ראה זהר תרומה קעה, ב."],["4754","35","<b>עינא פקיחא</b>: ראה זהר (אדרא רבא) נשא קכט, ב."],["4755","36","<b>כי נר מצוה ותורה אור</b>: משלי ו, כג."],["4756","37","<b>חסד דרועא ימינא</b>: תקו\"ז בהקדמה."],["4757","38","<b>שכר מצוה מצוה</b>: אבות פ\"ד, מ\"ב."]]],[2100990279,"המצוה בעוה\"ז נק' נר מצוה לקבל אור המאציל עצמו בבחי' הפנימי' ובג\"ע הוא שנמשך רק מבחי' החיצוניו' שלה בלבד להיו' גילוי אור האלקי בג\"ע שבעולם הבריא' שהוא רק בחי' חיצוניו' האצי' כידוע וע\"כ אמרו ז\"ל דיפה<sup data-n=\"4758\">39</sup> שעה א' בתשובה ומע\"ט בעוה\"ז מכל חיי העוה\"ב וד\"ל.\n<b>וזהו</b> לשמור את כל מצוותיו פי' המצו' נק' כלים לאור דתורה כמ\"ש כי נר מצוה ותורה אור שהוא להיו' הישר בעיני ה' כנ\"ל ובמצות משתמר האור הזה תמיד כי בלתי המצות הרי אין כלי לשמור ההארה של קול ה' אשר בתורה והיינו כי תשמע בקול ה' לשמור את כל מצוותיו כו' ר\"ל כי תרצה לשמוע בקול ה' ע\"ד הנ\"ל אין הדבר תלוי רק בשמירת המצות להיו' כלים לאור דתורה ועיקר הטעם כי גם שרש המצו'<sup data-n=\"4759\">40</sup> מבחי' עתיק' כי הרי נק' תרי\"ג ארחין כו' והם הנק' ישרים דרכי הוי' להיו' ישר יחזו פנימו פב\"פ כנ\"ל אלא שירדו למטה להיו' כלים לאור דתורה אבל שרשם במדרג' א' הם עם הקול דתורה וזהו שאמר אשר אנכי מצוך היום פי' אנכי מי שאנכי דהיינו בחי' ע\"י וע\"כ אומרי' בברכו' המצות אשר קדשנו מלשון כי אשרוני בנות שהוא בחי' העונג העליון דע\"י כי התענוג העליון מלובש ברצון העליון שבמצות כידוע וד\"ל.\n<b>ומה</b> שאמר אשר אנכי מצוך היום היום דוקא ועי\"ז תוכל לעשו' הישר בעיני ה' כו' ע\"ד הנ\"ל, הענין הוא כי לכאורה יש להבין דהלא ג'<sup data-n=\"4760\">41</sup> מתנות טובות יש עוה\"ב ותורה כו' וכולן באין ע\"י יסורי' העוה\"ב אחר יסורי גיהנם וגלגולי' רבים כו' והלא יפה שעה א' בתשובה ומע\"ט בעוה\"ז מכל חיי העוה\"ב וא\"כ הי' ראוי שיקבל האדם יסורי' בעוה\"ז בכפלי כפלי' מיסורי גיהנם עד שיוכל לבא לעסק התורה והמצות ואנו רואי' שאינו כן אך הענין הוא דלא כהעוה\"ב העוה\"ז דעוה\"ב<sup data-n=\"4761\">42</sup> מקבל מבחי' סדרי השתלשלו' דלאחר התיקון ונק' עולם ברור ושם הרי נידונים כאו\"א לפי מדתו הראוי לו וע\"כ אין תשובה בעוה\"ב לפי שאין כל א' מכיר אלא כמו שהוא ולא יוכל לעלות ממדרג' למדרג' וע\"כ גם מי שהוא למעלה לא יוכל לבא למטה כו' אבל בעוה\"ז הוא זמן הבירור ויכול התחתון לעלו' למעלה &lt;שלד&gt;\nמכפי מדתו ועליון יכול לירד למטה וע\"כ עיקר התשובה בעוה\"ז כמו ראב\"ד<sup data-n=\"4762\">43</sup> שעלה מבירא עמיקת' לרום המעלו' בשעה א' וכל זה מפני שהיום הוא זמן הבירור מבחי' אנכי מי שאנכי הסובב ומקיף כל ההשתלשלו' בהשווא' א' וע\"כ יש ביכולתו לעלו' התחתון למעלה כו' משום דקמי' כחשיכה כאורה עד שהזדונו' יהיו כזכיו' ע\"י התשובה כידוע מה שא\"א להיו' כזה בעוה\"ב וזהו אשר אנכי מצוך היום דוקא ועתה הוא הזמן לעשות הישר בעיני ה' אלקיך ע\"ד הנ\"ל להיו' עין בעין מלמטה למעלה",[["4758","39","<b>דיפה שעה אחת בתשובה ומע\"ט</b>: אבות פ\"ד, מי\"ז."],["4759","40","<b>המצות. . תרי\"ג ארחין</b>: ראה זהר (אדרא רבא) נשא קכט, א. קלו, א."],["4760","41","<b>ג' מתנות טובות</b>: ברכות ה, סע\"א."],["4761","42","<b>דעוה\"ב. . ונק' עולם ברור</b>: ראה פסחים נ, א."],["4762","43","<b>ראב\"ד שעלה מבירא עמיקת'</b>: ראה ע\"ז יז, א."]]],[2100990280,"כמו מלמעלה למטה שזה היפוך סדר השתלשלו' לפי שאנכי מצוך היום שהוא בחי' סובב הכללי ביותר שאין בו מעלה ומטה כלל וקו היושר בוקע בו מעליונו לתחתיתו כמ\"ש בע\"ח וד\"ל."],[2100990281,"<h3>זהר בלק פתח האי ינוקא ואמר שחורה אני ונאוה</h3>\n<b>שבת פ' ראה</b>\n<b>זהר</b><sup data-n=\"4763\">1</sup> בלק<sup data-n=\"4764\">2</sup> דף קצ\"א פתח האי ינוקא ואמר שחורה אני ונאוה בנות ירושלים וכו' אל תראוני שאני שחרחורת וגו' בשעתא דאיהי גו רחימא סגיא לגבי' רחימה מגו דחיקו דרחימו דלא יכלה למסבל אזעירת גרמה בזעירו סגיא עד דלא אתחזיאת מינה אלא זעירו דנקודה חדא ומאי איהי יוד כדין אתכסיאת מכל חילין ומשריין דילה ואיהי אמרת שחורה אני דלית באת דא חיוורו בגווי' כשאר אתוון ודא שחורה אני ולית לי רשו לאעלא לכון תחות גדפאי וכו' ובג\"כ אל תראוני לא תחמון בי כלל דאנא נקודה זעירא מה עבדין גברין תקיפין חיילין דילה שאגין כארי' תקיפין כד\"א הכפירים שואגים לטרף ומגו דחילו שמע רחימה דלעילא וידע דרחימתי' היא ברחימו כוותי' מגו קלין ושאגין תקיפין דקא משאגין כאריין גברין תקיפין דמתא מגו רחימו עד דלא אתחזיאת מדיוקנא ושפירו דילה כלל וכדין מגו קלין ושאגין דאינון גברי חילא דילה נפיק דודה רחימה מגו היכלא בכמה מתנן כו' ובחדו דרחימותא דעמה אתבניאת ואתעבידת בתיקונהא בדיוקנהא בשפירו דילה כמלקדמין ודא גבורי כח עשו לה ואהדרו לה לדיוקנא ושפירו דילה דתוקפא וגבורתא דלהון גרימו דא וע\"ד כתיב גיבורי כח עושי דברו עושים אותי ודאי ומתקנין לי' ומהדרין לי' לדיוקנא קדמאה וכו' כגוונא דא לתתא בזמנא דחייבין בדרא איהי אתכסיאת ואזעירת גרמה עד דלא אתחזיאת מכל דיוקנהא בה כד אתאן גבורי כח וזכאי קשוט כביכול עושים להאי דבר ואנהירת זעיר זעיר ואתעבידת בדיוקנהא בשפירו דילה כמלקדמין ע\"ש.\n<b>וביאור</b> הענין הוא ע\"פ מארז\"ל אנשי<sup data-n=\"4765\">3</sup> כנה\"ג החזירו עטרה ליושנה. ולהבין זה מהו ענין עטרה הישנה ומהו ענין חזרתה צ\"ל מ\"ש בע\"ח<sup data-n=\"4766\">4</sup> שהמשכת קו",[["4763","1","<b>זהר בלק דף קצ\"א פתח האי ינוקא</b>: הנחת המהרי\"ל. נעתק מכת\"י 80 פ, ב. 392 מה, ב.\nנוסח אחר (הנחת כ\"ק אדמו\"ר האמצעי) נמצא בגוכתי\"ק 1025. נעתק בכת\"י 611 פז, א. בכותרת: בעז\"ה שבת פ' ראה [שייך למאמר בזוהר בלק דק\"צ ע\"ב ע\"פ ברכו ה' מלאכיו כו' הנ\"ל דשבת פ' פנחס] נדפס בביאוה\"ז ק, א.\nנוסח אחר נדפס בהנחות הר\"פ ע' לח בכותרת: זוהר בלק תקס\"ו, אלול, לאדי.\nמאמר זה נדפס ג\"כ במאמרי אדה\"ז — ש\"ס ע' רפא."],["4764","2","<b>זהר בלק</b>: הלשון כאן הוא בכמה שינויים מלשון הזוהר."],["4765","3","<b>אנשי כנה\"ג החזירו עטרה ליושנה</b>: יומא סט, ב. וראה ילקוט שמעוני נחמי' רמז תתרעא."],["4766","4","<b>בע\"ח שהמשכת קו המדה מהמאציל</b>: ראה לקו\"ת נשא כז, ג-ד. סה\"מ תרל\"ב ח\"ב ע' תז."]]],[2100990282,"המדה מהמאציל ב\"ה להיות אורות וכלים דנאצלים בבחי' שרשים ובבחי' תוספ' דהיינו שבז\"א לא נאצל בתחלה כ\"א בחי' ו\"ק בחי' שרשים ובנוק' בחי' כתר לבד ואח\"כ באו ג\"ר דידי' וט' אחרונות דידה בסוד תוס' (והטעם מבואר שם שיהיו מסתלקין מפני מעשה התחתונים ע\"ש).\n<b>והענין</b> הוא ע\"פ ביאור הכתוב ארוממך<sup data-n=\"4767\">5</sup> אלקי המלך ואברכה שמך לעולם ועד, פי' ארוממך לנוכח שהוא קאי על חיצוניות בחי' כתר שם ב\"ן מל' שבכתר והיינו ע\"י שיתעלה ויתרומם בחי' אלהי המלך מל' שבכתר לבחי' עצמיות א\"ס ב\"ה יומשך להיות ואברכ\"ה שמך בחי' מל' דאצי' בנין הנוק' בפרצוף שלם מי\"ס לעולם ועד בבי\"ע. דהנה מהות בחי' מל' דאצי' הוא בחי' ממוצע בין נאצלים לנבראים שבחי' כתר דנוק' הוא מתנשא מימות עולם דנבראים ואינו נתפס ומתלבש בהם כלל והוא בחי' אצי' ממש רק בחי' חב\"ד וכו' יורדים להתלבש בבי\"ע בבחי' מקוריי' ושרשיים (כמ\"ש במ\"א ענין הממוצע) שכל מהות בחי' מל'<sup data-n=\"4768\">6</sup> הוא התגלות האצילות שאינה מהות בפ\"ע סיהרא<sup data-n=\"4769\">7</sup> לית לה מגרמה כלום כ\"א בחי' התגלות החכמה וכל התגלות חו\"ג וכו' שממהות בחי' התגלות של כל מדה ומדה שהוא מלכות של המדות נעשה מזה פרצוף הנוק' להתגלות לזולתו בבי\"ע ממש וכמשל דבור שבפה האדם המגלה מצפוני לבו לזולתו ע\"י גילויי השפעות המדות בחזה הלב שלפי אופני גילויים בשינויים ומזיגות שונות אם חסד וכו' בכלי הלב ככה ממש יומשך בדבור שבפה שמהות המדה בפ\"ע היא בחי' מציאות מציאת החסד וכו' (כמ\"ש במ\"א ענין ב' בחי' מציאות והתגלות).\n<b>והנה</b> מבשרי אחזה מאדם הרוצה לגלות ולהשפיע איזה השפעה פרטית לזולתו הפחות מערכו מוכרח הוא שיהי' בזה כל עשר בחי' הנפש דהיינו בחי' חכמה איך לגלות וכן בחי' בינה וכו' ואח\"כ ע\"י חו\"ג וכו', אך מפני מה יהי' בחי' החב\"ד וכו' להתגלות באופן זה דוקא ומפני מה יגלה וישפיע לו כל עיקר היינו מחמת שרצונו בזה ורצון הוא למעלה וכו'. כמו\"כ יובן למעלה בבחי' מל' דאצילות שיש בה ג\"כ ע\"ס חב\"ד כו' שהמקור להם הוא בחי' כתר דתהו רצון להתגלות מלכותו ואח\"כ ע\"י הרצון נמשך בחי' חכמה איך לגלות וכו'.\n<b>והנה</b> כתיב לעולם<sup data-n=\"4770\">8</sup> ה' דברך נצב בשמים שכתר דנוק' דבוק באחורי ז\"א (כנודע שכל עלול דבוק בעילתו בחציו העליונה והוא בחי' כתר שבכל פרצוף של המקבל שהוא דבוק עם פרצוף של המשפיע) והיינו שבחי' הרצון להתגלות מלכותו הנמשך מז\"א דאצי' אין בו עדיין שום בחי' גילוי השפעה לזולתו כ\"א כאשר יתפשט",[["4767","5","<b>ארוממך אלקי המלך</b>: תהלים קמה, א."],["4768","6","<b>מל'. . לית לה מגרמה כלום</b>: ראה ע\"ח (שער העקודים) ש\"ו, פ\"ו."],["4769","7","<b>סיהרא לית לה מגרמה כלום</b>: ראה זהר תולדות קלה, סע\"ב. ויחי רלו, ב. שם רמט, ב. ויקהל רא, א. בחוקותי קיג, ב."],["4770","8","<b>לעולם ה' דברך נצב בשמים</b>: תהלים קיט, פט."]]],[2100990283,"בחב\"ד כו' שמהותו אינו כ\"א בחי' רצון להתגלות ותו לא. ובראשית המשכת הרצון מהמדות העליונות הי' כלול ממש עמהם בלי שיומשך להתפשט באורך ורוחב בחב\"ד וכו' להיות ראש לשועלים בבי\"ע כ\"א התכללות בעצמותה וכו' כמשי\"ת. והנה בראשית המשכת קו המדה מהמאציל ב\"ה לא הי' באפשרי להמשך ולהיות נאצל בנוק' כ\"א בחי' כתר שלה רצון למלכותו לבד מבלי שיתגלה חב\"ד דידה ושיתהווה בחי' חכמה להתפשטות מלכותך מל' כ\"ע בבי\"ע כו' והסיבה הוא מחמת שנעוץ<sup data-n=\"4771\">9</sup> סופן בתחלתן.\n<b>והענין</b> הוא שכמו שהוא בסופא דכל דרגין בבחי' מל' דאצי' שהוא בחי' ממוצע ובחי' התגלות לבד וכו' כמ\"כ הוא למעלה מעלה בבחי' כתר דאצילות הכללי הכולל ב' פרצופים ע\"י ואריך שהוא ג\"כ בחי' ממוצע בין המאציל ב\"ה לפרצופי האצילות שאינם מערכו ומהותו כלל (כמ\"ש כולם<sup data-n=\"4772\">10</sup> בחכמה עשית שנק' אדם דעשי' וכמ\"ש במ\"א) וצריך להיות ע\"י ממוצע וכו' שהוא בחי' כתר דאצילות, והוא ג\"כ בחי' התגלות לבד שאינו שום מהות בפ\"ע וכו' רק שאינו התגלות שום דבר ומהות ח\"ו כ\"א התגלות אא\"ס הפשוט בתכלית הפשיטות שאינו מערך ומהות האצילות ובכדי שיהי' בבחי' חכם ומבין בבחי' חב\"ד דאצילות הוא ע\"י בחי' מל' שבכתר שהוא בחי' ב\"ן שבכתר התגלות של הכתר להתהוות בנין האצילות חב\"ד וכו' דגם דלית שמאלא בעתיקא מ\"מ כלול הוא ממ\"ה וב\"ן פנימיות וחיצוניות ונק' דרך כלל ע\"י וא\"א, והיינו שבחי' א\"א וב\"ן הוא בנין המל' דא\"ק בבחי' חב\"ד וכו'.\n<b>והענין</b> שבחי' כתר בכל מקום הוא בחי' רצון ובכדי שיתהווה חכמה ובינה וכו' צ\"ל התגלות הרצון לי' המשכות פרטיות רצון לחכמה ורצון לבינה כו' שהוא הכח הפרטי לפרצופי האצילות שאף שאין ברצון התחלקות פרטיי' בגלוי ממש בהבדלי חלקים שונים זה מזה שהכל הוא בחי' רצון מ\"מ הוא מתפשט בכוחות ומקורות מיוחדים רצון לחכמה כו' והוא כמשל כח היולי הכולל כל הגילויים בהעלמו בבחי' בכח לבד והוא נראה פשוט מ\"מ מאחר שהפעולות הנמשכים ממנו אח\"כ בהגילוים הם שונים זמ\"ז מוכרח הוא שיוכללו בהעלמו ג\"כ כוחות ומקורות מיוחדים לכל גילוי פרטי. וכמו\"כ הוא בבחי' ב\"ן שבכתר שהוא הכח והמקור האמיתי לע\"ס דאצי' בבחי' רצון צ\"ל כוחות ורצונות פרטיי' וכנ\"ל מאחר שהאצי' מתחלק באורות וכלים חב\"ד כו' רק ששם הם בהעלם כל הכוחות והרצונות וע\"ז נאמר ע\"ס גנוזות במאצילן דאף שהם עשר מ\"מ הם גנוזות בבחי' התעלמות הרצונות כו' ונק' בס\"י<sup data-n=\"4773\">11</sup> בשם עשרה עומקים שהוא בחי' חיצוניות הכתר בבחי' התפשטות בנין המל' דא\"ק רצון לחכמה כנ\"ל מ\"מ הוא בחי' עומקים שאין ההתחלקות בפועל ח\"ו כ\"א בבחי' כח ומקור לבד וד\"ל.",[["4771","9","<b>שנעוץ סופן בתחלתן</b>: ס\"י פ\"א, מ\"ז."],["4772","10","<b>כולם בחכמה עשית</b>: תהלים קד, כד."],["4773","11","<b>בס\"י בשם עשרה עומקים</b>: פ\"א, מ\"ה. וראה סה\"מ תרכ\"ט ע' שסא — (הובא בפע\"ח). סה\"מ תקס\"ד ע' רכד ואילך. הובא באוה\"ת דרושים ליוהכ\"פ ע' א'תקנז."]]],[2100990284,"<b>אמנם</b> כתר המל' דא\"ק בחי' ע\"י המתנשא מימות עולם דנאצלים שאינו אף בבחי' כח ומקור לפרצופים שבאצי' כ\"א הארת הרצון הפשוט ומופשט מבחי' כח ומקור וכו' נק' עומק שבעומק להיותו מושלל אף מהעשרה עומקים והוא כמשל רצון העצמיי בראשית המשכתו מעצם הנפש שהוא מושלל מבחי' פרטיי' וחלקים מובדלים אף מבחי' בכח לרצות דבר מה כו' שהוא ענין פשיטות הרצון כמ\"כ בחי' כתר<sup data-n=\"4774\">12</sup> שבכתר נק' רעווא דכל רעוין פי' כמו באדם התחתוז ד\"מ שאף דמהרצון הפשוט הנ\"ל נמשכים אח\"כ רצונות פרטיות לכל דבר המצטרך וכו' מ\"מ הוא מושלל מהם בראשית המשכתו מעצם הנפש שהוא בבחי' התכללות בעצמות ממש מבלי שיומשך רק שבחי' חיצוניות מתגלה אח\"כ ברצונות פרטיים כו' כמו\"כ למעלה ראשית עליות הרצון הפשוט פנימיות הכתר מ\"ה וכו' נק' בשם רעוא דכל רעוין וד\"ל, סתימו<sup data-n=\"4775\">13</sup> דכל סתימין היינו אף שרצונות הפרטיי' רצון וחכמה הם ג\"כ נעלמים שאינם כ\"א כוחות ומקוריים כמשל כח היולי הנ\"ל מ\"מ פנימית הרצון סתום אף מהנעלמים והסתומים שעדיין אין שום גילוי פרטיות הרצונות שהוא בחי' בנין מל' דא\"ק בע\"ס רצון וחכמה כו' י\"ס דאריך כ\"א בחי' כתר מל' דא\"ק רצון הפשוט כו'. והנה בראשית המשכות אא\"ס ב\"ה בעליות הרצון כו' שיתהווה מקור ושרש לנאצלים לא נמשך כ\"א בחי' כתר שבכתר הנ\"ל רצון הפשוט ולא הי' הבנין דמל' דא\"ק רצון לחכמה כו' (ומחמת זה למטה ג\"כ בנוק' דז\"א לא נמשך כ\"א כתר מל' לבד כנ\"ל כי נעוץ תחב\"ס שמל' דאצילות נמשכת בשרשה ממל' דא\"ק וכמ\"ש במ\"א ששניהם הם בחי' התגלות רק שמל' דאצי' הוא בחי' התגלות מדות העליונות כו' וכתר דאצי' שהוא בחי' התגלות אא\"ס הפשוט שענין הגילוי הוא שאינו עצם וד\"ל וכמ\"ש במ\"א אך מ\"מ הוא ג\"כ פשוט כנ\"ל וד\"ל). וטעם הדבר שלא נמשך בתחלת האצילות וההמשכה יותר מבחי' כתר דמל' דא\"ק היינו כי איידי<sup data-n=\"4776\">14</sup> דטריד למבלע לא פליט כמשל התלמיד כשהוא טרוד במוחו לשמוע דבר שכל מרבו אזי מחמת טרדתו לקבל נמנע הוא להשפיע לזולתו איזה בחי' השכלה כנראה בחוש.\n<b>וביאור</b> הענין הוא למעלה דהנה בכל בחי' יש חו\"ג וכמו\"כ ברצון יש ג\"כ חו\"ג שהוא כמשל הגדפין שתנועתם הוא שבגף אחד מתחזק העוף שיגביה א\"ע למעלה ובגף השני הוא דוחה את האויר למטה, כמו\"כ בחי' חסד בכל מקום הוא ההמשכה וההשפעה להשפיע לזולתו דוקא טבע המים לירד כו', אמנם בחי' גבורות הוא ההיפוך ממש שהוא ענין הצמצום וקבוץ המהות בעצמיות הנפש מבלי שיתפשט כו', כמו\"כ בחי' חסדים שברצון הוא בחי' התפשטות הרצון שיבא בגילוי להשפיע לזולתו ובחי' גבורות הוא התעלמות הרצון מבלי שיומשך למטה וד\"ל. וכמו\"כ יובן למעלה למשכיל בראשית המשכת הרצון הפשוט שהוא כלול עדיין בעצם אא\"ס ב\"ה ודבוק עמו בתכלית (כמשל רצון העצמי בראשית המשכתו שהוא כלול תמיד במקורו והוא ענין כל עלול דבוק בעילתו) מחמת זה לא הי' יכול להמשך ממנו הבנין רצונות",[["4774","12","<b>כתר שבכתר שנק' רעווא דכל רעוין</b>: ראה ג\"כ שערי תשובה קמג, ד."],["4775","13","<b>סתימו דכל סתימין</b>: ראה זח\"ב פט, א. קמו, ב. וראה תקו\"ז בהקדמה (יז, א)."],["4776","14","<b>איידי דטריד למבלע לא פליט</b>: ראה חולין קח, ב. וראה תו\"ח נח סג, ג הערה 44."]]],[2100990285,"פרטיות כו' מסיבת התכללותו בעצמיות עדיין בראשית המשכתו אזי הכל חוזר למקורו להתנשא ולהתעלם בעילתו א\"ס ב\"ה מבלי שיתפשט כו' וד\"ל. וב' הבחי' שברצון נק' עומק רום ועומק תחת, עומק רום הוא בחי' התדבקות הרצון בעילתו בראשית המשכתו כו' ועומק תחת הוא בחי' התפשטותו והמשכתו למטה שיהי' מקור ושרש כו'. נמצא לפ\"ז שבראשית המשכת הרצון מצד התנשאותו והתדבקותו למעלה לא הי' באפשרי בשום אופן להמשך למטה להתגלות בבנין המל' דא\"ק רצון לחכמה כו' (כ\"א ע\"י אור חוזר וכמשי\"ת).\n<b>ועתה</b> יובן ענין מאמר הזוהר הנ\"ל בשעתא דאיהי גו רחימו סגיא לגבי רחימה מגו דחיקו דרחימו דלא יכלה למסבל אזעירת גרמה בזעירו דנקודה חדא ומאי איהו יו\"ד, פי' שבראשית המשכת מל' דא\"ק בבחי' כתר דאצילות הכולל ב' פרצופי' ע\"י וא\"א בתחלת התפשטותו בבחי' רצון פשוט לנאצלים בכלל והוא מושלל עדיין מבניינו בבחי' ב\"ן שהוא בחי' חיצוניות הכתר רצון לחכמה כו' הוא ברחימו סגיא לגבי רחימה תשוקת העלול להדבק בעילתו בעצמות אא\"ס ב\"ה שבזה בחי' הרצון אין בה עדיין שום בחי' התחלקות אף בבחי' מקורים ושרשים לפרצופי האצי' כ\"א גילוי אא\"ס הפשוט בתכלית וכו' והי' נכלל הכל בעצמותו ודבוק במקורו תמיד מבלי שיומשך וכו'.\n<b>וזהו</b> אזעירת גרמה בזעירו סגי' עד דלא אתחזיאת מינה אלא זעירו דנקודה חדא שהוא בחי' כתר המל' דא\"ק בחי' כתר שבכתר שהוא זעירו סגי' נקודה חדא קבוץ מהותה להנשא ולהדבק בעילתו בעצמיות כו' בבחי' עומק רום הנ\"ל. ומחמת שנעוץ תחב\"ס ששרש נוק' דזעיר נמשכת מבחי' מל' דא\"ק היא ג\"כ ברחימו סגי' לגבי רחימה שתחלת יציאתה היא מאחורי ז\"א והיתה דבוקה מאחוריו כעלול הדבוק בעילתו, כמשל גילוי המדות כשהם עדיין במציאותם טרם שיתגלו בדיבור שהוא גילוי מופרד במהות בפ\"ע ולזולתו ממש משא\"כ כשגילוי המדות הוא עדיין בחזה הלב הוא עצם א' ממש עם המדות עצמם (כמ\"ש במ\"א על ענין בחי' מלכיות פרטיות דו\"ק דז\"א ובחי' מל' הכללי' מל' דאצי'), כמו\"כ בחי' נוק' דז\"א כשהיתה מאחורי ז\"א היתה עצם א' עמו ממש.\n<b>לכן</b> גם אח\"כ בהפרדה ע\"י הנסירה בכדי לירד ולהיות ראש לשועלים בבי\"ע להחיות בע\"ג ממש לא הי' נמשך כ\"א כתר דידה רצון להתגלות ותו לא והוא בחי' נקודה חדא תחת היסוד דז\"א והוא ג\"כ מחמת שהיא ברחימא סגיא לגבי רחימא להתדבק ולהנשא למעלה שלא ליפרד מז\"א בעלה כ\"א לדבק בעילתה כו' והוא ג\"כ מחמת דחיקו דרחימו דלא יכלה למסבל ולירד בבחי' בנין הנוק' חב\"ד כו' שיתהווה הגילוי בבי\"ע שהוא הפכי ממש, מחמת זה הי' הרצון נכלל תמיד בעצם המדות עליונות מבלי שיתפשט כו' ולא הי' עדיין בחי' חכמה וכו' איך לגלות להתהוות יש ודבר בבי\"ע והוא ג\"כ זעירו דנקודה חדא קבוץ המהות להנשא למעלה כו' כי לא נמשכה כ\"א בחי' כתר לבד כתר מלוכה. ודא איהי יו\"ד, פי' דהנה ידוע שמל' נק' ה\"א, דהנה האותיות הם בחי' כלים להמשכת אורות עליונים והמה כלים מכלים שונים לפי ענין שינויים בציור הכתב ו' בחי' קו ב' ג' קוין כו', והיינו שיש בחי' אותיות וכלים לקבלת אורות הנמשכים מלמעלה בבחי' מ\"ד, ויש בחי' אותיות שהמה"],[2100990286,"בחי' כלים להעלאת המ\"ן מהתחתונים והוא ענין פתיחת האות ופתחו שהחלל שיש בכל אות ואות הוא מורה לבחי' כלי המקבל בתוכה דבר הניתן בו. אמנם הפתח והפתיחה הוא ענין אופן כלי קבלתם אם מלמעלה תהי' הפתיחה יקבל מלמעלה טפת המ\"ד בכדי להשפיע למטה מלמעלה כו'. אמנם אות ה' יש בו ב' הבחי' פתיחה למעלה וגם למטה, והוא ענין שמל' דאצי' נק' ה\"א.\n<b>והענין</b> הוא דהנה נודע שכל בחי' המשכת ההשפעה מאורות הנאצלים למטה בבי\"ע א\"א כ\"א שיתקבצו כולם אל הבריכה העליונה בחי' מלכותו ית' שהוא בחי' גילוי המדות וכמ\"ש במ\"א וכנ\"ל מבחי' הממוצע ובלעדה א\"א בשום אופן שיתהווה דבר נפרד בבי\"ע כו', שלזה היא נק' עשישית דמקבלת כל נהורין. וכמו\"כ לפי שאין טפה עולה מלמעלה שאין טפיים עולות כו' שהוא ענין העלאת המ\"ן מבי\"ע וכמ\"ש בע\"ח מלאכים ונשמות מעלים מ\"ן לרחל שענין העלאת מ\"ן הוא בחי' הכנת המקבל והכשרו לקבל איזה השפעה מלמעלה ממנו. וכמו\"כ בכדי שיתהווה איזה בחי' הארה והמשכת גילוי אלקות בבי\"ע למלאכים ונשמות וכו' בתוס' הארה יתירה שהוא ע\"י בחי' מלכותו ית', מוכרחים הם להעלות מ\"ן בתחלה שהוא ענין הביטול בתחלה לבחי' מל' ית' אזי ע\"י ג\"כ נשפע השפעת המ\"ד, והוא ענין פתיחה מלמעלה שבאות ה\"א מזיגת כלי המל' לקבל כו' ופתיחה מלמטה הוא קבלת המ\"ן העולים מבי\"ע כו'.\n<b>אמנם</b> כל זה הוא כשהיא בבנינה בפרצוף שלם במקומה אזי היא נק' ה\"א כו', אך בשעתא דאיהי ברחימו סגי' לגבי רחימה והיא בבחי' נקודה חדא קבוץ מהותה שאינה נמשך כ\"א בחי' כתר דידה לבדה ודא איהו יו\"ד, וע\"ד אמרת שחורה אני דלית באות דא חוורו בגווי' כשאר אתוון כו', וכמ\"ש שהוא בגשמיות שביו\"ד אין שום פתיחו לא למטה כו', ודא שחורה אני ולית לי רשו לאעלא לכון תחות גדפוי בחי' העלאת מ\"ן כו' ביד\"ך<sup data-n=\"4777\">*14</sup> אפקי\"ד רוח\"י ר\"ת בא\"ר שהוא ענין קבלתה בתוכה מ\"ן העולים מבי\"ע מלאכים ונשמות כו' וכמו\"כ אינה מקבלת מלמעלה ממנה, והוא מחמת זעירו דנקודא חדא כתר מל' לבד בראשית המשכתו בטבע העלול כו' כי נעוץ תחב\"ס כו' עומק רום הנ\"ל בחי' עומק מ\"ה שבכתר, ואיידי דטריד למבלע להנשא למעלה כו' לא הי' יכול להמשך הבנין כו' כ\"א בחי' רצון לבד כו' בחי' יו\"ד. וכמו\"כ למעלה ידוע הוא שאו\"א מעלין מ\"ן לבחי' מל' שבא\"ק והיינו כשהיא בבניינה בבחי' א\"א ב\"ן שבכתר רצונות פרטיי' לפרטי' א\"ס דאצילות הנ\"ל שאזי היא נק' ג\"כ ה\"א ופתיחו מלמעלה לקבל מפנימיותו כו'. אמנם בתחלת האצילות לא נאצל ונמשך כ\"א בחי' רצון פשוט ותו לא בלי התחלקות לרצונות פרטיי' פנימיות הכתר ולא נתפשט עדיין באורך ורוחב, והוא ג\"כ בחי' יו\"ד לבד קבוץ המהות להתעלות למעלה כו' מסיבת התכללותו בעצמיות עדיין כו', והוא ג\"כ מגו דחיקו דרחימו דלא יכול למסבל כו' לירד בבחי' כתרים לי\"ס דאצי' רצונות פרטיי' כו' שהוא היפך פנימיות הנ\"ל אזעירת גרמה בבחי' יו\"ד לבד כנ\"ל ולית לי רשו לאעלא לכון תחות גדפוי בחי' קבלת המ\"ן שאו\"א מעלים כו'.",[["4777","*14","<b>ביד\"ך אפקי\"ד רוח\"י ר\"ת בא\"ר</b>: תהלים לו, ו. ראה פע\"ח שער (טז) ק\"ש שעהמ\"ט פ\"ב. פ\"י. לקמן ע' תרצא."]]],[2100990287,"<b>מה</b> עבדין גברין תקיפין חיילין דילה שאגין כאריין תקיפין כו' ודא גבורי כח עושי דברו מתקנין לה ומהדרין לה כדיוקנא קדמאה כו'. ביאור הענין הוא ע\"פ מ\"ש בע\"ח שיש ב' בחי' פנימי' ומקיפי' דהיינו בחי' אור ישר ואור חוזר. דהנה בחי' או\"פ דאור ישר הוא ד\"מ אור הנפש המאיר בכלי הגוף כו' וכמשל תפיסת איזה שכל עמוק בכח המשכיל במוח המשכיל במשל שלפי ערך כלי השגתו ותפיסתו ככה ממש יתלבש בו השכלה החדשה ולפי שכלו יהולל איש אם הוא בטבעו בעל שכל ומוח תפיסתו בהרחבה וכו' יעמיק ויתפס ביותר כו', אך מה שאינו נתפס בקרבו להעדר הכלי כו' הוא נשאר בבחי' מקיף דהיינו שבכח חכמתו יכול הי' שישיג ביתר כו' רק שלא יצא מההעלם אל הגילוי להתלבש בכלי מוח ההשגה כל עומק המושג כו' הוא מחמת שאינו יכול להתלבש תוך הכלי בבחי' או\"פ והוא להעדר וקטנות הכלי כו' וכו' והראי' שרוב שנים יודיעו חכמה כי טבע מקיף זה לירד ולהמשך למטה כו' כאשר יומזג ויוכשר הכלי לזה כמו\"כ יובן למשכיל למעלה בחי' האצילות הכל הוא בבחי' אורות וכלים והתלבשות האור בהכלי בבחי' פנימי לפי ערך הכלי כו' הוא אור מצומצם לפי סדר ההשתלשלות לבד אמנם עצם האור נשאר מלמעלה בבחי' מקיף כו' וטבע המקיף הוא ג\"כ לירד ולהמשך למטה כו' (והיינו ע\"י העלאת המ\"ן לזה שהוא הכשר ומזיגה כו'). וענין ירידתו בגילוי למטה הוא בלי צמצומים והתעבות כלל עילא ותתא שווים כחשיכה כאורה מאחר שאינו בבחי' אור מצומצם כו', והוא ענין חסד דע\"י אשר על זה נאמר וימינך פשוטה לקבל שבים כי אין העונות תופסים מקום כלל, והוא ג\"כ ענין י\"ג<sup data-n=\"4778\">15</sup> ת\"ד שהם י\"ג מדה\"ר שלזה הם מכונים בשם שערות הזקן, כמו למשל באדם התחתון רוב שנים יודיעו חכמה שהוא ענין התגלות והמשכת המקיף למטה בגילוי בבחי' מוחין דגדלות, וכל מה שנמשך מוחין דגדלות יותר ניכר בשערות כי שערות הם מותרי מוחין כו' והם הוראה על איכות גילוי המוחין והמשכתם מבחי' מקיפים כו' והוא ענין המבואר סבא דעתי' סתים פי' שהסתים שהוא למעלה מן הדעת והוא בבחי' מקיף מתגלה בהם בבחי' דעת וד\"ל.\n<b>והוא</b> ענין איש אשכולות איש שהכל בו זקן<sup data-n=\"4779\">16</sup> שקנה חכמה קנה דוקא פי' ע\"י המשכת המקיף כו', משא\"כ הבחור אף שהוא חריף ומפולפל הוא רק מה שמתלבש בכלי השגתו בבחי' או\"פ שהוא בבחי' המשכה מצומצמת זעיר שם אשר בירידתה להתלבש בהסתר וצמצום כו' הוא מתעבה ומתקצר, משא\"כ בזקן אינו מתלבש בהתגלות והתעבות, ולכן היו הסנהדרין<sup data-n=\"4780\">17</sup> זקנים דוקא תפארת<sup data-n=\"4781\">18</sup> בחורים כוחם והדר זקנים שיבה כו', וכן ראב\"ע<sup data-n=\"4782\">19</sup> כשהרגיש מוחין דגדלות שלו בבחי' זו",[["4778","15","<b>י\"ג ת\"ד שהם י\"ג מדה\"ר</b>: ראה זהר (אדרא רבא) נשא קלא, א. תרומה (ספרא דצניעותא פ\"ת) קעז, א. ע\"ח שער (יג) א\"א פ\"ט."],["4779","16","<b>זקן שקנה חכמה</b>: קידושין לב, ב."],["4780","17","<b>הסנהדרין זקנים</b>: ראה סנהדרין יז, סע\"א. רמב\"ם הל' סנהדרין פ\"ב, ה\"ו. וראה תו\"א בראשית יא, ד. תו\"ח [קה\"ת — תשס\"ג] ש, ג. מאמרי אדה\"א ויקרא ח\"א ע' רמד. נביאים וכתובים ע' תקיט. אמ\"ב שער התפילין קלד. לקו\"ש חי\"ז ע' 138 הערה 59. חכ\"ט ע' 264 הערה 14."],["4781","18","<b>תפארת בחורים כוחם</b>: משלי כ, כט."],["4782","19","<b>ראב\"ע. . הרי אני כבן שבעים שנה</b>: ברכות פ\"א מ\"ה."]]],[2100990288,"נתהדר לו חוורתי ואמר הרי אני כבן שבעים שנה כו' כי ימי<sup data-n=\"4783\">20</sup> שנותינו ע' שנה הוא רק להתגלות בחי' זו דגדלות בהמשכת המקיפים למטה בגילוי ממש, והתחלת הגילוי הוא בכמה בחי' וזמנים שונים מי\"ג שנה וכו' וכן בן<sup data-n=\"4784\">21</sup> עשרים יכול למכור בנכסי אביו כו' עד שיגיע לימי הזקנה הדר זקנים שיבה כנ\"ל, והוא מצד גילוי רצונו ית' המלובש בתורה שהוא מבחי' מקיפים שלמעלה ופי' כמאמרם בים<sup data-n=\"4785\">22</sup> נדמה להם כבחור וכגבור איש מלחמה ובסיני כזקן מלא רחמים כו' וד\"ל. נמצא שענין מקיף דאור ישר הנמשך בשרשו מחסד דע\"י ענינו הוא שמתגלה שרש המקיפים שלמעלה מהאצי' בגילוי ממש בהמשכת י\"ג ת\"ד אשר אין העונות תופסים מקום כלל וכו' וימינך פשוטה לקבל שבים היינו שיורד ונמשך למטה ואינו מתעבה וד\"ל.\n<b>וענין</b> מקיף דאור חוזר המכונים בשם פאת הראש תיקונא דגולגלתא הוא כמשל תפיסת המשכיל בעמקות המושכל לפי איכות רוחב השגתו ומחמת עומק המושג הנתפס ולדקות העיון וההשגה אין כלי המוח שליט להכילו בפנימיות ונבקע ועולה למעלה ראש בעילוי אחר עילוי עד שיעלה ויתעלם למקור ועצם נפש המשכלת אשר היא למעלה מבחי' אור והמשכה כו', ואזי מחמת חזרת האור למעלה תומשך אח\"כ באופן מחודש ויותר מופלג מבתחלה כמ\"ש במ\"א, והוא דוקא מחמת חזרת האור להעדר כלי ההלבשה כו' הוא מתעלה בעילוי אחר עילוי למעלה דוקא, כמשל כח הצומח שכוחו להתעלות למעלה והוא בארץ דוקא מקום היותר נמוך כו', וכמשל דף המעכב מרוצת המים שמסיבת העמדתו הוא חוזר וכו', וכענין הראני את מראייך כמשל הרואה במראה שמתראה לו פרצוף שלו ממש והוא מחמת דבר המסתיר את חוש הראי' שלא ישלוט חוצה מחמת זה חוזרת הראי' איליו, כמו\"כ יובן למעלה שמצד חזרת האור מלמטה למעלה ע\"י בחי' בע\"ת ויצעקו<sup data-n=\"4786\">23</sup> אל ה' כו' הוא מתעלה בעילוי אחר עילוי ונק' אור חוזר לקדמותו ועצמיותו ממש ונק' תיקוני דגולגלתא שערות הראש קדוש יהי' גדל פרע שער ראשו, והוא ענין הכל<sup data-n=\"4787\">24</sup> ירוממך סלה בעילוי אחר עילוי כו'. וזהו פי' עומק רום ועומק תחת שלפי ערך עליתו בעומק רום בבחי' אור חוזר ככה ממש תהי' המשכתו למטה בעומק תחת, כידוע שא\"ס ב\"ה הוא למעלה עד אין קץ ולמטה עד אין תכלית שלפי ערך עלייתו כו' לפי ערך זה ממש יורד בעומק תחת לברר עד אין תכלית. והיינו גבורי כח בחי' גבורה דעתיק ובחי' אור חוזר בחי' עומק רום הנ\"ל עושים דברו בנין דנוק' ה' כמלקדמין כו', ארוממך אלקי המלך בחי' חיצוניות כתר ב\"ן כו' לבחי' עצמיות ע\"י אור חוזר הנ\"ל ואברכה שמך כו', וכן החזירו עטרה ליושנה ע\"י ויצעקו בקול גדול בחי' גבורה אור החוזר לקדמותו וד\"ל.",[["4783","20","<b>ימי שנותינו ע' שנה</b>: תהלים צ, י."],["4784","21","<b>בן עשרים יכול למכור בנכסי אביו</b>: ב\"ב קנו, א. ע\"ח סוף שער כה. לקו\"ת במדבר ב, רע\"א. לעיל ע' תמא."],["4785","22","<b>בים נדמה להם כבחור</b>: ראה מכילתא יתרו כ, ב. בשלח טו, ג. וראה הנסמן במ\"מ ללקו\"ת צו ט, ד."],["4786","23","<b>ויצעקו אל ה'</b>: תהלים קז, ו."],["4787","24","<b>הכל ירוממך סלה</b>: ברכת יוצר לשבת."]]],[2100990289,"<h3>ר\"מ שופטים לא יקום עד א' באיש</h3>\n<b></b><b>ר\"מ שופטים דרע\"ה ע\"א.</b>\n<b>לא</b><sup data-n=\"4788\">1</sup> יקום עד א' באיש<sup data-n=\"4789\">2</sup> לכל עון כו' פקודא דא להעיד עדות ב\"ד כו' ולית סהדותא פחות מתרין כו' בג\"ד אוקמוה מ\"מ<sup data-n=\"4790\">3</sup> מי<sup data-n=\"4791\">*3</sup> מעיד על אדם קורות ביתו כו' ע\"ש. הנה כתי' ויקם<sup data-n=\"4792\">4</sup> עדות ביעקב עדות<sup data-n=\"4793\">5</sup> אותיות דעת וכולא חדא מילתא שבחי' הדעת שבמל' דאצי' כולל חו\"ג יחדיו בהתכללות א' בשיקול הדעת וזהו תרין סהדין שמצטרפין להביא ראי' בב\"ד ולית סהדותא בפחות מתרין היינו בב\"ד של מעלה שתחת מדת מל' דאצי' כו' אשר מלך במשפט יעמיד ארץ שמצטרך להיות ב' עדי' דווקא המה חו\"ג שבדעת הכללי שבמל' הכוללם יחד דהיינו יש דעת נוטה לזכות ויש דעת נוטה לחוב וב' דעות אלו שמטים כלפי חסד וגבו' נכללים בדעת עליון הכוללם יחד בשיקול הדעת וכו' וכפי שיתברר הדבר לאמיתו בשיקול הדעת עליון הכולל ב' דעות אלו להיות מכריע ביניהם כן יקום דוקא כי זהו עיקר השלימות כשמצטרפי' ונכללים ב' בחי' חו\"ג ההפכי' במזיגה והתכללות א' בדעת עליון שבקו האמצעי ואח\"ז כפי שיכריע בניהם כן יקום אבל כשאין בו ב' עדים אלו כלולים כ\"א עד דחסד או דגבורה ולא שניהם במזג השוה אזי כתי' ולא<sup data-n=\"4794\">6</sup> ימות ע\"פ עד אחד דגבורה המחייב כ\"א ע\"פ<sup data-n=\"4795\">7</sup> שני עדים יקום דבר הוא הדבר אשר ציוה הוי' בו ונבראו כמ\"ש בדבר<sup data-n=\"4796\">8</sup> ה' שמים נעשו וברוח פיו כל צבאם שהוא בחי' מדות מל' דאצי' הדיבור עליון שהקיום של הדיבור הוא ע\"י משפט צדק דווקא והוא ב' עדי' דחו\"ג שבדעת הכוללם יחד שעי\"ז דוקא יקום דבר כי מלך<sup data-n=\"4797\">9</sup> במשפט דווקא יעמיד ארץ כו' כנ\"ל ולא יקום ע\"פ עד אחד כו' וד\"ל.\n<b>בג\"ד</b> אוקמוה מארי מתניתין מי מעיד על האדם קורות ביתו ולא עוד אלא אנשי ביתו כו' והן הן ב' עדים שיקום דבר ע\"י קורות ביתו ואנשי ביתו פי' קורות ביתו הוא בחי' העצמות של האדם שנק' קורות כמ\"ש המקרה<sup data-n=\"4798\">10</sup> מים עליותיו דגרמין בנויין על מוחא כו' ופי עצמות הן מן האב כי האב מזריע הלובן שממנו עצמות ואשה מזרעת האודם שממנו הבשר כו' וזהו אנשי ביתו ורמ\"ח אברים של הבשר והקרום על העצמות שהם מלבישים את העצמות כדכתי' עור<sup data-n=\"4799\">11</sup> ובשר תלבישני ובעצמות וגידים תסוככני והעצמות המה הפנימים מכולם שנמשכים מטיפה עצמיות",[["4788","1","<b>לא יקום עד א' באיש</b>: הנחת המהרי\"ל. נעתק מכת\"י 427 כב, ב.\nהנחת כ\"ק אדה\"א (מגוכתי\"ק 1025) (ונעתק בכת\"י 611 לז, א (וחסר הסיום). נדפס בביאוה\"ז שופטים קכא, ד. וראה גם אוה\"ת שופטים ס\"ע תתנב-ג. ביאוה\"ז להצ\"צ שם ע' תתרכט."],["4789","2","<b>לא יקום עד א' באיש</b>: שופטים יט, טו."],["4790","3","<b>מ\"מ</b>: מארי מתניתין."],["4791","*3","<b>מי מעיד על אדם קורות ביתו</b>: ראה תענית יא, א. חגיגה טז, א."],["4792","4","<b>ויקם עדות ביעקב</b>: תהלים עח, ה."],["4793","5","<b>עדות אותיות דעת</b>: ראה ג\"כ סה\"מ תרכ\"ט (הוצאת תשנ\"ב) ע' שנא ואילך. סה\"מ תרל\"ג ח\"א ע' ריד."],["4794","6","<b>ולא ימות ע\"פ עד אחד</b>: שופטים יז, ו."],["4795","7","<b>ע\"פ שני עדים יקום דבר</b>: שם יט, טו."],["4796","8","<b>בדבר ה' שמים נעשו</b>: תהלים לג, ו."],["4797","9","<b>מלך במשפט דווקא יעמיד ארץ</b>: ראה משלי כט, ד."],["4798","10","<b>המקרה מים עליותיו</b>: תהלים קד, ג."],["4799","11","<b>עור ובשר תלבישני</b>: איוב י, א."]]],[2100990290,"של האב שהן עיקר מעמד ומצב וקיום הגוף שעליהם קרום הגידים והבשר והעור כו' וכמ\"כ למעלה החכ' שנמשכה מאבא דאצי' נק' בחי' עצמות חיוורא בחי' לובן כו' ולכן נק' בשם עצמות לשון עצמיות כי נקודת החכ'<sup data-n=\"4800\">12</sup> ראשיתה אצי' הוא שורש ויסוד העצמית בבנין כל הפרצופי' דאצי' ובינה הוא מלביש לחכ' בבחי' לבוש והוא הנק' בשר שנמשך מן האודם שבאשה כי בינה<sup data-n=\"4801\">13</sup> דינין מתערין מינה והוא שורש קו שמאל בג\"ה שמלביש לחכ' מקור החסדי' קו ימין דאצי' בבחי' לבוש והעור היא בחי' מחשבה עליונה בבחי' פרצוף לאה מל' דתבונה שהיא לבוש ללבוש המלבשת את הבשר.\n<b>והנה</b> כתיב עור<sup data-n=\"4802\">14</sup> בעד עור שיש ב' עורות דלאה ודרחל זו על זו עד שפרצוף רחל היא העור החופה על אור הפנימי דלאה נמצא כי כללות הפרצופי' דאצי' שמבינה ואילך המה רק בחי' לבושים להחכ' דאצי' שממנה תבנה ותכונן קומת אדם דאצי' בבשר וגידים ועור החופה על העצמות הפנימים הנמשכי' מן האב מלובן שבטיפה כו'.\n<b>וזהו</b> גרמין בנויין על מוחא כמ\"ש ושיקוי<sup data-n=\"4803\">15</sup> לעצמותיך ששיקוי המוח הוא מתפשט בהעצמות בפנים והם בנויין על מוחא שיש בהן בחי' פנימית וחיצונית כלולים בחב\"ד חג\"ת נה\"י חב\"ד הוא השיקוי הפנימית שבתוך העצמות. וזהו המקרה מלשון קורות ביתו שקרוי מלמעלה וחג\"ת המה חיצונית העצמות שהמה נמשכי' בכל דופני קומת האדם וזהו המקרה לשון קירות ג\"כ שהמה הדפנות שנק' קירות בלשון הכתוב כמו ומראהו<sup data-n=\"4804\">16</sup> שפל מן הקיר, ונה\"י הוא בחי' השפעה שלהם בהגידים ובשר ועור כו' כנודע לחכמי הרפואה ונת' מזה בע\"ח ג\"כ שיש ג' מיני גידים באדם גידי הדם שהדם סובב והולך בהם וגידי הרוח שאין בהם דם רק רוח חיים המתפשט בכל הגוף וגידי ההרגשה שאין בהם אפי' רוח חיים זולתי כח ההרגשה של הדעת במוח המתפשט בעצמות תחילה שכל מה שיכאוב לו אפי' בציפורן רגלו ירגיש תיכף ע\"י גידי הרגשה שמוח הדעת בעצמות ומהם ימשכו ומתפשט אף בבשר כו'.\n<b>וזהו</b> עפ\"י שנים עדים יקום דבר שהמה חו\"ב דאצי' חכמה מקור החסדים ובינה מקור הגבורות עצמות ובשר גרמין בנויין על מוחא ונק' קירות ביתו והבשר שברמ\"ח אברים הלבוש והקרום על העצמות נק' אנשי ביתו והן תרין סהדין שע\"פ ב' עדים דוקא יקום דבר כו' כנ\"ל וד\"ל.",[["4800","12","<b>החכ' ראשיתה אצי'</b>: ראה לקו\"ת ברכה צח, ב. שה\"ש יח, ד."],["4801","13","<b>בינה דינין מתערין מינה</b>: ראה זהר ויקרא י, סע\"ב. יא, רע\"א."],["4802","14","<b>עור בעד עור</b>: איוב ב, ד."],["4803","15","<b>ושיקוי לעצמותיך</b>: משלי ג, ח."],["4804","16","<b>ומראהו שפל מן הקיר</b>: מצורע יד, לז — ומראיהן שפל מן הקיר."]]],[2100990291,"<h3>ולא אבה ה' אלקיך</h3>\n<b>בעזר\"ה שבת פ' כי תצא</b>\n<b>ולא</b><sup data-n=\"4805\">1</sup> אבה ה' אלקיך לשמוע אל בלעם ויהפוך ה' את הקללה לברכה כי אהבך ה' אלקיך<sup data-n=\"4806\">2</sup>. הנה יש להבין מאי רבותא דלא אבה לשמוע אל בלעם וכי בלעם חשוב היה כ\"כ שישמע אליו, ועוד מהו ויהפוך הקללה לברכה מאי קללה איכא הכא עד שאמר שהיפך הקללה לברכה מאחר דלא שמע כלל אל בלעם לקללם וכו'.\n<b>אך</b> הענין יובן בהקדים תחלה כללו' ענין הפסוק בדרך קצרה, כי הנה שרש עובדות דבלעם היה לחפש ולמצוא מקום לקטרג על ישראל ולכך טרח וייגע לעיין בהם בהשגחה עמוקה בדעת שלימה כי הי' בחי' דעת דקליפה וכמ\"ש ע\"ע ויודע<sup data-n=\"4807\">3</sup> דעת עליון, וכל מי שמחפש למצוא קטרוג על ישראל נק' בשם בלעם לפי שבלעם הי' מחפש בכל המקומות אולי ימצא מקום שמשם יוכל לקטרג וכמ\"ש במקומות שחיפש כמו ראש<sup data-n=\"4808\">4</sup> הפעור ונשקפה ע\"פ הישימון שמשם יוכלו לשקוף ולעיין היטב גם ברע הגנוז מאד בטוב וכן וישת<sup data-n=\"4809\">5</sup> אל המדבר פניו כו' שכולן מקומו' שהיו ישראל עתידין שם לחטוא כידוע בדרשו' חז\"ל ולכך נוטלין<sup data-n=\"4810\">6</sup> בר\"ה שופר לתקוע כדי לערבב את המקטרג שבכל דור לחפש ללמוד חובה על ישראל שנק' בלעם כו' וזהו ע\"ד הפשוט בפי' הפסוק דלא אבה לשמוע אל בלעם אע\"פ שמצא קטרוגי' הרבה מצד הטענה אחר שהשגיח ומצא כנ\"ל אעפ\"כ לא אבה לשמוע אל טענתו והטעם דלא אבה לשמוע הוא לפי שהוי' הוא אלקי\"ך וזהו ולא אבה הוי' אלקיך לשמוע ולא אמר ולא אבה ה' סתם אלא דוקא לפי שהוי' הוא אלקיך כו'.\n<b>וביאור</b> הדבר הנה יש להבין פי' שם<sup data-n=\"4811\">7</sup> הוי' שיש בכל נפש מישראל וכמ\"ש כי<sup data-n=\"4812\">8</sup> חלק הוי' עמו וכידוע, והנה בחי' קוצו<sup data-n=\"4813\">9</sup> של יו\"ד הוא בחי' הכתר כידוע",[["4805","1","<b>ולא אבה ה' אלקיך לשמוע אל בלעם</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק 1025 (צח, א).\nמאמר זה באריכות מכ\"ק אדמו\"ר האמצעי נדפס במאמרי אדה\"א תצא ע' תרמב. ובאוה\"ת כי תצא ע' תתקפא (בשינויים קלים).\nהנחת המהרי\"ל נדפס בלקו\"ת תצא לח, ג (וראה שם רשימת הכתבי יד). הגהות וכו' מהצ\"צ נדפס באוה\"ת כי תצא ע' תתקצה.\nלכמה ענינים המבוארים בהמאמר ראה ג\"כ תו\"ח וירא קיז, א.\nהנחת ר' הלל מפאריטש מד\"ה זה לכ\"ק אדמו\"ר הצ\"צ נמצא בכת\"י 942 סו, א. (אחרי מאמרי חורף תר\"ז). 608 רמח, א. (בהמשך למאמרי קיץ תר\"י)."],["4806","2","<b>ולא אבה. . כי אהבך ה' אלקיך</b>: תצא כג, ו."],["4807","3","<b>ויודע דעת עליון</b>: בלק כד, טז. וראה זהר בלק רצד, א. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תתמ ובהנסמן לשם. מאמרי אדה\"א דברים ע' כט וש\"נ. שם ע' לט."],["4808","4","<b>ראש הפעור ונשקפה ע\"פ הישימון</b>: ראה בלק כב, מא. כג, יד. ובמפרשי התורה שם."],["4809","5","<b>וישת אל המדבר פניו</b>: בלק כד, א."],["4810","6","<b>נוטלין בר\"ה שופר לתקוע כדי לערבב את המקטרג</b>: ראה ר\"ה טז, ב."],["4811","7","<b>שם הוי' שיש בכל נפש מישראל</b>: ראה ג\"כ לקו\"ת צו ח, ד. תזריע כב, א. מטות פו, ג. סה\"מ תרכ\"ז ע' שסב."],["4812","8","<b>כי חלק הוי' עמו</b>: האזינו לב, ט. וראה לקו\"ת ראה יח, א."],["4813","9","<b>קוצו של יו\"ד הוא בחי' הכתר</b>: ראה ע\"ח שער הכללים פ\"ב. פרדס שער (כז) האותיות פי\"ג. שערי הקדושה להרח\"ו הובא בלקו\"ת כאן לח, ג ספ\"א."]]],[2100990292,"והיו\"ד<sup data-n=\"4814\">10</sup> הוא בחי' חכמה וה\"א ראשונה בחי' בינה כו' ותחלה יש להבין פי' קוצו של יו\"ד שהוא בחי' עצמיות הרצון שהיא כמו &lt;שלה&gt;\nטבע בנפשותינו ונק' אהבה מסותרת או אהבה טבעית דהיינו האהבה המיוסדת בנפש בבחי' טבעיות שהוא בבחי' הכתר הנק' יחיד\"ה דאין ברצון זה שום טעם ושכל כלל כי הוא הרצון<sup data-n=\"4815\">11</sup> שלמעלה מן הטעם כו' דהיינו שאינו רוצה ליפרד מיחודו ית' בלא טעם וכענין מס\"נ<sup data-n=\"4816\">12</sup> על קדה\"ש שהוא בלא טעם וע\"ז נא' כי נר<sup data-n=\"4817\">13</sup> ה' נשמת אדם כנר<sup data-n=\"4818\">14</sup> הדולק ועולה מאלי' כו' ולפי טבע רצון זה העצמי לא הי' אדם יכול לעבור עבירה כלל ומה שעובר הוא מפני שנכנס<sup data-n=\"4819\">15</sup> בו רוח שטות המטעה את הנפש לומר שבזה אינו נפרד מיחוד האלקי כו' וזהו ג\"כ ענין יראת<sup data-n=\"4820\">16</sup> חטא שקודמת לחכמה כידוע לפי שעי\"ז הוא סור מרע בתכלית גם מאיסור קל של ד\"ס ואדרבה חמורי'<sup data-n=\"4821\">17</sup> עליו דברי סופרים יותר מיינה של תורה (כי יש ג' מדרגו' ספר<sup data-n=\"4822\">18</sup> וסופר וסיפור כמ\"ש בס' יצירה וספר הוא תורה שבכתב וסיפור הוא תורה שבע\"פ והחכמים המדקדקי' דיני התורה בתושב\"פ נק' סופרים כמו הסופר שכותב הספר שהוא למעלה ממנו כך תשבפ\"ע היא גבוה מתשב\"כ כמ\"ש אשת<sup data-n=\"4823\">19</sup> חיל עטרת בעלה כו' וזהו שאמר ערבי' ד\"ס יותר מיינה של תורה וכמ\"ש<sup data-n=\"4824\">20</sup> במ\"א ואין כאן מקומו להאריך).\n<b>וזהו</b> הנרמז בקוצו של יו\"ד<sup data-n=\"4825\">21</sup> דוקא כי הקוץ שעל היו\"ד<sup data-n=\"4826\">22</sup> אינו גם בערך שטח של נקודה אלא רק קוץ ותג בעלמא שהוא כמו לרמז בלבד וסימנא בעלמא והקוץ הזה הוא פונה למעלה כו' כי ע\"י אתעדל\"ת בבחי' אהבה הטבעית הנ\"ל הוא מעורר למעלה ג\"כ בחי' רצון<sup data-n=\"4827\">23</sup> העליון הפשוט שלמעלה מעלה מן בחי' החכמה גם מלהיו'",[["4814","10","<b>והיו\"ד הוא בחי' חכמה</b>: ראה תקו\"ז בהקדמה ו, ב. אגה\"ת פ\"ד."],["4815","11","<b>הרצון. . שלמעלה מן הטעם</b>: ראה של\"ה בית ה' ד, ב בהג\"ה בשם ר' יוסף אלקשטיליא. יונת אלם (לרמ\"ע מפאנו) פ\"ב."],["4816","12","<b>מס\"נ על קדה\"ש שהוא בלא טעם</b>: ראה תניא פי\"ח. ביאורי הזהר תשא נד, ד. תו\"א משפטים עח, ב. מג\"א צט, ב. לקו\"ת תצא לו, א. תו\"ח ויצא קעו, ג."],["4817","13","<b>נר ה' נשמת אדם</b>: משלי כ, כז. וראה תניא רפי\"ט ובליקוט פירושים לשם."],["4818","14","<b>כנר הדולק ועולה מאלי'</b>: ראה פרש\"י ריש פרשה בהעלותך."],["4819","15","<b>שנכנס בו רוח שטות</b>: סוטה ג, א. וראה לקו\"ת כאן לח, ג. שערי תשובה ח\"א שער התשובה ז, ב. ח, ג. תו\"ח תולדות יד, ג."],["4820","16","<b>יראת חטא שקודמת לחכמה</b>: אבות פ\"ג, מ\"ט."],["4821","17","<b>חמורי' עליו דברי סופרים</b>: ראה ע\"ז לה, א וברש\"י שם. וראה שהש\"ר פ\"א, ב (עה\"פ כי טובים דודיך מיין). וראה תו\"א ויחי מז, ב. נב, ד. לקו\"ת מטות פה, א. דרושים לסוכות ושמ\"ע פ, ב. שה\"ש ז, א. ועוד."],["4822","18","<b>ספר. . כמ\"ש בס' יצירה</b>: ראה ס\"י בתחלתו. וראה זח\"ב קלז, ב. ועוד."],["4823","19","<b>אשת חיל עטרת בעלה</b>: משלי יב, ד."],["4824","20","<b>וכמ\"ש במ\"א</b>: ראה לקו\"ת דרושים לסוכות פ, ב. שה\"ש ז, א."],["4825","21","<b>בקוצו של יו\"ד</b>: ראה ג\"כ אגה\"ת פ\"ד. לקו\"ת תצא לט, ב. תו\"ח שמות [הוצאת קה\"ת תשס\"ג] שס, א."],["4826","22","<b>היו\"ד. . בערך שטח של נקודה</b>: ראה גם מאמרי אדה\"ז כתובים ח\"ב ע' רכב. מאמרי תקס\"ז ע' כו."],["4827","23","<b>רצון העליון הפשוט. . בחי' החכמה</b>: ראה יונת אלם פ\"ב. סה\"מ תקס\"ח ח\"א ע' תקכו. אמרי בינה שער הק\"ש פצ\"ט. ועוד."]]],[2100990293,"מקור לחכמה וכמאמר דלית<sup data-n=\"4828\">24</sup> מחשבה תפיס' בי' כו' אפי' מחשבה סתימא' כו' וע\"ד הרצון שבאדם למטה שהוא למעלה מן הטעם לגמרי כנ\"ל שנק' בחי' יחידה כו' וע\"כ הקוץ הזה פונה למעלה להיו' כי אינו אלא בחי' רמז בעלמא ולא גילוי אור במציאת איזה דבר מה כמו החכמה וכיוצא להיותו דבוק בעצמו' המאציל לגמרי וע\"כ הוא פונה למעלה לעצמו' אור א\"ס דכתיב בי' אני<sup data-n=\"4829\">25</sup> ה' לא שניתי כו' וד\"ל.\n<b>וזהו</b> ולא<sup data-n=\"4830\">26</sup> אבה ה' לשמוע אל בלעם כי ע\"י אתעדל\"ת בבחי' קוצו של יו\"ד למטה כנ\"ל נעשה אתעדל\"ע בבחי' הרצון הפשוט הנ\"ל שלמעלה מן הטעם לגמרי הנרמז בקוצו של יו\"ד וע\"כ ממילא ולא אבה לשמוע אל בלעם הגם שבלעם מקטרג בטוב טעם ודעת שלימה כנ\"ל אבל אעפ\"כ אינו חפץ לשמוע לטענתו אחר שרצונו בישראל הוא בבחי' עצמיו' הרצון שלמעלה מן הטעם אין הטעם של הקטרוג עושה בו שינוי התפעלות כלל ואע\"פ שיש לו טענה אין שומעין לו כלל משום דמה שאין שומעי' לו הוא ג\"כ בלא טעם ודעת כו' וזהו ולא אבה לשמוע כו' שלא שמע כלל לטענת בלעם מטעם הנ\"ל וד\"ל.\n<b>ועתה</b> יש להבין בחי' היו\"ד דשם הוי' בנפש כו' דהנה היו\"ד שהוא רק כמו נקודה א' בלבד הנה הוא מורה על בחי' הצמצום לצמצם ולהעלים א\"ע מכל וכל עד שלא נשאר רק כמו נקודה א' בלבד וביאור ענין היו\"ד למעלה היינו בחי' החכמה כנ\"ל שהיו\"ד בחכמה לפי שהחכמה<sup data-n=\"4831\">28</sup> נק' כח מה להיותו בבחי' אין וכמ\"ש בראשית<sup data-n=\"4832\">29</sup> ברא אלקי' שהבריא' בחכמה<sup data-n=\"4833\">30</sup> שנק' ראשית הגילוי מן ההעלם כי נתצמצם העצמו' ולא נשאר בגילוי אור רק כמו נקוד' &lt;שלו&gt;\nא' והוא אור החכמה וע\"כ נאמר שם אלקי' בבריא' דחכמה כמ\"ש בראשית ברא אלקים שהצמצום<sup data-n=\"4834\">27</sup> הוא בשם אלקים<sup data-n=\"4835\">31</sup> בכל מקום כידוע לפי שהחכמה הנה היא באה מן ההעלם דכתר בבחי' צמצום והסתלקו' להעלים העיקר ולהיו' נגלה רק אפס קצהו כמו עד\"מ ברק<sup data-n=\"4836\">32</sup> אור המבריק וכמ\"ש ויצא<sup data-n=\"4837\">33</sup> כברק חצו כו' וכידוע וז\"ש רז\"ל בתחלה<sup data-n=\"4838\">34</sup> עלה במחשבה לברוא במדת הדין שהוא בחי' היו\"ד דחכמה<sup data-n=\"4839\">35</sup> שהוא בחי' הדין והצמצום ואח\"כ שתף עמו מדת הרחמי'",[["4828","24","<b>דלית מחשבה תפיס' בי'</b>: ת\"ז בהקדמה (פתח אלי')."],["4829","25","<b>אני ה' לא שניתי</b>: מלאכי ג, ו."],["4830","26","<b>ולא אבה. . שלמעלה מן הטעם</b>: בלקו\"ת שם מציין: ועיין בשע\"ק להרח\"ו ח\"ג שער א' כי קוצו של יו\"ד כו' ע\"ש. וע\"ש שער ב' ויחידה כו'."],["4831","28","<b>שהחכמה נק' כח מה</b>: זהר בהקדמה א, ב. וראה זהר (רעיא מהימנא) צו כח, א לד, א."],["4832","29","<b>בראשית ברא אלקי'</b>: בראשית א, א."],["4833","30","<b>שהבריאה בחכמה</b>: ראה תרגום ירושלמי בראשית א, א."],["4834","27","<b>יו\"ד. . הצמצום</b>: ולהעיר מע\"ח שער (ז) מטי ולא מטי פ\"א: כי י\"ו הם ב' בחי' התפשטות."],["4835","31","<b>שהצמצום הוא בשם אלקים</b>: שער היחוד והאמונה רפ\"ו."],["4836","32","<b>ברק אור המבריק</b>: ראה לקו\"ת תצא לח, ד."],["4837","33","<b>ויצא כברק חצו</b>: זכרי' ט, יד."],["4838","34","<b>בתחלה עלה במחשבה</b>: ראה רש\"י בראשית א, א. אוה\"ת נצבים ע' א'קפט. לקו\"ש ח\"כ ע' 31 הערה 7."],["4839","35","<b>דחכמה. . הדין והצמצום</b>: ראה ע\"ח שער (יג) א\"א פ\"ו. מבוא שערים ש\"ג ח\"ב פ\"ו. וראה תו\"א ה, ד. ובכ\"מ."]]],[2100990294,"שהוא ההתפשטו' לפי שאם לא בחי' הצמצום אשר הי' בתחלה לא הי' להתהוות העולמו' קיום כלל כי בהגלות נגלות אור האלקי כמו שהוא לא הי' באפשרי להיו' קיום למציאת נברא להיו' בבחי' יש ודבר בפ\"ע כי הי' בטל ממציאותו ונכלל באלקו' כנר הבטל ונכלל בפני האבוקה הגדולה כו' ואע\"פ שגם עכשיו נא' דכולא<sup data-n=\"4840\">36</sup> קמי' כלא חשיב היינו כלא בכף<sup data-n=\"4841\">37</sup> הדמיון ולא לא ממש מפני שכבר נתצמצם אור האלקי ונתעלם בתכלית בכמה מיני צמצומי' והעלמו' שונות בירידו' המדרגו' בהשתלשלו' רבות כידוע אבל אם לא הי' בחי' הצמצום בתחלה הי' כולא לא ממש ולא כלא כי היו חוזרין ונכללי' במקורא דכולא והיו אין ואפס ממש כו' וד\"ל.\n<b>והמופת</b> לדבר זה הנה מצינו כשקטרגו<sup data-n=\"4842\">38</sup> המלאכי' ואמרו מה אנוש וכו' הושיט אצבעו קטנה ביניהן ושרפן הרי כשנתגלה עליהם קצת הארה יתירה יותר מכפי מדת הצמצום אשר עליהם שזהו ענין הושיט אצבעו קטנה כלומר הארה מועטת כבחי' אצבע קטנה עד\"מ יותר מכדי השגתם כו' עי\"ז נשרפו ונתבטלו ממציאותן כמשל הנר הנכלל באבוקה שהרי אמר ושרפן דהיינו שנתבטלו ממש ומכ\"ש בהגלות נגלות אור האלקי כמו שהוא שלא הי' קיום במציאו' כלל לכל ההשתלשלו' של העולמו' כי היו נכללי' ומתבטלי' ממש וע\"כ הוצרך לבחי' הצמצום להעלים ולהסתיר האור בתחלה מכל וכל ולא נשאר רק כנקוד' א' והוא היו\"ד דחכמה.\n<b>וזהו</b> שאנו אומרי' מחדש<sup data-n=\"4843\">39</sup> בכל יום מעשה בראשית פי' בראשית בחכמה שנק' ראשית הגילוי והחידוש הוא בכל יום מחכמה<sup data-n=\"4844\">40</sup> שנק' אין כי מחדש הבריאה בכל יום מאין ליש כו' אך בתחלת הבריאה הי' הצמצום ממילא מעצמו בשביל בריא' יש מאין כו' ואח\"כ תלוי דבר זה במעשה התחתוני' שיגרמו מלמטה בהעלא' מ\"ן דהיינו באתדל\"ת כי רוח<sup data-n=\"4845\">41</sup> אייתי רוח כו' וכמ\"ש אם<sup data-n=\"4846\">42</sup> ישים אליו לבו רוחו ונשמתו אליו יאסוף כו' ועי\"ז מתחדש בכל יום מעשה בראשית דהיינו להיו' בחי' הצמצום ביו\"ד כדי שיהא הבריא' יש מאין כו' וענין אתדל\"ת צריך להיו' ג\"כ ע\"ד בחי' צמצום כדי לעורר למעלה כדוגמתו בחי' הצמצום דיו\"ד הנ\"ל והיינו ע\"י בחי' היו\"ד שבנפש האלקי' באדם דהיינו כשבא לכלל ביטול רצון לבטל א\"ע מכל וכל ולסלק א\"ע ורצונו בכל הדברים בכל שיעור קומה שלו בחב\"ד ומדו' ומחשבה דו\"מ כמו שלא יעמיק חכמתו רק בגדולת ה' ותורתו ועבודתו וכן במחשבה לא לחשוב דבר זר וכו' וכן בדיבור ובמעשה כמו עוצם<sup data-n=\"4847\">43</sup> עיניו מראות ברע וכו' והקדושה",[["4840","36","<b>דכולא קמי' כלא חשיב</b>: ראה זהר בהקדמה יא, ב."],["4841","37","<b>בכף הדמיון</b>: ראה מאמרי אדה\"א תצא שם ע' תרנג."],["4842","38","<b>כשקטרגו המלאכי' ואמרו מה אנוש</b>: סנהדרין לח, ב. וראה לקו\"ת אמור לו, א. דרושים לר\"ה ס, ב."],["4843","39","<b>מחדש בכל יום מעשה בראשית</b>: ע\"ד ברכת יוצר."],["4844","40","<b>מחכמה שנק' אין</b>: ראה זהר בראשית ל, ב. תרומה קסז, א. וראה שערי אורה סג, ב. ובכ\"מ."],["4845","41","<b>רוח אייתי רוח</b>: ראה זהר תרומה קסב ריש ע\"ב. וירא צט ריש ע\"ב. סידור ערב שבת קסג, ד. ועוד."],["4846","42","<b>אם ישים אליו לבו</b>: איוב לד, יד."],["4847","43","<b>עוצם עיניו מראות ברע</b>: ישעי' לג, טו."]]],[2100990295,"במותר לך וכיוצא ולכך אמרו לשון קדש קדש<sup data-n=\"4848\">44</sup> עצמך במותר לך כמו קדש<sup data-n=\"4849\">45</sup> לי כל בכור שהוא לשון קדושה<sup data-n=\"4850\">46</sup> והבדלה להיות שצ\"ל בבחי' ביטול הרצון לסלק נפשו ורצונו מתאוה הגופנית ורק לעשות רצון ה' שזה נק' &lt;שלז&gt;\nקדוש דהיינו בחי' החכמה שנק' קדש כידוע והטעם שנק'<sup data-n=\"4851\">47</sup> חכמה קדש הוא מפני שהיא בחי' אין שהוא קדוש ומובדל בהעלם והסתלקו' כנ\"ל וע\"י אתדל\"ת בבחי' ביטול רצון עד שיהי' רק כנקודא א' זהו בחי' יו\"ד שבנפש שמעורר אתעדל\"ע ג\"כ בחי' יו\"ד שהוא בחי' צמצום והעלם העצמו' ולהיו' נגלה רק כנקודא א' כנ\"ל בענין ביטול הרצון ולא אבה למעלה מן הטעם כו' וז\"ש ישת<sup data-n=\"4852\">48</sup> חושך סתרו להעלים ולהסתיר א\"ע בחושך והעלם כדי שיהא הבריא' בבחי' יש מאין כנ\"ל והיינו ג\"כ בחי' יו\"ד<sup data-n=\"4853\">49</sup> שנק' חושך כי הנקודה שחורה היא בבחי' ההעלם וכמ\"ש<sup data-n=\"4854\">50</sup> במ\"א ע\"פ שחורה אני ונאוה כו' וזהו ה'<sup data-n=\"4855\">51</sup> מלך גיאו' לבש פי' שכאשר עלה ברצון המאציל להיו' מלך על עם והרי אין דבר נפרד מאתו ע\"כ הוצרך להתצמצם ולהתעלם בלבוש גיאו' שמכסה ומעלים א\"ע מכל וכל ולא יגלה רק כמו נקודא א' ואזי אף תיכון תבל כו' שנתהוו' יש מאין תבל ומלואו וד\"ל.\n<b>וזהו</b> ולא אבה הוי' אלקיך לשמוע אל בלעם כו' פי' לפי שהוי' הוא אלקיך ע\"כ ולא אבה, והנה היו\"ד דשם הוי' נתבאר למעלה וענין הה\"א הוא בחי' ההתפשטות לאורך ורוחב והוא בחי' בינה שע\"י ההתבוננו' נעשה התפעלות ברשפי אש בהתפשטו' כו' וההתבוננו' היא ממה שהוא ית' ממלא כ\"ע וסובב כ\"ע כידוע שזהו ג\"כ בבחי' ההתפשטו' לאורך ורוחב היפך בחי' הצמצום הנ\"ל והנה בחי' ה\"א הזאת היא בתשובה עילא' מעומקא דלבא כמ\"ש ויצעקו<sup data-n=\"4856\">52</sup> אל ה' בצר להם ופי' בצר להם היינו לפי שמחמת ההשגה איך שהוא סובב וממלא וכולא קמי' כלא כו' נעשה הכל צר לו כי גם חיי העוה\"ב צר לו כמ\"ש מי<sup data-n=\"4857\">53</sup> לי בשמים ועמך לא חפצתי כו' אחר דכולא קמי' כלא וצועק בצעקה לצאת מן המיצר הזה אלא ליכלל ולידבק במהותו ועצמותו ית' דוקא ולא בצמצום האור האלקי שמתפשט להיות בממלא וסובב כו' וד\"ל.",[["4848","44","<b>קדש עצמך במותר לך</b>: ראה ספרי ראה יד, כא. יבמות כ, א. לקו\"ש חי\"ט ע' 403."],["4849","45","<b>קדש לי כל בכור</b>: בא יג, ב."],["4850","46","<b>קדושה והבדלה</b>: ראה תו\"כ ורש\"י ר\"פ קדושים. תניא כמצויין במפתח ענינים מערכת קדושה."],["4851","47","<b>שנק' חכמה קדש</b>: מא\"א בערכו. ראה מאמרי אדה\"א תצא שם — שנק' קדוש כמ\"ש והחכמה מאין תמצא כו' וז\"ש קודש ישראל להוי' ראשית תבואתו."],["4852","48","<b>ישת חושך סתרו</b>: תהלים יח, יב."],["4853","49","<b>יו\"ד שנק' חושך</b>: ראה זוהר בלק קצא, א. ע\"פ שחורה אני."],["4854","50","<b>כמ\"ש במ\"א ע\"פ שחורה אני</b>: ראה ביאוה\"ז בלק ק, א. שה\"ש א, ה. וראה זוהר בלק קצא, א. וראה לקו\"ת שה\"ש ז, א."],["4855","51","<b>ה' מלך גיאות לבש</b>: תהלים צג, א. וראה מאמרי אדה\"א ויקרא ח\"ב ע' תקה. וראה גם שער האמונה פי\"ט. פירוש המלות פט, ג."],["4856","52","<b>ויצעקו אל ה' בצר להם</b>: תהלים קז, ו. כח."],["4857","53","<b>מי לי בשמים ועמך לא חפצתי</b>: תהלים עג, כה."]]],[2100990296,"<b>ועל</b> קוטב זה הוסד גם יסוד סדר התפלה שיתבונן בגדולת ה' בתחלה איך שאין<sup data-n=\"4858\">54</sup> חקר כלל לגדולתו ואח\"כ יתפעל באהבה בק\"ש באמרו ואהבת<sup data-n=\"4859\">55</sup> כו' כי התשובה והתפלה שרש א' להם הכל בבחי' ה\"א עילא' דשם הוי' וכמאמר דבינה<sup data-n=\"4860\">56</sup> לבא<sup data-n=\"4861\">57</sup> כו' וזהו שאנו אומרי' והחזירנו<sup data-n=\"4862\">58</sup> בתשובה שלימה לפניך כי ע\"י תשובה בא האדם לפני ה' ממש שיאיר בו ה' בבחי' הפנימי' וכמ\"ש יאר<sup data-n=\"4863\">59</sup> ה' פניו כו' וד\"ל.\n<b>והנה</b> ע\"י אתעדל\"ת<sup data-n=\"4864\">60</sup> נעשה אתעדל\"ע בה\"א דשם הוי' להיו' למעלה בחי' התפשטו' ג\"כ בממלא וסובב כו' אך הנה כל זה הוא למעלה ברוחניות עדיין אבל כדי להיות גילוי התפשטו' אור זה גם למטה בעוה\"ז השפל הוא ע\"י בחי' וי\"ו ה\"א שבאתעדל\"ת בתורה ומצות שהן בחי' ו\"ה שבשם הוי' כי הנה התורה הוא בחי' וי\"ו כו' כי הוי\"ו<sup data-n=\"4865\">61</sup> הוא בחי' ההמשכה ובקול דתורה יש ג\"כ בחי' המשכה מן החכמה וכמ\"ש קול<sup data-n=\"4866\">62</sup> קורא במדבר פי' קול דתורה קורא וממשיך בחי' קדש העליון דחכמה גם במדבר בעוה\"ז החומרי כמ\"ש בארץ<sup data-n=\"4867\">63</sup> ציה כו' כן בקדש חזיתיך דהיינו מן החכמה שנק' קדש נמשך למטה בגילוי ע\"י קול דתורה כמו שהוא למעלה וכמארז\"ל שהקדב\"ה<sup data-n=\"4868\">64</sup> יושב ושונה כנגדו כו' וד\"ל.\n<b>והה\"א</b> האחרונה הוא בחי' מעשה<sup data-n=\"4869\">65</sup> המצות &lt;שלח&gt;\nשכללותם נק' בשם צדקה וכמ\"ש והיה<sup data-n=\"4870\">66</sup> מעשה הצדקה שלום לפי שכללו' ענין המצות הוא להיו' גילוי אלקו' באה למטה בבחי' כלי דוקא וכמו הצדקה שהיא להחיות<sup data-n=\"4871\">67</sup> רוח שפלים כו' והיינו פי' צדקה<sup data-n=\"4872\">68</sup> צדק ה\"א כי צדק<sup data-n=\"4873\">69</sup> דינא דמלכותא כו' והה\"א היינו בחי' ה' החסדים הנמשכי' בה ע\"י רמ\"ח מ\"ע ששרשם בחי' ה' חסדי' בכלל וזהו צדק<sup data-n=\"4874\">70</sup> מלאה ימינך ימין העליון שהוא החסד נתמלאה בצדק<sup data-n=\"4875\">71</sup> דאיהו דין דמלכו' ואזי נק' צדקה<sup data-n=\"4876\">72</sup>",[["4858","54","<b>שאין חקר כלל לגדולתו</b>: לשון הכתוב תהלים קמה, ג — ולגדולתו אין חקר."],["4859","55","<b>ואהבת</b>: ואתחנן ו, ה."],["4860","56","<b>התשובה. . ה' עילאה. . דבינה</b>: אגרת התשובה פ\"ח ופ\"ט. ובליקוט פירושים שם."],["4861","57","<b>דבינה לבא</b>: ראה תקו\"ז בהקדמה יז, א."],["4862","58","<b>והחזירנו בתשובה שלימה</b>: תפלת שמו\"ע."],["4863","59","<b>יאר ה' פניו</b>: נשא ו, כה."],["4864","60","<b>אתעדל\"ת נעשה אתעדל\"ע</b>: ראה זהר לך פח, א. ויצא קסד, א. ויחי רלה, א. רמד, א."],["4865","61","<b>הוי\"ו הוא בחי' ההמשכה</b>: ראה אגה\"ת פ\"ד."],["4866","62","<b>קול קורא במדבר</b>: ישעי' מ, ג."],["4867","63","<b>בארץ ציה</b>: תהלים סג, ב."],["4868","64","<b>שהקב\"ה יושב ושונה כנגדו</b>: ראה תנא דבי אליהו רבא רפי\"ח. ילקוט שמעוני איכה ב, יט (רמז תתרלד)."],["4869","65","<b>מעשה המצות שכללותם נק' בשם צדקה</b>: ראה ב\"ב ט, א."],["4870","66","<b>והיה מעשה הצדקה שלום</b>: ישעי' לב, יז."],["4871","67","<b>להחיות רוח שפלים</b>: שם נז, טו."],["4872","68","<b>צדקה צדק ה\"א</b>: ראה זהר אחרי עב, א. וראה מאמרי אדה\"א דברים ח\"ב ע' שצד, וש\"נ. ח\"ג ע' תתעב, וש\"נ."],["4873","69","<b>צדק דינא דמלכותא</b>: ראה תקו\"ז בהקדמה יז, ב."],["4874","70","<b>צדק מלאה ימינך</b>: תהלים מח, יא. וראה סידור שער החנוכה רעח, ג-ד."],["4875","71","<b>בצדק דאיהו דין</b>: ראה סידור שם: כמ\"ש בר\"מ לאו דאית לך צדק דאיהו דין. ראה תיקוני זהר בהקדמה יז, ב. זהר קדושים פה, ב. פ, ב."],["4876","72","<b>צדקה בתוס' ה\"א</b>: בלקו\"ת שם: (וע' בזהר פ' בחקתי דקי\"ג ע\"ב ובפ' הרמ\"ז שם ובאדר\"ז דרצ\"א סע\"ב ודרצ\"ב ע\"א)."]]],[2100990297,"בתוס' ה\"א כי כדי להיות נגלה כבוד ה' למטה בכלים מכלים שונים במצות מעשיות הוא בחי' החסדי' דוקא ולכך נק' המצו' צדקה והיינו ה\"א אחרונ' דשם הוי' וד\"ל.\n<b>ויהפוך</b> ה' את הקללה לברכה כי אהבך ה' אלקיך. פי' היפוך הקללה לברכה היינו היפוך הזדונות כזכיות כי הקללה באה על העוונות והחטאי' והברכה באה על קיום המצות והיפוך הקללה לברכה דהיינו שהקללה עצמה נעשית ברכה זהו א\"א כ\"א כאשר הזדונות<sup data-n=\"4877\">73</sup> עצמן נעשו זכיות ממש ורבותא קא' בזה דמלבד שלא שמע אל בלעם לקללם אלא ההיפוך עשה שבקללה רב טוב וחסד יהי' דהיינו כשהיפך הקללה לברכה כו' והנה אין היפוך הזדונות להיו' כזכיות אלא ע\"י התשובה דוקא מעומקא דלבא הנק' תשובה עילא' והוא כמו תשובת<sup data-n=\"4878\">74</sup> ר\"א בן דורדיא שיצאה נשמתו בתשובה מעומק הלב ולכך בכה רבה\"ק ואמר יש קונה עולמו בשעה אחת דאע\"פ שלא עשה מצות מ\"מ קנה חיי העוה\"ב בשעה זו לפי שמבואר בזוהר<sup data-n=\"4879\">75</sup> דבעלי תשובה משכי' לי' לקדב\"ה בחילא יתיר כו' דהיינו למעלה מן הדעת והטעם אלא ברצון העצמי מעומקא דלבא שנק' חילא יתיר ורוח אייתי רוח ואמשיך רוח כידוע ע\"כ עי\"ז נעשה למעלה אתעדל\"ע ג\"כ בחילא יתיר והיינו מבחי' רצון<sup data-n=\"4880\">76</sup> הפשוט הנק' רעוא דכל רעוין והוא המהפך זדונו' להיו' כזכיות ממש וזהו הטעם שבנעילה<sup data-n=\"4881\">77</sup> דיו\"כ מתגלה בחי' רעוא דכל רעוין לפי שבעי\"ת<sup data-n=\"4882\">78</sup> הי' בחי' תשובה עילא' מעומקא דלבא באמרם ממעמקי'<sup data-n=\"4883\">79</sup> קראתיך הוי' בכל יום בעי\"ת<sup data-n=\"4884\">*79</sup> כו' ויש עשרה<sup data-n=\"4885\">80</sup> עומקי' כמ\"ש בס\"י ובכל<sup data-n=\"4886\">*80</sup> יום ממשיכי' עומק אחד ממקור כל העומקי' וכמ\"ש ממעמקי' עומקא דעומקא כו' והיינו קראתיך הוי' מחדש כו' ודרך כלל הי' עומקי' הן ז' מדו' וג' שכליים חב\"ד נגד י' ספי' דאצי' ולהמשיך להן בחי' י' כתרים הנק' עומקי' הרי בהכרח שיומשך ממקורא דכולא דהיינו מבחי' כתר שבכתר ששם בחי' רעוא דכל",[["4877","73","<b>הזדונות עצמן נעשו זכיות</b>: ראה יומא פו, ב."],["4878","74","<b>תשובת ר\"א בן דורדיא</b>: ע\"ז יז, א. וראה סה\"מ תרמ\"ו (קה\"ת תשמ\"ז) ע' יט: ואפ\"ל שאין הכוונה שיצא נשמתו בפו\"מ. וע\"ש."],["4879","75","<b>בזהר. . בחילא יתיר</b>: ראה זהר חיי שרה קכט, ב. אגה\"ת ספ\"ח."],["4880","76","<b>רצון הפשוט הנק' רעוא דכל רעוין</b>: ראה זהר (ספרא דצניעותא) תרומה קעו, ב. תו\"ח בראשית לו, ג ובהערה 1. וראה ג\"כ תו\"א קי, א. שערי תשובה קל, א."],["4881","77","<b>שבנעילה דיו\"כ מתגלה בחי' רעוא דכל רעוין</b>: ראה פע\"ח (שער יוהכ\"פ) שער כז, פ\"ה."],["4882","78","<b>שבעי\"ת הי' בחי' תשובה עילאה</b>: ראה אוה\"ת דרושים לר\"ה ע' ב'צט: דהנה מבואר בזו\"ה ובפע\"ח דבעשי\"ת הוא בחי' תשו\"ע דוקא, אמנם ב' מדריגות יש בב\"ח תשו\"ע הא' בבחי' בינה והב' הוא יותר גבוה ממנה עד שתשו' בבחי' בינה לא נק' רק בחי' תשו\"ת, ע\"ש. וכן הוא גם בסה\"מ תרכ\"ט ע' שלג: שנת' בזהר ובפע\"ח דבעי\"ת הוא בחי' תשובה עילאה דוקא. וראה שם ע' שלח."],["4883","79","<b>ממעמקי' קראתיך הוי'</b>: תהלים קל, א."],["4884","*79","<b>באמרם ממעמקים קראתיך. . בעי\"ת</b>: כתבי האריז\"ל הובא במג\"א הל' ברכות סנ\"ד סק\"ב. ראה סידור אדה\"ז בסיום פסוקי דזמרה לפני (שיר המעלות) ברכו."],["4885","80","<b>עשרה עומקים כמ\"ש בס\"י</b>: סוף ש' תפלת ר\"ה בפע\"ח. וראה סה\"מ תקס\"ח ח\"ב ע' תתקז. לקו\"ת נצבים מח, ב."],["4886","*80","<b>ובכל יום ממשיכים עומק אחד. . וכמ\"ש ממעמקים עומקא דעומקא</b>: פע\"ח סוף שער תפלת ר\"ה. וראה ד\"ה להבין כללות ענין עשרה עומקים מליל שבת שובה תקס\"ו (הנחת אדמו\"ר האמצעי נדפס בסה\"מ תרכ\"ו (הוצאה חדשה) ע' רלד. והנחת ר' משה בן אדה\"ז נדפס בסה\"מ תקס\"ה ע' תתצז). הגהת כ\"ק אדמו\"ר הצ\"צ בלקו\"ת נצבים מח, ד."]]],[2100990298,"רעוין והוא המתגלה בנעילה דיו\"כ למטה ובעי\"ת מעוררי' אותו ע\"י התשובה מעומקא דלבא מטעם דמשכי' לי' בחילא יתיר כנ\"ל ובהגלות נגלות אותו הרצון הפשוט ביו\"כ אזי נהפכו הזדונו' כזכיו' וכמ\"ש אנכי<sup data-n=\"4887\">81</sup> אנכי מוחה פשעיך ומלבד שמוחל וסולח העונות הנה הוא מהפכם מקללה לברכה דוקא כי נתהפך הרע לטוב ממש כי שם לא<sup data-n=\"4888\">82</sup> יגורך רע ואין<sup data-n=\"4889\">83</sup> רע יורד מלמעלה כו' וזהו לפני<sup data-n=\"4890\">84</sup> הוי' תטהרו למעלה משם הוי' כי ביו\"כ נמשך שם הוי' מחדש בכל הי\"ס דאצי' ע\"י המשכת הי' עומקי' וכמ\"ש ממעמקי' קראתיך הוי' כו' וכנ\"ל וד\"ל.\n<b>וזהו</b> ויהפוך ה' את הקללה לברכה אחר שהוי' נעשה אלקיך ולא אבה לשמוע אל בלעם שהוא בבחי' הדעת הנה עוד זאת אהבה וחיבה יתירה נודעת לך &lt;שלט&gt;\nלהפוך הקללה לברכה להפוך הזדונו' כזכיו' וזהו כי אהבך ה' אלקיך פי' אהבך אהבה יתירה בבחי' עצמיו' הרצון כנ\"ל והוא ע\"י התשובה משום דמשכי' לי' בחילא יתיר כנ\"ל וד\"ל.",[["4887","81","<b>אנכי אנכי מוחה פשעיך</b>: ישעי' מג, כה."],["4888","82","<b>כי לא יגורך רע</b>: תהלים ה, ה."],["4889","83","<b>ואין רע יורד מלמעלה</b>: ראה של\"ה סח, א. קו, ב. שעח, א. אגה\"ק ס\"א. ראה ב\"ר פנ\"א, ג. מדרש תהלים סקמ\"ט."],["4890","84","<b>לפני הוי' תטהרו</b>: אחרי טז, ל."]]],[2100990299,"<h3>להבין שרשי הדברים</h3>\n<b>בעזר\"ה</b>\n<b>להבין</b><sup data-n=\"4891\">1</sup> שרשי הדברים הנ\"ל. הנה שרש ענין קוצו<sup data-n=\"4892\">2</sup> של יו\"ד הוא בבחי' הכתר כידוע ובחי' היו\"ד הוא בחכמ' ולהבין מה שקוצו<sup data-n=\"4893\">3</sup> של יו\"ד אינו אלא כמו רמז בעלמא כמבואר למעלה הענין הוא לפי שבחי' הכתר מקבל מבחי' מל' דא\"ס כידוע ובבחי' מל' דא\"ס אמרו דלית מחשבה תפיס' בי' כלל כי הוא בבחי' הא\"ס כמו עצמו' דא\"ס כמארז\"ל קודם<sup data-n=\"4894\">4</sup> שנברא העולם הי' הוא ושמו בלבד וכו' שאינו נתפס בגדר השגה ותפיס' כלל אך אע\"פ שבמחשבה אינו נתפס מ\"מ בנקודת רצון הפנימי שבלב הנק' אהבה טבעית שאינה מצד השגה ותפיס' כלל כי אע\"פ שאיננו יודע",[["4891","1","<b>להבין שרשי הדברים הנ\"ל</b>: הנחת כ\"ק אדה\"א. נעתק מגוכתי\"ק 1025 (צט, ב).\nהביאור בשינויים והגהות מהצ\"צ נדפס באוה\"ת כי תצא ע' תתר ואילך. וקיצורים והוספות בכרך ו ע' ב' שסח ואילך.\nהנחת המהרי\"ל נדפס בלקו\"ת תצא לט, ב. [וראה שם ברשימת הכתבי יד]. וסיום להביאור באוה\"ת כי תצא כרך ו ע' ב'שסז."],["4892","2","<b>קוצו של יו\"ד הוא בבחי' הכתר</b>: ראה ע\"ח שער הכללים פ\"ב. פרדס שער (כז) האותיות פי\"ד. שערי הקדושה להרח\"ו הובא בלקו\"ת כאן לח, ג ספ\"א."],["4893","3","<b>שקוצו של יו\"ד אינו אלא כמו רמז בעלמא</b>: ראה אוה\"ת תצא שם ע' תתר. ובארוכה ד\"ה אורח חיים תרס\"ט. לקו\"ש חי\"ט ע' 420 הערה 21. ליקוט פירושים ומ\"מ — חיטריק לאגה\"ת פ\"ד."],["4894","4","<b>קודם שנברא העולם הי' הוא ושמו בלבד</b>: ראה לעיל (ח\"א) ע' ו ובהנסמן שם."]]],[2100990300,"ומשיג עצמיו' ומהו' אור הא\"ס הוא נמשך מצד בחי' עצמיו' הרצון כנ\"ל הנה בנקודה זו הוא נתפס דוקא לפי שהוא למעלה מבחי' מחשבה ותפיס' וזהו בחי' קוצו של יו\"ד שאינו אלא כמו רמז בעלמא בלי שום תפיס' והשגה ופונה למעלה דהיינו לבחי' מל' דא\"ס שנעשה בחי' כתר לאבי\"ע כידוע וד\"ל, והיו\"ד הוא בבחי' החכמה<sup data-n=\"4895\">5</sup> שנק' ראשית הגילוי מן ההעלם וכמ\"ש והחכמה<sup data-n=\"4896\">6</sup> מאין תמצא כנ\"ל.\n<b>וביאור</b> הדברים הנה ידוע דהחכמה<sup data-n=\"4897\">7</sup> נק' נקודא בהיכלא והיינו נקודת אבא בהיכל הבינה כי בחי' הבינה הוא בחי' ההשגה לאורך ורוחב דוקא אבל החכמה<sup data-n=\"4898\">8</sup> נק' כח מה כלומר מה פשפשת כו' כי אינו אלא כח השכלת השכל שלמעלה עדיין מבחי' השגה ממש כידוע וע\"כ אינו אלא כמו בחי' נקודא א' בלבד כידוע, והנה התהוות אור החכמה דאצי' הוא בא בבחי' צמצום גדול וזהו שגילוי אור החכמה בתחלת התהוותה מההעלם הוא רק בבחי' נקודא א' בלבד עד\"מ כח החכמה באדם התחתון שהוא בא במוח כמו ברק המבריק בהארה פתאומי' להיותה באה בבחי' הצמצום מההעלם שלמעלה מן השכל כי להיות בחי' מציאת חכמה מלמעלה מן החכמה א\"א כ\"א ע\"י צמצום לצמצם ולהעלים ולהיות נגלה מן ההעלם רק כמו ברק המבריק בלבד דהיינו כמו נקודא א' והטעם הוא כי בחי' החכמה דאצי' הנה היא באה בהשתלשלות רבות מאד עד שנמצא מכחה למטה מטה כמו בעולם העשי' מציאת שכל אנושי ממש רק שבא ע\"י צמצומי' רבים באצי' ומאצי' לבריא' בהשגו' הנשמו' ומלאכי' ומבריא' ליצי' כו' עד חכמה שבמל' דמל' דעשי' אבל למעלה מן האצי' דהיינו בעצמו' המאציל ממש אין שם גם לא מבחי' ערך מציא' ומהו' חכמה כלל וכמאמר חכים<sup data-n=\"4899\">9</sup> ולא בחכמה ידיעא כו' וע\"כ א\"א שיבא מציא' &lt;שמ&gt;\nחכמה גם חכמה דאצי' מן המאציל עצמו רק ע\"י צמצום גדול והוא מה שתתגלה רק בבחי' נקודא א' בלבד וד\"ל ואפי' בחי' חכמה סתימא' דא\"א שנק' בלשון<sup data-n=\"4900\">10</sup> הגאונים בשם שכל הנעלם מכל רעיון (ובכלל נק' שכל הנעלם הזה כללו' בחי' הכתר אך בפרט הוא בחי' ח\"ס דא\"א) גם הוא בא בבחי' הצמצום מעצמו' המאציל כי הנה ידוע דבחי' גבורה דע\"י הוא מלובש בח\"ס כמ\"ש<sup data-n=\"4901\">11</sup> בע\"ח ובחי' גבורה דע\"י היינו בחי' הצמצום והדין להעלים א\"ע בתחלה בכדי שימצא מציא' שכל הנעלם הזה כי גם הוא בכלל בחי' חכמה יחשב ואע\"פ שאינו בחי' חכמה ממש מ\"מ הוא נק' מקור דמקור לחכמה כידוע וא\"כ כדי שיהא בחי' גילוי אור שכל זה הנעלם ג\"כ צריך להיו' ע\"י צמצום",[["4895","5","<b>החכמה שנק' ראשית הגילוי</b>: נסמן לעיל ע' תרסה."],["4896","6","<b>והחכמה מאין תמצא</b>: איוב כח, יב."],["4897","7","<b>דהחכמה נק' נקודא בהיכלא</b>: ראה זהר בהקדמה ו, א."],["4898","8","<b>החכמה נק' כח מה</b>: ראה זהר (רעיא מהימנא) צו כח, א. לד, א."],["4899","9","<b>חכים ולא בחכמה ידיעא</b>: ת\"ז בהקדמא (פתח אלי')."],["4900","10","<b>בלשון הגאונים בשם שכל הנעלם מכל רעיון</b>: מובא בכ\"מ בדא\"ח בשם: רע\"מ, פרדס, לשון הגאונים. ובפזמון לסעודה ג' של שבת ד\"ה אל מסתתר לתלמיד הרמ\"ק. וראה תו\"א ר\"פ לך. תו\"ח לך פ, א. מאמרי אדה\"א בראשית ע' ח. ויקרא ח\"ב ע' תרכב. דברים ח\"ד ע' א'ריא. וראה סה\"מ תרפ\"ט ע' 66: ובלשון הגאונים נק' שכל מופלא."],["4901","11","<b>כמ\"ש בע\"ח</b>: ראה ע\"ח (שער א\"א) שי\"ג, פ\"ו-ז."]]],[2100990301,"שהוא בחי' גבורה דע\"י וגם השכל הנעלם הזה כשמאיר ובא למטה להיות מקור לבחי' אור אבא דאצי' הנ\"ל ג\"כ הוא מאיר ע\"י בחי' צמצום כנ\"ל והיינו ענין בחי' השערו'<sup data-n=\"4902\">12</sup> שנמשכין ממותרי המוחין שמבחי' ח\"ס דא\"א בי\"ג תקונין בכלל וכמאמר הידוע דאור<sup data-n=\"4903\">13</sup> אבא יונק ממזל השמיני דונוצר חסד כו' וד\"ל.\n<b>וזהו</b> של\"ב נתיבו' חכמה הם בשמו' דאלקים שהוא בחי' הצמצום כידוע שהרי ידוע דל\"ב<sup data-n=\"4904\">14</sup> ויאמר אלקי' דעובדא דבראשית הן המה ל\"ב נתיבות דחכמה ופי' נתיב הוא שביל קצר ומצומצם מטעם הנ\"ל משום דהחכמה נאצלה רק בבחי' נקודא א' בלבד מן ההעלם וע\"כ נק' ל\"ב נתיבות ויש בזה ב' פרושי' הא' נתיב שנמשך בחכמה דהיינו בתחלת התהוות' מח\"ס או בחי' ח\"ס מעצמו' המאציל או הפי' בנתיבות דחכמה היינו מחכמה דאצי' שמתפתח לל\"ב חלקי' אבל בח\"ס עצמו אין בה עדיין ההתחלקו' לל\"ב כי נק' מוחא דסתים דלא שכיח ולא אתפתח כמבואר<sup data-n=\"4905\">15</sup> באד\"ר אבל מ\"מ יהי' איך שיהי' נתיבו' דחכמה הוא בבחי' אלקים דוקא המצמצם מטעם הנ\"ל וד\"ל.\n<b>אך</b> בענין בחי' השערו' שנמשכין מח\"ס כנ\"ל יש להבין למה דוקא ע\"י צמצום דבחי' שערות דוקא אבל הענין הוא כי לפי שהשערו' הן דבר נבדל מן הגוף כידוע שלא יתפעל האדם בקציצת שערה אבל מ\"מ קצת<sup data-n=\"4906\">16</sup> יניק' יש בחללן וכמ\"ש במ\"א וגם זה הוא צומח ובא מבחי' מותרי המוחי' כנ\"ל, והנה צמיחה זו עוברת דרך הגלגלתא המעלמת המוחין שבתוכה לבלתי יתגלו חוצה וז\"ש ה'<sup data-n=\"4907\">17</sup> מלך גיאו' לבש וכן מ\"ש ישת<sup data-n=\"4908\">18</sup> חושך סתרו דהיינו העלם דגלגלתא ואחר העלם זה בוקעין ועוברין בחי' השערו' מח\"ס כנ\"ל וכל זה משום דאין ערוך כלל וכלל בין עצמו' המאציל לנאצלים ע\"כ א\"א שיבא אור מציאו' נגלית באצי' כ\"א ע\"י צמצום דשערו' שהוא בא בבחי' דילוג גדול משום דלעוצם הרוממו' כולא קמי' כלא ממש עד שלא יתפס אור שפעו למטה כ\"א בדבר נבדל וחיצוני בלבד כמו בחי' השערו' כו' משא\"כ מחכמה לבינה ומבינה למדו' וכיוצא האור והשפע באה מעילה לעילה כשאר סדרי ההשתלשלות משום דיש להן יחוס וערך קצת זע\"ז כמ\"ש במ\"א וד\"ל.\n<b>ואחר</b> שנתבאר ענין קוצו של יו\"ד וענין היו\"ד יובן ג\"כ איך שנעשין למעלה ע\"י אתעדל\"ת כנ\"ל כי הנה יש בנפש האדם ב' מדרגות בבחי' הביטול הא' ביטול הרצון למעלה מן הטעם ודעת והוא בחי' אהבה טבעית הנ\"ל שאינו חפץ מצד בחי' עצמיו' ליפרד מיחוד אלקו' והוא בחי' קוצו של יו\"ד כנ\"ל ואתעדל\"ת זו גורמת\n&lt;שמא&gt;",[["4902","12","<b>השערו' שנמשכין ממותרי המוחין</b>: נסמן לעיל ע' תקעו."],["4903","13","<b>דאור אבא יונק ממזל השמיני</b>: ראה זח\"ג רפט, ב. ובכ\"מ."],["4904","14","<b>דל\"ב ויאמר אלקים ל\"ב. . נתיבות דחכמה</b>: הובא בפרדס להרמ\"ק ז\"ל שער הנתיבות רפ\"ב."],["4905","15","<b>כמבואר באד\"ר</b>: דר\"צ ע\"א. וראה לקו\"ת שלח מח, ב. מסעי צג, ג."],["4906","16","<b>קצת יניק' יש בחללן וכמ\"ש במ\"א</b>: ראה תו\"א קי, ב. לקו\"ת תזריע כד, א. קרח נג, א."],["4907","17","<b>ה' מלך גיאו' לבש</b>: תהלים צג, א."],["4908","18","<b>ישת חושך סתרו</b>: תהלים יח, יב."]]],[2100990302,"למעלה ג\"כ ע\"ד זה והוא בחי' ביטול רצון העליון כמ\"ש בטל<sup data-n=\"4909\">19</sup> רצונך מפני רצונו כדי שיבטל רצון אחרים וכו' וענין בחי' ביטול הרצון העליון למעלה ג\"כ היינו בחי' הביטול שלמעלה מן הדעת והוא ענין סילוק עצמותו להעלים ולהסתיר א\"ע מכל וכל בכדי שיוכל להיו' גילוי אור בהשתלשלו' גם להיו' מקור לחכמה שנק' נקודא והיינו מה שמבואר למעלה בענין העלם דגלגלתא ומה שבוקעין ויוצאי' אח\"כ בחי' שערו' להיו' מקור לחכמה כו' וזה נק' העלם העצמו' דרך כלל וז\"ש ה' מלך גיאות לבש שמתלבש בלבוש להעלים א\"ע כו' וגם נק' בחי' זו בשם עתיק<sup data-n=\"4910\">20</sup> יומין מלשון המעתיק הרים כו' וכמ\"ש המתנשא<sup data-n=\"4911\">21</sup> מימות עולם כו' שנעתק מבחי' השתלשלו' י\"ס דאצילו' שנק' יומין וכמ\"ש<sup data-n=\"4912\">22</sup> במ\"א וד\"ל.\n<b>והביטול</b> השני הוא ביטול הרצון מצד הדעת וההשגה דוקא ואתעדל\"ת זאת גורמת למעלה אתעדל\"ע בביטול רצון שמלובש בחכמה דאצי' שהוא בחי' היו\"ד כנ\"ל שנק' בשם ראשית הגילוי כנ\"ל והיינו בחי' הצמצום שלפני בחי' ההתפשטו' שידוע דא\"א הי' להיו' ההשתלשלו' בסובב וממלא בלתי הצמצום בתחלה וכענין הושיט<sup data-n=\"4913\">23</sup> אצבעו קטנה ביניהן ושרפן הרי מפני קצת גילוי יותר מדאי באצבע הקטנה שהיא היו\"ד נשרפו ונכללו במקורם כו' וזהו שרש ענין דקמיה דוקא כלא ולא לא ממש משום דהצמצום מעלים את עצמותו אבל בלא צמצום בתחלה היו בחי' לא ממש ולא כלא בכף הדמיון וד\"ל.\n<b>והנה</b> ההפרש אשר יש בין ב' מדרגו' הביטול הנ\"ל היינו במה שיש הפרש בין כתר לחכמה מאחר שזה בקוצו של יו\"ד וזה ביו\"ד כנ\"ל וידוע ההפרש<sup data-n=\"4914\">24</sup> בין הכתר לחכמה דבחכמה אמרו דבה תלוי ענין הברורי' דוקא כמאמר דבחכמה<sup data-n=\"4915\">25</sup> אתברירו משא\"כ בכתר שהוא למעלה מבחי' הברורי' כנודע והטעם הוא לפי שהחכמה מתלבשת ובאה בהשתלשלו' שיש שם בחי' עה\"ד טו\"ר כידוע ע\"כ בחכמה מברר הוא הטוב מן הרע כמו לאהפכא<sup data-n=\"4916\">26</sup> חשוכא לנהורא כו' ע\"י ביטול הרצון כנ\"ל משא\"כ בבחי' הכתר שלמעלה מן ההשתלשלו' שאין שם בחי' עה\"ד טו\"ר עדיין לא שייך שם בחי' בירור כלל מאחר שהוא ענין אהבה הטבעית שלמעלה מן הדעת ואין",[["4909","19","<b>בטל רצונך מפני רצונו</b>: אבות פ\"ד, מ\"ב."],["4910","20","<b>עתיק יומין מלשון המעתיק הרים</b>: איוב ט, ה. וראה לקו\"ת אמור לא, ד — הג\"ה מכ\"ק אדמו\"ר הצ\"צ: ועיין בזוהר ח\"ג קל\"ג, ב' ע\"פ וחסדי מאתך כו' וכתיב ובחסד עולם כו' ודף קל\"ד ב' ענין ימי קדם וימי עולם ועמ\"ש במ\"א ע\"פ ביום השמיני עצרת [לקו\"ת שמע\"צ פג, ב] בפי' אשר נשבעת לאבותינו מימי קדם ובד\"ה השמים כסאי שהתורה קדמה אלפים שנה לעולם. לקו\"ת שלח לט, ד. חוקת סז, ב. תצא לט, ג. סה\"מ תקס\"ב ח\"ב ס\"ע תקלב. תקס\"ה ח\"ב ע' תתקמא."],["4911","21","<b>המתנשא מימות עולם</b>: ע\"פ ברכת יוצר."],["4912","22","<b>וכמ\"ש במ\"א וד\"ל</b>: ראה הנסמן לעיל — עתיק יומין."],["4913","23","<b>הושיט אצבעו הקטנה</b>: סנהדרין לח, ב. תו\"ח בראשית יז, ב ובהערה 9."],["4914","24","<b>ההפרש בין הכתר לחכמה</b>: ראה ג\"כ שערי אורה סד, א. ובכ\"מ."],["4915","25","<b>דבחכמה אתברירו</b>: ראה זהר (היכלות) פקודי רנד, סע\"ב."],["4916","26","<b>לאהפכא חשוכא לנהורא</b>: ראה זהר בהקדמה ד, א."]]],[2100990303,"הרע נמצא אלא בשבירת הכלים בעץ הדעת טו\"ר כידוע שהוא דוקא ע\"י הדעת וד\"ל.\n<b>ועתה</b> יש להבין שרש ענין הה\"א שהוא בבחי' ההתפשטו' לאורך ורוחב כנ\"ל. דהנה הה\"א ראשונה שבשם הוי' הוא בחי' בינה והוא בחי' ההתפשטו' שאחר הצמצום דיו\"ד דחכמה כידוע דחו\"ב<sup data-n=\"4917\">27</sup> נק' תרין ריעין והן אותיו' י\"ה כמ\"ש בי\"ה<sup data-n=\"4918\">28</sup> ה' צור עולמי' כו' ביו\"ד<sup data-n=\"4919\">29</sup> נברא העוה\"ב שהוא מאין דחכמה ליש דבינה כמ\"ש להנחיל<sup data-n=\"4920\">30</sup> אוהבי יש כו' ולמטה באדם היינו בחי' רשפי אש שבלב בהתלהבו' שבאה דוקא מבחי' ההתבוננו' בהשגה במוח שמזה בא התפעלו' הלב כי ההתפעלו' בלב הוא בחי' ההתפשטו' כענין השמחה שהיא התפשטו' הלב והיא באה מצד בחי' התפשטו' שבמוח בהשגה שבאה במרחב דוקא וכמ\"ש אם<sup data-n=\"4921\">31</sup> הבנים שמחה דהשמחה<sup data-n=\"4922\">32</sup> היא מבחי' בינה שנק' &lt;שמב&gt;\nאם הבנים כידוע ולמעלה הוא בחי' ה\"א ראשונ' שהיא בחי' התפשטו' בסובב וממלא כו' וזה נעשה באתעדל\"ת בתשובה עילאה דוקא דהנה תשובה עילא' היא באה מעומק הלב ובינה לבא כידוע וזהו שרש ענין ויצעקו<sup data-n=\"4923\">33</sup> בצר להם כו' שהכל נק' צר ומצוק כי הרצון והתשוקה ברשפי אש מלמטה למעלה היא לעצמו' המאציל דוקא שכללו' הכל קמי' כלא חשיב ואפי' העוה\"ב וכו' נק' צר כי אינו אלא הארה מצומצמת מיו\"ד ועי\"ז נמשך מן הצמצום להיו' בחי' התפשטו' דה\"א וכמ\"ש מן<sup data-n=\"4924\">34</sup> המיצר קראתי ענני במרחב כו' מפני שאחר היציאה מן המיצר בא הוא למרחב והוא בחי' ההתפשטו' דה\"א שבאה דוקא אחר הצמצום דיו\"ד כנ\"ל וד\"ל. וענין הוי\"ו<sup data-n=\"4925\">35</sup> הוא בחי' ההמשכה דתורה וה\"א אחרונ' הוא בחי' מעשה המצות כנ\"ל.\n<b>וביאור</b> הדברים הנה ידוע דבחי' קול<sup data-n=\"4926\">36</sup> ודיבור נק' ו\"ה הוי\"ו הוא קול המשכה מן המדו' לדיבור שנק' ה\"א אחרונה כידוע והנה תחלה יש להבין שהפרש גדול יש בין אותיו' י\"ה ובין אותיו' ו\"ה, דהנה מבואר למעלה בענין י\"ה שהוא הצמצום דחכמה ואח\"כ באה בחי' ההתפשטו' דבינה והרי מבואר למעלה שא\"א שיבא בחי' התפשטו' בלתי צמצום בתחלה וא\"כ כל עיקר הצמצום בשביל שיהא התפשטו' והכל בחי' א' הוא ויובן דבר זה בתוספ' ביאור בכלל הידוע בפי' מאין ליש שהוא ענין מן ההעלם לגילוי שכלל זה כולל כל ההשתלשלו' מעילה לעילה ואמנם הנה מובן בענין זה שיוצא מן ההעלם לגילוי שכל זה עדיין הוא בבחי' העצמות של",[["4917","27","<b>דחו\"ב נק' תרין רעין</b>: ראה זהר ויקרא ד, א."],["4918","28","<b>בי\"ה ה' צור עולמי'</b>: ישעי' כו, ד."],["4919","29","<b>ביו\"ד נברא העוה\"ב</b>: מנחות כט, ב. ראה גם מאמרי אדה\"א במדבר ח\"ג ע' א'רנה."],["4920","30","<b>להנחיל אוהבי יש</b>: משלי ח, כא."],["4921","31","<b>אם הבנים שמחה</b>: תהלים קיג, ט."],["4922","32","<b>דהשמחה היא מבחי' בינה</b>: ראה תו\"א קיב, ב-ד. לקו\"ת דרושים לסוכות ושמ\"ע עט, ד. פט, א. ובכ\"מ."],["4923","33","<b>ויצעקו בצר להם</b>: תהלים קז, ו. כח."],["4924","34","<b>מן המיצר קראתי ענני במרחב</b>: תהלים קיח, ה."],["4925","35","<b>הוי\"ו הוא בחי' ההמשכה</b>: ראה תו\"א לך יג, ג. ויחי נג, ב. לקו\"ת תזריע כב, ג. כד, ב. שה\"ש מ, ג ואילך."],["4926","36","<b>קול ודיבור נק' ו\"ה</b>: ראה לקו\"ת ראה כט, ג. תו\"ח יתרו [קה\"ת — תשס\"ג] רסח, ג."]]],[2100990304,"המשפיע עדיין רק שהי' תחלה הדבר בהעלם אצלו ואח\"כ יצא הדבר לגילוי אבל אותו הדבר עצמו שהי' בהעלם הוא הדבר שמתגלה אח\"כ ואין בזה שינוי מהות כלל וכמו ע\"ד דוגמא שיוצא מן העלם המחשבה לגילוי הדיבור שאותו הדבר ממש שחשב במחשבה הוא הדבר שיגלה אח\"כ בדיבור לא ניתוסף ולא נגרע כלל וכך הוא בענין יציא' ההעלם לגילוי מחכמה לבינה שהוא מאין ליש כנ\"ל דהכל עדיין נחשב מבחי' העצמו' רק שבתחלה הי' בהעלם ואח\"כ נתגלה כנ\"ל והיינו בחי' היו\"ד והה\"א שאין לומר בהתפשטות דה\"א ענין דבר נוסף וחדש על הצמצום דיו\"ד אלא הכל בחי' א' כנ\"ל רק שמן ההעלם בא לגילוי בהתפשטו' אורך ורוחב כו' אבל בחי' ו\"ה הנה שניהם המה ענין נפרד ונבדל מן העצמות כי הרי ענין המדו' שבלב הבאי' לידי המשכה בקול הוא ענין בחי' השפעה לזולתו שאין זה נחשב כלל מבחי' העצמו' ומכ\"ש כלי הדיבור שהוא רק לזולתו שיקבל מהדיבור וכיוצא.\n<b>וזהו</b> כללות ענין ההפרש בין אותיו' י\"ה לאותיו' ו\"ה שאותיו' י\"ה המה עצמיים ואותיו' ו\"ה המה נפרדי' ואמנם מלבד זה גם בענין שינוי מהות באותיו' ו\"ה יש שינוי המהות מן המדו' לדיבור שהרי אותיו' הדיבור המה במהות נבדל לגמרי מן המדו' שבלב והגם שהקול מחבר המדו' בדיבור חיבור זה הוא כמו שאדם מתחבר בדבר נבדל ממנו לגמרי והגם שאנו רואים שהמדו' נמשכי' אחר המדו' אם המדה של אהבה יהיו נמשכי' דברי אהבה כו' הנה זהו עפ\"י הקול המחבר את המדו' להיו' מלובשי' בדיבור אבל מצד הדיבור הנה נשתנה מהו' המדו' להיו' נשמעי' במהו' קול הבל הדיבור שמורכב מאש רוח מים גשמיים כידוע וד\"ל.\n<b>וכך</b> יובן הנמשל למעלה באותיו' &lt;שמג&gt;\nו\"ה העליוני' שהוי\"ו הוא בחי' המדו' דאצי' שבאי' לידי גילוי בדיבור העליון שנק' ה\"א אחרונ' דשם הוי' כנודע שמשתנים מהות המדו' כשבאין לידי דיבור משא\"כ בחי' אותיו' י\"ה דאו\"א דאצי' שנק' תרין ריעין כנ\"ל אין בהן שינוי המהו' כלל אלא רק שההעלם והצמצום בא לידי גילוי כנ\"ל וזהו שרש ענין ו\"ה שהוא ענין תורה ומצות דוקא לפי שהתורה נק' קול הממשיך אור המאציל בכלים מכלים שונים במצות שהוא ענין נבדל מן עצמו' המאציל משא\"כ בחי' י\"ה שהוא בחי' גילוי ההעלם שזהו עדיין הכל נחשב מבחי' עצמו' המאציל ועם כל זה הרי יש חיבור לאותיו' י\"ה עם אותיו' ו\"ה בשם הוי' דכללות האצי'.\n<b>וזהו</b> ענין הפסוק ולא אבה ה' אלקיך לשמוע אל בלעם כו' שהוא לפי שהוי' הוא אלקיך כנ\"ל והיינו בחי' חיבור דעצמו' המאציל בנאצלי' שהוא ע\"י שם הוי' והנה בתחלה קוצו של יו\"ד כנ\"ל שהוא בחי' העלם העצמו' ועי\"ז ולא אבה לשמוע אל בלעם שהי' מבחי' דעת דקליפ' כנ\"ל אחר ששם הוא בחי' ביטול הרצון למעלה מן הדעת כנ\"ל וד\"ל ואח\"כ י\"ה שהוא בחי' צמצום והתפשטו' דחו\"ב כנ\"ל ואח\"כ ו\"ה המשכה דתורה ומצות ויש קשר וחיבור לכללות ד' אותיו' הללו עד שתמיד יתחבר עצמו' המאציל עי\"ז וזהו שסיים כי אהבך הוי' אלקיך פי' אהבך לשון פועל יוצא שפועל בך אהבה כו' לפי שיש לו חיבור לי\"ס דאצי' ע\"י שם הוי' שבכנ\"י ע\"כ אמר כי אהבך דהא בהא תליא עד דבאתעדל\"ת אתעדל\"ע ובאתעדל\"ע אתעדל\"ת כידוע"],[2100990305,"דהיינו שאהבת ה' לישראל תלוי' באהבת כנ\"י למעלה ואהבת כנ\"י למעלה תלוי' באהבה העליונ' והוא לפי שמתחברי' ומתקשרי' יחד ע\"י שם הוי' כנ\"ל.\n<b>וזהו</b> כי אהבך הוי' אלקיך בחי' הוי' שיש בך אהבך בפועל יוצא וגם שיהא אהבת ה' אליך ולהיו' הא בהא תליא וזה קאי לנתינת טעם על תחלת הפסוק ולא אבה כו' משום שיש לך חיבור תמיד בעצמו' המאציל שלמעלה מן החכמה ע\"י שם הוי' שהוא אלקיך והטעם לזה כי אהבך כו' וד\"ל.\n<b>ויהפוך</b> ה' את הקללה לברכה כו' זדונות נעשו כזכיות כו' כמבואר למעלה. וביאור שרש ענין זה הנה תחלה יש להקדים בשרש ענין שס\"ה ל\"ת שהן למעלה מרמ\"ח מ\"ע שהרי הן בי\"ה דשמי<sup data-n=\"4927\">37</sup> עם י\"ה גי' שס\"ה כידוע והמ\"ע הן בו\"ה והטעם ידוע ומבואר<sup data-n=\"4928\">38</sup> במ\"א ע\"פ בארץ לא זרועה שנזרע שם בחי' לא דל\"ת לפי שהלאו בא קודם להן בהשתלשלות כי מפני עוצם רוממות המאציל א\"א לבא בגילוי אור עצמותו כ\"א בחי' הלאו בלבד שהוא כענין השלילה לשלול מדבר שלא מושג מהותו כמבואר במ\"א באריכו' וירדו למטה ונתלבשו בשס\"ה ל\"ת כמו לא<sup data-n=\"4929\">39</sup> תאכל חלב שבחלב א\"א לבא התגלות כו' והיינו י\"ה שהוא הצמצום שלפני ההתפשטות וכנ\"ל והנה הזדונות מעונות דשס\"ה ל\"ת כשנהפכין לזכיות והיינו ע\"י היפוך הרע לטוב הנה יבאו לבחי' שרשן בתחלה שהיו בבחי' הצמצום דלאו שקודם להן כו' וזה א\"א להיו' למעלה כ\"א ע\"י אתעדל\"ת באופן זה דוקא דהיינו שיהא גם למטה הלאו קודם להן והוא בחי' ביטול הרצון מן ההיפך בתחלה דהיינו &lt;שדמ&gt;\nכללות בחי' התשובה וידוע דבע\"ת משכי' לי' בחילא<sup data-n=\"4930\">40</sup> יתיר כמו מס\"נ בתשובה דר\"א<sup data-n=\"4931\">41</sup> בן דרודיא בפ\"מ שכלתה נפשו ממש וכך יש בחי' מס\"נ בכל תשובה מעומקא דלבא והוא הנק' בכל מאדך שהוא ענין היציאה מן הכלי שלו והכל לפי מה שהוא, ואם מה שנחשב ההתפעלות באדם זה למעלה מן הכלי שלו עדיין במי שגבוה ממנו נחשבת בבחי' כלי ע\"ז אמר בכל<sup data-n=\"4932\">42</sup> מאדך לשון יחיד מאד של כל אדם כפי מה שהוא אך שיהא למעלה מן הכלי שלו בכדי שעי\"ז אתעדל\"ע יהי' ג\"כ באופן זה שהוא בחי' ביטול הרצון העליון לצאת מן הכלי עד שלא יוכל להתצמצם כ\"א בדרך שלילה והוא הלאו שקודם להן כו' וזהו שרש היפוך הזדונות דוקא לזכיות למעלה וד\"ל. ובזה יובן שרש ענין עשרה עומקים<sup data-n=\"4933\">43</sup> הנז' בס\"י שבשביל זה אומרי' בעי\"ת<sup data-n=\"4934\">44</sup> ממעמקים קראתיך כו' כידוע.",[["4927","37","<b>דשמי עם י\"ה גי' שס\"ה</b>: בלקו\"ת פקודי ג, ב מציין: בת\"ז בהקדמה ד' ד' סע\"ב וד' ה' ע\"א (וראה בהנסמן במ\"מ לשם)."],["4928","38","<b>ומבואר במ\"א ע\"פ בארץ לא זרועה</b>: במקום הנסמן בהמ\"מ — דשמי עם י\"ה."],["4929","39","<b>לא תאכל חלב</b>: ראה ויקרא ג, יז."],["4930","40","<b>בחילא יתיר</b>: ראה זח\"א קכט, ב."],["4931","41","<b>דר\"א בן דורדיא בפ\"מ שכלתה נפשו</b>: ראה ע\"ז יז, א."],["4932","42","<b>בכל מאדך לשון יחיד</b>: ראה סה\"מ תקס\"ב ח\"א ע' קיז וע' קצה. תו\"א מקץ לט, סע\"ג ואילך. תו\"ח שמות [הוצאת קה\"ת — תשס\"ג] קמב, ד."],["4933","43","<b>עשרה עומקים הנז' בס\"י</b>: נסמן לעיל ע' תערב."],["4934","44","<b>בעשי\"ת ממעמקים קראתיך</b>: ראה לקו\"ת תצא לט, ב. נצבים נג, ב. דרושים לר\"ה נד, ג. האזינו עד, א. ברכה צה, א."]]],[2100990306,"<b>דהנה</b> ידוע דיש ג' חללי גלגלתא והן ג' מוחין חב\"ד והגלגלתא<sup data-n=\"4935\">45</sup> הוא הקרקפתא דחפיא על מוחא הרי הוא למעלה הרבה מבחי' המוחי' שבתוכו וכנ\"ל ועליו נא' מגלה<sup data-n=\"4936\">46</sup> עמוקות מני חושך לפי שי\"ס הנאצלי' הרי הם באין ונמשכין אחר בחי' הצמצום וההעלם דגלגלתא כנ\"ל דהיינו דרך בחי' שערות כו' והנה ידוע די\"ס הם באי' בהתלבשו' באורו' וכלים מחכמה שבכל ספי' ולמטה אבל בחי' הכתרים של כל ספי' וספי' הם למעלה מהתלבשו' בכלי ועליהם נא' בס\"י<sup data-n=\"4937\">47</sup> עשר ספי' בלי מה וע\"כ נק' כל בחי' כתר של כל ספי' בשם עומק כידוע והמשכת י' עומקים היינו המשכת י' כתרים לי\"ס.\n<b>ואמנם</b> מ\"ש ממעמקים ב' עומקים הענין משום דכדי להמשיך י' כתרים בהכרח שצריך לעורר מקור הראשון דהיינו בחי' עצמו' אור המאציל שלפני העלם וצמצום בחי' הגלגלתא דחפיא על מוחא כו' וזהו הנק' עומק לעומק והוא ענין י\"ס הגנוזות בעצמות המאציל וזהו ממעמקי' מעומקא דחשוכא כו' כי מ\"ש ישת<sup data-n=\"4938\">48</sup> חושך סתרו היינו בחי' העלם הגלגלתא דחפיא כו' ומעומקא דחשוכא זה היינו מעצמו' המאציל שלפני העלם וצמצום זה דגלגלתא ומשם נמשך י' עומקי' שהן י' כתרים למטה בי\"ס דאצי' שנאצלו כבר מן ההעלם הזה כו' וזהו פי' מגלה עמוקות מני חושך שמגלה מההעלם הראשון שנק' עומקא דכולא והוא נק' ג\"כ עומקא דחשוכא ומשם מגלה י' עומקי' לי\"ס וזהו מגלה עמוקות כו' וד\"ל אך ע\"י מה נמשך הי' עומקי' מי\"ס הגנוזות במאציל היינו ע\"י התשובה מעומקא דלבא בעי\"ת בבחי' בכל מאדך כנ\"ל מפני שהוא בחי' היציא' מן הכלי לגמרי שאזי חוזר האור לקדמותו ממש כו' וזהו פי' ויהפוך ה' את הקללה לברכה כו' שנתהפכו הזדונות כזכיו' ע\"י עי\"ת שאו' ממעמקים קראתיך שנתגלה האור מעומקא דכולא להפוך הקללה לברכה והזדונו' כזכיו' וכמ\"ש מחיתי<sup data-n=\"4939\">49</sup> כעב פשעיך כו' לפי שהעונות נרחצין במים טהורים מלמעלה מעלה מכל ההשתלשלו' דהיינו מעומקא דחשוכא דוקא.\n<b>ולהבין</b> ביאור וטעם לזה הנה תחלה יש להבין פי' ממעמקים קראתיך הוי' דמשמע שנמשך שם הוי' ע\"י עשרה עומקי' שממשיכי' בעי\"ת ולכאורה אינו מובן דהלא גם בלא\"ה שם הוי' נמשך בכל יום בחידוש הבריאה יש מאין כו' אך הענין הוא די\"ס האצי' הנה הם מתלבשים בכלים מכלים שונים &lt;שמה&gt;\nבפנימי' ואמצעיי' וחיצוני' וידוע שכלים החיצוני' דאצי' הוא שמלובשי' במלכו' דאצי' ובמלכו' ג\"כ יורד האור בירידה אחר ירידה בכלים מכלים שונים דהיינו בצרופי אותיו' החיצוני' שבמל' שנק' עו\"ר וכמ\"ש עור<sup data-n=\"4940\">50</sup> בעד עור כו' וכידוע אזי יוכל להיו' יניק' לחיצונים מבין צירוף לצירוף שהוא כמו בין גומא לגומא שבעור עד\"מ וכמ\"ש במ\"א<sup data-n=\"4941\">51</sup> בענין זיעתן של חיות",[["4935","45","<b>והגלגלתא הוא הקרקפתא דחפיא על מוחא</b>: ראה זהר (אדרא רבא) נשא קכח, ב."],["4936","46","<b>מגלה עמוקות מני חושך</b>: איוב יב, כב."],["4937","47","<b>בס\"י עשר ספי' בלי מה</b>: פ\"א מ\"ד."],["4938","48","<b>ישת חושך סתרו</b>: תהלים יח, יב."],["4939","49","<b>מחיתי כעב פשעיך</b>: ישעי' מד, כב."],["4940","50","<b>עור בעד עור</b>: איוב ב, ד."],["4941","51","<b>וכמ\"ש במ\"א בענין זיעתן של חיות הקדש</b>: ראה חגיגה יג, ב. וראה תו\"א לא, ב. ובכ\"מ."]]],[2100990307,"הקדש כו' וידוע דהעונות והחטאים הרי הם נאחזי' בחיצונים ששרש יניקתן הוא מבחי' עור דנוק' ויש להם שרש קצת גם באחוריים דכלים דז\"א כנ\"ל וא\"כ הרי ע\"י העונות יש קצת פגם בכלים דז\"א והגם שאין פגם באורו' כו' וכאשר צריך לרחוץ פגם העונות א\"א שירחצו אותם באור הבא מכבר בי\"ס דאצי' אחר שכבר בא בהשתלשלו' ושוכן ומלובש בכלים והם כבר נפגמו כו' ואע\"פ שלא נפגם האור מ\"מ אין ביכולתו לרחוץ מן הפגם כו' אלא צריך בהכרח שיבא אור חדש לגמרי שלא בא עדיין באצי' בהשתלשלות מעולם מההעלם לגילוי ולא נתלבש בכלים עדיין כו' ולו דוקא יש כח לרחוץ ולטהר גם הפגם שכבר נפגם וכענין אור<sup data-n=\"4942\">52</sup> חדש על ציון תאיר וכו'.\n<b>והנה</b> אור החדש הזה בהכרח שבא מלמעלה מעלה מכל ההשתלשלות שכבר נשתלשל והיינו מבחי' עצמו' המאציל שלפני העלם הגלגלתא דחפיא כו' שלא בא משם עדיין ההארה בי\"ס דאצי' כנ\"ל בענין י' עומקים שזה נק' אור חדש וע\"כ ביכולתו לטהר ולרחוץ כל פגם שכבר נאחז בהשתלשלו' כו'.\n<b>וזהו</b> פי' ממעמקים קראתיך הוי' שנמשך בחי' שם הוי' מחדש מעצמו' המאציל מעומקא דחשוכא הנ\"ל אשר עדיין לא בא מעולם בהשתלשלות בהוי\"ו די\"ס האצי' וזהו והחזירנו בתשובה שלימה לפניך דוקא לפניך ממש דהיינו לפני העלם בחי' הגלגלתא כנ\"ל והוא לפני המשכת שם הוי' אשר כבר נמשך באצי', ומה שזה נק' תשובה שלימה היינו לפי ששב האור לקדמותו ממש שלפני כל השתלשלו' כנ\"ל וזהו פי' כד<sup data-n=\"4943\">53</sup> אתכפיא סט\"א אסתלק יקרא דקדב\"ה פי' אסתלק נתעלה ונתרומם בבחי' העצמות ממש שלפני העלם וצמצום הראשון כנ\"ל והיינו ע\"י דאתכפיא סט\"א דוקא בביטול הרצון מעומקא דלבא בעי\"ת ומשום דבע\"ת הוא דמשכי לי' בחילא יתיר בכל מאדך כנ\"ל הטעם עד שגורמי' למעלה הלאו קודם להן שהוא בחי' י\"ה להיות מחדש ולכך ביכולתו לטהר ולרחוץ העונות ולהיו' הזדונו' כזכיו' ביו\"כ וד\"ל.\n<b>וזהו</b> שרש ענין לפני<sup data-n=\"4944\">54</sup> הוי' תטהרו כו'. דהנה מבואר למעלה בענין עשרה עומקי' שבעי\"ת שהן בחי' י' כתרים לי\"ס דאצי' והנה בעשרת הימים דעי\"ת נמשך בכל יום בחי' כתר אחד לספי' אחת מי' הספירות וכן בכל יום עד יו\"כ שהוא יום העשירי שהוא לנגד בחי' ספי' הכתר עצמו שהוא הכולל כל הספי' לפי שהוא ראש ומקור לכולן וע\"כ יו\"כ<sup data-n=\"4945\">55</sup> נק' קדוש הוי' כלומר מובדל משם הוי' שבנאצלי' כו' וד\"ל.",[["4942","52","<b>אור חדש על ציון תאיר</b>: נוסח (אשכנז) ברכת ק\"ש שחרית."],["4943","53","<b>כד אתכפיא סט\"א אסתלק יקרא דקב\"ה</b>: זח\"ב קכח, ב."],["4944","54","<b>לפני הוי' תטהרו</b>: אמור טז, ל."],["4945","55","<b>יו\"כ נק' קדוש הוי'</b>: ראה ישעי' נח, יג. שבת קיט, א. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתלא."]]],[2100990308,"<b>והנה</b> כל ספי' כלולה מי\"ס וא\"כ גם בחי' הכתר כלול מי\"ס ולהיות כן אחר שגם יו\"כ עצמו מכלל חשבון הימים ואדרבה בו תלוי עיקר הכפרה להיותו כלול מכולם יחד והוא כלול מי\"ס הרי לפ\"ז כל היום דיו\"כ<sup data-n=\"4946\">56</sup> מכפר עד שקיעת החמה בנעילה כו' וזהו שאמרו ז\"ל &lt;שמו&gt;\nדסוף<sup data-n=\"4947\">57</sup> היום סמוך לשק\"ה מכפר גם על עבירו' שעשה ביו\"כ עצמו לפי שבנעילה הוא סוף הזמן היותר אחרון ע\"כ בו תלוי עיקר הכפרה הכוללת הכל והוא להיותו בבחי' כתר שבכתר היותר עליון באותו יום עצמו שהוא בבחי' הכתר דהיינו יו\"כ מאחר שהיום כלול מי\"ס עד כתר שבכתר הרי בנעילה הוא בחי' כתר שבכתר ומקודם לזה הגם שכל היום הוא מבחי' הכתר אבל אין בחי' היותר כללי מכולם כמו זמן דנעילה בשק\"ה שאין עוד למעלה הימנו וכמבואר בספרי הקבלה דהעליי' דמל' בנעילה הוא בבחי' פנימי' דעתיקא כו' עילוי שאין למעלה הימנו לכך מכפר אז גם על העבירו' שעשה בשעה קודם לנעילה כו' וד\"ל.\n<b>ועיקר</b> הטעם להיות כי כמו שהכתר בכלל נבדל בערך מבחי' החכמה ושאר הספי' למטה באצי' כך למעלה לפני האצי' בחי' כתר שבכתר נבדל בערך מט\"ס שבכתר עצמו והוא זמן דנעילה כנ\"ל וע\"ז נא' לפני הוי' תטהרו לפני שם הוי' שבנאצלי' דהיינו בבחי' כתר שבכתר בנעילה שהוא מבחי' עצמו' המאציל ממש והוא הנק' לפני הוי' בכלל כי גם משם הוי' דט\"ס דכתר ג\"כ הוא נבדל בערך וע\"כ הוא נמנה בכלל עולם הא\"ס כידוע וזהו לפני הוי' תטהרו שמשם נטהרו ונרחצו כל העוונות גם שנפגמו כבר על ידם האורו' כי הרי אור חדש לגמרי מאיר מבחי' כתר שבכתר בנעילה דיו\"כ וזהו שאו' בנעילה אנכי<sup data-n=\"4948\">58</sup> אנכי אנכי מי שאנכי מוחה כו' דלא<sup data-n=\"4949\">59</sup> ידע לי' בר איהו בלחודוהי כו' וכמ\"ש במ\"א וד\"ל.",[["4946","56","<b>דיו\"כ מכפר עד שקיעת החמה בנעילה</b>: ראה תענית כו, ב — כיון דבסמוך לשקיעת החמה. ֿ. כתפילת נעילה דמיא."],["4947","57","<b>דסוף היום סמוך לשק\"ה מכפר גם</b>: ראה לקו\"ת שם — ולכן איתא במשנה פב\"ת דכריתות מי שבא על ידו ספק עבירה ביוהכ\"פ אפילו עם חשכה פטור שכל היום מכפר."],["4948","58","<b>אנכי אנכי. . מוחה</b>: ישעי' מג, כה. וראה תו\"ח שמות [הוצאת קה\"ת — תשס\"ג] רכט, ב."],["4949","59","<b>דלא ידע לי' בר איהו בלחודוהי וכמ\"ש במ\"א</b>: זח\"ג רפח, א. וראה שם קמ, ב. קכט, ב. קנט, א. פירוש המלות נה, ג. מאמרי אדה\"א דרושי חתונה ח\"ב ע' תקכא. המשך תער\"ב ע' א'קסא."]]],[2100990309,"<h3>להבין שרש ענין הקללות שבתוכחה</h3>\n<b></b><b>שבת פ' כי תבא בעזר\"ה.</b>\nשבת פ' כי תבוא\n<b>להבין</b><sup data-n=\"4950\">1</sup> שרש ענין הקללות שבתוכחה. והיה<sup data-n=\"4951\">2</sup> אם לא תשמע בקול ה' וכו' ובאו עליך כל הקללות האלה וכו' עד השמדך ועד אבדך כו' ידבק ה' בך הדבר עד כלותו אותך מעל האדמה אשר אתה בא שמה לרשתה יככה ה' כו', והיו שמיך אשר על ראשך נחשת והארץ אשר תחתיך ברזל, יתן ה' מטר ארצך אבק ועפר כו' עד סיום כל הפרשה ההיא ובסוף הפ' אמר והיה<sup data-n=\"4952\">3</sup> כאשר שש ה' כו' ונסחתם מעל האדמה אשר אתה בא שמה לרשתה.\n<b>הנה</b><sup data-n=\"4953\">4</sup> איתא בתיקונים<sup data-n=\"4954\">5</sup> בתיקונא שביעא' בראשית<sup data-n=\"4955\">6</sup> ירא בוש\"ת ודאי ווי לי' לס\"מ כד קדב\"ה תבע מיני' ומע' ממנן דילי' כל עאקו דעאקו לישראל בגלותא ואחזי לי' אגרא דלהון אי הוו אוקרין לישראל כו' ואיהו וממנן דילי' לא עבדין יקרא אלא קלנא ובג\"ד קלא נפיק כל יומא יר\"א בוש\"ת כו' ע\"ש ובסוף תיקון השמיני דעל סמ' ובת זוגי' איתמר לע\"ל כי<sup data-n=\"4956\">7</sup> שמים כעשן נמלחו והארץ כבגד תבלה.\n<b>והענין</b> הוא כי הנה נודע ענין הצמצום דשם ב\"ן שהוא בא מסיבת שבירת הכלים דז'<sup data-n=\"4957\">8</sup> מלכין קדמאין דתוהו וכמ\"ש וימלוך<sup data-n=\"4958\">9</sup> וימת כו' וירדו מהם ונפלו רפ\"ח ניצוצי' בשם ב\"ן דמל' דאצי' והוא ענין הצמצום<sup data-n=\"4959\">10</sup> דשם אלקי\"ם כידוע שהוא לצמצם ולהעלים האור האלקי כ\"כ עד שיוכל להיו' מציאת י\"ש ודבר נפרד בפ\"ע לגמרי ואם לא זה הצמצום לא הי' באפשרי להיו' מציא' דבר נפרד חוץ מאלקו' ומה גם להיו' בעל בחירה ורצון וא\"כ לא הי' מציא' שכר ועונש כלל, אבל ע\"י הצמצום שנעשה בחי' נפרד בפ\"ע להיו' בעל בחירה ורצון מעה\"ד טו\"ר יש ענין שכר ועונש, וכדי שיהי' מציאת שכר ועונש ע\"כ הוצרך לבחי' הצמצום דוקא כידוע וד\"ל.\n<b>והנה</b> גם לאחר בחי' הצמצום להסתיר האור עד שיהי' בחי' נפרד הנה יש בזה כמה מדרגות כי הנה הנבראי' שנבראו י\"ש מאי\"ן ע\"י הצמצום הן הנה בבחי' עה\"ד טו\"ר, והתערובת מטו\"ר יש בכל נברא ונברא בהכרח, וענין התערובת טו\"ר ידוע שבחי' הביטו\"ל במציאו' שנמצא בכל נבראי' העליונים וכמ\"ש וצבא<sup data-n=\"4960\">11</sup> השמים",[["4950","1","<b>להבין שרש ענין הקללות שבתוכחה</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק 1025 (קיב, א). המאמר עם כמה שינויים (וסעיפים) נדפס באוה\"ת תבוא ע' תתרצב. וראה תורת מנחם כרך ט (תשי\"ג — ח\"ג) ע' 167 סעיף יז ואילך."],["4951","2","<b>והיה אם לא תשמע בקול ה'. . עד סיום כל הפרשה ההיא</b>: תבוא כח, טו ואילך."],["4952","3","<b>והיה כאשר שש. . בא שמה לרשתה</b>: שם סג."],["4953","4","<b>הנה איתא</b>: באוה\"ת מסומן כאן סעיף א)."],["4954","5","<b>בתיקונים בתיקונא שביעא' בראשית ירא בושת</b>: תקו\"ז תיקון ז (כד, א)."],["4955","6","<b>בראשית</b>: ראה שם הקדמת תקו\"ז בתחלתה."],["4956","7","<b>כי שמים כעשן נמלחו</b>: ישעי' נא, ו."],["4957","8","<b>דז' מלכין קדמאין</b>: ראה זהר (אד\"ר נשא) קכח, א. ע\"ח שער הכללים פ\"א. שם שער (ח) ואילך. דרושי נקודות פ\"ד."],["4958","9","<b>וימלוך וימת</b>: וישלח לב, לו ואילך."],["4959","10","<b>הצמצום דשם אלקים</b>: נסמן לעיל ע' תלט."],["4960","11","<b>וצבא השמים לך משתחווי'</b>: נחמי' ט, ו."]]]]});
